window.QUESTIONS = [{"id":"w0q1","run":"2026","week":"0","wn":0,"n":1,"q":"What is Psychology?","options":["Just a social media trend","An art of living","A subject about human body","A study of cognitive processes & behavior"],"answer":[3],"explanation":"Psychology is the scientific study of mind (cognitive processes) and behavior. It is not merely an art of living or a study of the body, which belongs to biology and physiology.","rep":["2026","2025","2024"],"grp":0},{"id":"w0q2","run":"2026","week":"0","wn":0,"n":2,"q":"A broad field of study that explores a variety of questions about thoughts, feelings and actions is ____?","options":["Society","Globalization","Psychology","Social Science"],"answer":[2],"explanation":"Psychology specifically investigates thoughts, feelings and actions of individuals. Social science is a broader umbrella that also covers economics, sociology and politics, so it is less precise.","rep":["2026","2025","2024"],"grp":1},{"id":"w0q3","run":"2026","week":"0","wn":0,"n":3,"q":"Learning has been a central topic of research in ____.","options":["Chemistry","Physics","Mathematics","Psychology"],"answer":[3],"explanation":"Learning, as a relatively permanent change in behavior or knowledge due to experience, has been a core research area in psychology since the work of Ebbinghaus, Pavlov, Thorndike and others."},{"id":"w0q4","run":"2026","week":"0","wn":0,"n":4,"q":"The word Psyche means ____?","options":["Body or physique","Mind or soul","Spirituality","Hormones"],"answer":[1],"explanation":"Psychology comes from the Greek words psyche (mind or soul) and logos (study). Hence psychology originally meant the study of the mind or soul.","rep":["2026","2025","2024"],"grp":3},{"id":"w0q5","run":"2026","week":"0","wn":0,"n":5,"q":"The ____ of learning focuses on how people learn.","options":["psychology","english","chemistry","none of the given"],"answer":[0],"explanation":"The psychology of learning studies the processes by which people acquire, retain and use new knowledge, skills and behaviors."},{"id":"w0q6","run":"2026","week":"0","wn":0,"n":6,"q":"To help people to function effectively and fulfill their own unique potential\" is the aim of ____?","options":["Humanistic psychology","Evolutionary biology","Computer science","Microbiology"],"answer":[0],"explanation":"Humanistic psychology (Maslow, Rogers) emphasizes personal growth, free will and self-actualization, i.e., helping people fulfill their unique potential.","rep":["2026","2025","2024"],"grp":5},{"id":"w0q7","run":"2026","week":"0","wn":0,"n":7,"q":"Psychology is not an independent science, but dependent on other fields.","options":["True","False"],"answer":[1],"explanation":"Psychology is an independent science with its own subject matter and methods, formally established when Wundt founded the first psychology laboratory in 1879. It draws on and interacts with other fields but is not dependent on them."},{"id":"w0q8","run":"2026","week":"0","wn":0,"n":8,"q":"The study of changes in an individual's behavior during his/her lifetime is called ____.","options":["Hormonal psychology","Gender psychology","Developmental Psychology","Genetics or Heredity"],"answer":[2],"explanation":"Developmental psychology studies how behavior, cognition and emotion change across the lifespan, from infancy through old age."},{"id":"w0q9","run":"2026","week":"0","wn":0,"n":9,"q":"The study of differences and similarities in the behavior of animals of different species is called ____.","options":["Developmental psychology","Cultural psychology","Personality psychology","Comparative Psychology"],"answer":[3],"explanation":"Comparative psychology compares behavior across species to understand evolutionary and functional similarities and differences. Cultural psychology compares human cultures, not species.","rep":["2026","2025","2024"],"grp":8},{"id":"w0q10","run":"2026","week":"0","wn":0,"n":10,"q":"Humans are incapable of learning.","options":["True","False"],"answer":[1],"explanation":"Humans are highly capable learners; learning occurs throughout life through experience, practice, observation and instruction."},{"id":"w1q1","run":"2026","week":"1","wn":1,"n":1,"q":"Learning is often seen as the contiguous causal effect of ____ on behavior.","options":["blood","bone density","trauma","experience"],"answer":[3],"explanation":"Learning is defined as a relatively permanent change in behavior or behavior potential that results from experience. Trauma can affect behavior, but the general causal factor in learning is experience."},{"id":"w1q2","run":"2026","week":"1","wn":1,"n":2,"q":"In order to say that learning has occurred, a hidden change in behavior must occur.","options":["True","False"],"answer":[1],"explanation":"Learning is inferred from an observable (overt) change in behavior or performance, not a hidden one. A change that cannot be observed in any way cannot be used to say learning has occurred."},{"id":"w1q3","run":"2026","week":"1","wn":1,"n":3,"q":"Which of the following is not a mental construct?","options":["skeleton","knowledge","representations","associations"],"answer":[0],"explanation":"Knowledge, representations and associations are hypothetical mental constructs used to explain learning. A skeleton is a physical, anatomical structure, not a mental construct."},{"id":"w1q4","run":"2026","week":"1","wn":1,"n":4,"q":"Learning changes the ____ structure of the brain through the process of continuous interactions between the learner and the external environment.","options":["physical","social","biological","none of the given"],"answer":[0],"explanation":"Learning physically alters the brain (neuroplasticity), for example by forming and strengthening synaptic connections through ongoing interaction with the environment."},{"id":"w1q5","run":"2026","week":"1","wn":1,"n":5,"q":"____ shapes the learning process.","options":["Only thoughts","Only emotions","Both thoughts and emotions","Neither thoughts nor emotions"],"answer":[2],"explanation":"Learning is influenced by both cognition (attention, beliefs, reasoning) and emotion (motivation, anxiety, interest), so neither alone fully shapes it."},{"id":"w1q6","run":"2026","week":"1","wn":1,"n":6,"q":"Watson's work included the famous Little Albert experiment in which he conditioned a small child to ____ a white rat.","options":["fear","love","hate","play with"],"answer":[0],"explanation":"Watson and Rayner (1920) paired a white rat with a loud noise until Little Albert showed a conditioned fear response to the rat, demonstrating classical conditioning of emotions."},{"id":"w1q7","run":"2026","week":"1","wn":1,"n":7,"q":"Behaviorism dominated psychology for much of the early ____ century.","options":["20th","19th","18th","17th"],"answer":[0],"explanation":"Behaviorism, launched by Watson in 1913 and extended by Skinner, dominated psychology from roughly the 1910s to the 1950s, before the cognitive revolution."},{"id":"w1q8","run":"2026","week":"1","wn":1,"n":8,"q":"The state of \"conscious incompetence\" may be valuable ____ of a learning experience.","options":["at the end","in the middle","2 years after the end","at the start"],"answer":[3],"explanation":"In the conscious competence model, realizing what you do not know (conscious incompetence) motivates learning, so it is valuable at the start. Ending a learning experience still in this stage would indicate the learning failed.","rep":["2026","2025"],"grp":17},{"id":"w1q9","run":"2026","week":"1","wn":1,"n":9,"q":"Which of the following is not an outcome of effective e-learning?","options":["wider range of strategies","more reflective approach","more positive emotions towards learning","more disconnected knowledge"],"answer":[3],"explanation":"Effective e-learning should produce more connected, integrated knowledge along with broader strategies, reflection and positive emotions. Disconnected knowledge is a sign of ineffective learning."},{"id":"w1q10","run":"2026","week":"1","wn":1,"n":10,"q":"Instrumental conditioning is an example of ____ learning.","options":["sensitization","habituation","associative","meaningful"],"answer":[2],"explanation":"Instrumental (operant) conditioning involves learning an association between a behavior and its consequence, making it associative learning. Habituation and sensitization are non-associative forms of learning."},{"id":"w2q1","run":"2026","week":"2","wn":2,"n":1,"q":"The three major types of learning described by ____ psychology are classical conditioning, operant conditioning and observational learning.","options":["cognitive","behavioral","emotional","evolutionary"],"answer":[1],"explanation":"Behavioral psychology focuses on observable learning and identifies classical conditioning, operant conditioning and observational learning as its three major types."},{"id":"w2q2","run":"2026","week":"2","wn":2,"n":2,"q":"According to the view of Watson, psychology is ____.","options":["subjective","only descriptive","experimental","about internal mental processes that cannot be measured and observed"],"answer":[2],"explanation":"Watson argued psychology should be a purely objective, experimental branch of natural science aimed at predicting and controlling behavior. He rejected subjective introspection and the study of unobservable mental processes."},{"id":"w2q3","run":"2026","week":"2","wn":2,"n":3,"q":"____ is given by Ivan Pavlov.","options":["Operant conditioning","Functional conditioning","Classical conditioning","Modern conditioning"],"answer":[2],"explanation":"Pavlov discovered classical conditioning through his work with dogs salivating to a neutral stimulus paired with food. Operant conditioning is associated with Skinner."},{"id":"w2q4","run":"2026","week":"2","wn":2,"n":4,"q":"The process by which organisms learn to respond to certain stimuli but not to others is known as ____.","options":["stimulus generalization","stimulus appreciation","stimulus discrimination","stimulus differentiation"],"answer":[2],"explanation":"Stimulus discrimination is learning to respond only to the conditioned stimulus and not to similar stimuli. Stimulus generalization is the opposite, responding to stimuli similar to the conditioned stimulus."},{"id":"w2q5","run":"2026","week":"2","wn":2,"n":5,"q":"Higher-order conditioning is intrinsically weaker than its first-order counterpart.","options":["True","False"],"answer":[0],"explanation":"In higher-order conditioning a new neutral stimulus is paired with an already conditioned stimulus rather than the unconditioned stimulus, so the resulting response is weaker and extinguishes more easily."},{"id":"w2q6","run":"2026","week":"2","wn":2,"n":6,"q":"____ is the process of gradually changing the quality of a response.","options":["Shaping","Modeling","Cueing","Shifting"],"answer":[0],"explanation":"Shaping reinforces successive approximations of a target behavior, gradually changing the response until the desired behavior is reached. Modeling involves learning by observing others.","rep":["2026","2023"],"grp":25},{"id":"w2q7","run":"2026","week":"2","wn":2,"n":7,"q":"The works of ____ were instrumental in engendering the dramatic shift from behaviorism to cognitive theories.","options":["Edward C. Tolman","Jean Piaget","German Gestalt","All of the given"],"answer":[3],"explanation":"Tolman's cognitive maps, Piaget's theory of cognitive development and the German Gestalt psychologists' work on insight and perception all emphasized internal mental processes, helping drive the shift to cognitive theories."},{"id":"w2q8","run":"2026","week":"2","wn":2,"n":8,"q":"____ intelligence is the ability to perceive the visual-spatial world accurately and involves sensitivity to color, line, shape, form, space, and the potential for recognizing and manipulating the patterns of spaces.","options":["Interpersonal","Spatial","Bodily-kinesthetic","Linguistic"],"answer":[1],"explanation":"In Gardner's theory of multiple intelligences, spatial intelligence is the ability to perceive and manipulate visual-spatial information, as seen in artists, architects and navigators."},{"id":"w2q9","run":"2026","week":"2","wn":2,"n":9,"q":"Sternberg proposed his theory in 1985 as an alternative to the idea of the ____.","options":["general intelligence factor","multiple intelligences","specific intelligence factor","unconscious intelligence"],"answer":[0],"explanation":"Sternberg's triarchic theory (analytical, creative and practical intelligence) was proposed as an alternative to Spearman's single general intelligence factor (g)."},{"id":"w2q10","run":"2026","week":"2","wn":2,"n":10,"q":"Which of the following is not a kind of product in the structure of intellect model?","options":["symbolic","classes","systems","implications"],"answer":[0],"explanation":"In Guilford's structure of intellect model, the products are units, classes, relations, systems, transformations and implications. Symbolic is a type of content, not a product."},{"id":"w3q1","run":"2026","week":"3","wn":3,"n":1,"q":"The connections between nerves cells are called ____.","options":["systems","syntaxes","neurons","synapses"],"answer":[3],"explanation":"Synapses are the junctions where one neuron communicates with another. Neurons are the nerve cells themselves, not the connections between them."},{"id":"w3q2","run":"2026","week":"3","wn":3,"n":2,"q":"In order to create a ____, information must be changed into a usable form, which occurs through a process known as encoding.","options":["past memory","new imagination","new memory","past imagination"],"answer":[2],"explanation":"Encoding is the first stage of memory formation, transforming incoming information into a form that can be stored as a new memory."},{"id":"w3q3","run":"2026","week":"3","wn":3,"n":3,"q":"Calling back the stored information in response to some cue for use in a process or activity is called ____.","options":["Retrieval","Recall","Recollection","All of the given"],"answer":[3],"explanation":"Retrieval, recall and recollection all refer to accessing stored information from memory in response to a cue, so all of the given terms apply."},{"id":"w3q4","run":"2026","week":"3","wn":3,"n":4,"q":"For many with ____ deficits, reading facial expressions and knowing how to respond are confusing daily challenges.","options":["memory","intelligence","social cognition","biological cognition"],"answer":[2],"explanation":"Social cognition covers how people perceive, interpret and respond to social information such as facial expressions. Deficits in it, as seen in some autism spectrum conditions, make reading emotions and responding appropriately difficult."},{"id":"w3q5","run":"2026","week":"3","wn":3,"n":5,"q":"The Information Processing View of Learning assumes that there are limits to how much information can be processed at each stage.","options":["True","False"],"answer":[0],"explanation":"The information processing view treats the mind like a system with limited capacity at each stage, for example short-term memory holding only about 7 plus or minus 2 items."},{"id":"w3q6","run":"2026","week":"3","wn":3,"n":6,"q":"The Information Processing View of Learning assumes that information process is involved in ____","options":["forgetting","remembering","perceiving","All of the given"],"answer":[3],"explanation":"The information processing view holds that all cognitive activities, including perceiving, remembering and forgetting, involve processing information."},{"id":"w3q7","run":"2026","week":"3","wn":3,"n":7,"q":"The capacity of the sensory register is ____.","options":["very small","very large","7+/-2 chunks","unlimited"],"answer":[1],"explanation":"The sensory register briefly holds a very large amount of incoming sensory information, though only for a fraction of a second to a few seconds. The 7 plus or minus 2 chunks limit applies to short-term memory, not the sensory register."},{"id":"w3q8","run":"2026","week":"3","wn":3,"n":8,"q":"Most children do not begin to engage in the process of rehearsal on their own until about age ____.","options":["seven","two","thirteen","one"],"answer":[0],"explanation":"Research (e.g., Flavell and colleagues) shows that children rarely use spontaneous rehearsal as a memory strategy before about age seven, after which it becomes common."},{"id":"w3q9","run":"2026","week":"3","wn":3,"n":9,"q":"____ provides an interface between the sub-systems of working memory and the part of long term memory specialized for episodic memory.","options":["Phonological loop","Visuo-spatial sketchpad","Retrieval buffer","Episodic buffer"],"answer":[3],"explanation":"Baddeley added the episodic buffer to his working memory model in 2000 as a limited-capacity store that integrates information from the phonological loop, visuo-spatial sketchpad and long-term episodic memory."},{"id":"w3q10","run":"2026","week":"3","wn":3,"n":10,"q":"Memories of specific episodes of one's life refers to ____.","options":["declarative memory","experimental episodic memory","autobiographical episodic memory","procedural memory"],"answer":[2],"explanation":"Autobiographical episodic memory stores personally experienced events from one's own life. Declarative memory is the broader category, and procedural memory concerns skills and how to do things."},{"id":"w4q1","run":"2026","week":"4","wn":4,"n":1,"q":"____ thinking is the ability to create mental representations of objects, places, events, or people in your mind.","options":["General","Creative","Divergent","Symbolic"],"answer":[3],"explanation":"Symbolic thinking means using symbols such as images, words, and concepts to represent things that are not physically present. Creative and divergent thinking are about generating novel ideas, not mental representation itself."},{"id":"w4q2","run":"2026","week":"4","wn":4,"n":2,"q":"We compare new information to our ____ of the person, place, or thing, so we know how to categorize the new information mentally.","options":["protofit","protobite","prototype","none of the given"],"answer":[2],"explanation":"A prototype is the most typical or best example of a category, and new items are categorized by how closely they resemble it. The other options are not real psychological terms."},{"id":"w4q3","run":"2026","week":"4","wn":4,"n":3,"q":"Which of the following is not true?","options":["Thinking is a higher mental process","Thinking is a sub-vocal talking","Thinking is fulfilling a need or problem solving","Thinking is only done in verbal symbols"],"answer":[3],"explanation":"Thinking uses many kinds of symbols, including images, concepts, and non-verbal representations, not only words. The other statements are standard descriptions of thinking (a higher mental process, sub-vocal speech in behaviorist accounts, and goal-directed problem solving)."},{"id":"w4q4","run":"2026","week":"4","wn":4,"n":4,"q":"Mental images are ____.","options":["Auditory","Visual","Gustatory","All of the given"],"answer":[3],"explanation":"Mental imagery can occur in any sensory modality: we can imagine sights, sounds, tastes, smells, and touch. So auditory, visual, and gustatory images are all mental images."},{"id":"w4q5","run":"2026","week":"4","wn":4,"n":5,"q":"____ organize complex phenomena into simpler, easily understandable, and usable categories and help to solve our problems.","options":["Concepts","Propositions","Constructs","Components"],"answer":[0],"explanation":"Concepts are mental categories that group objects, events, or ideas sharing common features, which simplifies complex information. Propositions are statements relating concepts, not the categories themselves."},{"id":"w4q6","run":"2026","week":"4","wn":4,"n":6,"q":"The lowermost level of Bloom's taxonomy is ____.","options":["remember","apply","understand","analyze"],"answer":[0],"explanation":"In the revised Bloom's taxonomy the order from lowest to highest is remember, understand, apply, analyze, evaluate, create. Remembering (recalling facts) is the base level."},{"id":"w4q7","run":"2026","week":"4","wn":4,"n":7,"q":"The psychomotor domain of the Bloom's taxonomy is concerned with ____.","options":["Biological makeup","Thoughts and beliefs","Feelings and emotions","Skilled behavior"],"answer":[3],"explanation":"The psychomotor domain covers physical movement, coordination, and motor skills, i.e. skilled behavior. Thoughts belong to the cognitive domain and feelings to the affective domain."},{"id":"w4q8","run":"2026","week":"4","wn":4,"n":8,"q":"Which of the following is an example of meta-cognition skills?","options":["Ignoring your limits","Self-monitoring","Skimming all important information","All of the given"],"answer":[1],"explanation":"Metacognition is thinking about one's own thinking, and self-monitoring (checking your own understanding and progress) is a core metacognitive skill. Ignoring your limits is the opposite of metacognitive awareness, so 'all of the given' cannot be right."},{"id":"w4q9","run":"2026","week":"4","wn":4,"n":9,"q":"____ critical thinking skill helps you analyze and process information to come to an unbiased conclusion.","options":["Open-mindedness","Self-regulation","Self-control","Observation"],"answer":[0],"explanation":"Open-mindedness means setting aside assumptions and considering evidence and viewpoints fairly, which is what allows an unbiased conclusion. Observation helps gather information but does not by itself guard against bias."},{"id":"w4q10","run":"2026","week":"4","wn":4,"n":10,"q":"The inspiration phase of the creative thinking process refers to the ____ stage.","options":["Incubation","Insight","Evaluation","Preparation"],"answer":[3],"explanation":"In the course's model, the inspiration phase is the preparation stage, where the person becomes interested in a problem and gathers information and ideas about it. Incubation follows, when ideas are processed unconsciously.","note":"Ambiguous: in Wallas's classic model, the 'aha' moment of inspiration is usually equated with illumination/insight, not preparation. The key follows the course slides' terminology."},{"id":"w5q1","run":"2026","week":"5","wn":5,"n":1,"q":"Which of the following is true about motivation?","options":["It is a physical impulse","It is an external process","It has a willingness to activate but not channel the attitudes of learners","None of the given"],"answer":[3],"explanation":"Motivation is an internal psychological process that both activates and directs (channels) behavior. It is not merely a physical impulse, not purely external, and it does channel behavior, so none of the statements is true."},{"id":"w5q2","run":"2026","week":"5","wn":5,"n":2,"q":"The term \"motivation\" comes from a ____ word.","options":["Greek","Latin","Hindi","Bengali"],"answer":[1],"explanation":"Motivation derives from the Latin word 'movere', meaning to move. It reflects the idea that motivation is what moves a person to act."},{"id":"w5q3","run":"2026","week":"5","wn":5,"n":3,"q":"It is called extrinsic motivation if causal factor is ____.","options":["curiosity","social pressure","self-satisfaction","needs"],"answer":[1],"explanation":"Extrinsic motivation comes from outside the person, such as rewards, punishments, or social pressure. Curiosity and self-satisfaction are internal sources, i.e. intrinsic motivation."},{"id":"w5q4","run":"2026","week":"5","wn":5,"n":4,"q":"____ motivation is considered to be more crucial for students as it is associated with deep learning, better performance and self-efficacy.","options":["Intrinsic","Extrinsic","Introjected regulation","None of the given"],"answer":[0],"explanation":"Intrinsic motivation, doing something for its own interest and enjoyment, is linked to deeper processing, persistence, and stronger self-efficacy. Extrinsic and introjected (guilt- or ego-driven) motivation tend to produce more surface-level learning."},{"id":"w5q5","run":"2026","week":"5","wn":5,"n":5,"q":"____ proposed that there are three primary drives that drive human behavior.","options":["Hull","Watson","Piaget","Gestalt"],"answer":[0],"explanation":"Clark Hull's drive-reduction theory holds that behavior is driven by primary biological drives (such as hunger, thirst, and sex) that create tension the organism seeks to reduce. Watson, Piaget, and the Gestalt school did not propose a drive theory of motivation."},{"id":"w5q6","run":"2026","week":"5","wn":5,"n":6,"q":"Expectancy Theory of Motivation was developed by ____.","options":["Vroom","Hull","Murray","None of the given"],"answer":[0],"explanation":"Victor Vroom proposed expectancy theory in 1964, stating that motivation depends on expectancy, instrumentality, and valence. Hull is associated with drive theory and Murray with the theory of psychogenic needs."},{"id":"w5q7","run":"2026","week":"5","wn":5,"n":7,"q":"An example of ____ is thinking, \"If I work hard I can achieve the targets my boss has set for me\".","options":["purposeful","valence","instrumentality","expectancy"],"answer":[3],"explanation":"Expectancy is the belief that effort will lead to successful performance. Instrumentality would be the belief that performance leads to a reward, and valence is how much the reward is valued."},{"id":"w5q8","run":"2026","week":"5","wn":5,"n":8,"q":"In SMART goals, T stands for ____.","options":["Temporary","Time-based","Tough","Testing"],"answer":[1],"explanation":"SMART stands for Specific, Measurable, Achievable, Relevant, and Time-based (or time-bound). A deadline gives the goal urgency and a point at which to evaluate progress."},{"id":"w5q9","run":"2026","week":"5","wn":5,"n":9,"q":"Friendship is a ____ need in Maslow's hierarchy.","options":["Love and belonging","Esteem","Physiological","Safety"],"answer":[0],"explanation":"Maslow's third level, love and belonging, covers friendship, intimacy, family, and social connection. Esteem needs concern respect and recognition, not affiliation."},{"id":"w5q10","run":"2026","week":"5","wn":5,"n":10,"q":"____ theory differentiates between autonomous motivation and controlled motivation.","options":["Arousal","Goal-setting","Need hierarchy","Self-determination"],"answer":[3],"explanation":"Deci and Ryan's self-determination theory distinguishes autonomous motivation (acting from genuine choice and interest) from controlled motivation (acting from external pressure or internal guilt). The other theories do not make this distinction."},{"id":"w6q1","run":"2026","week":"6","wn":6,"n":1,"q":"According to Daniel Goleman, ____ component of emotional intelligence focuses on how we handle relationships with others.","options":["self-awareness","motivation","empathy","emotional regulation"],"answer":[2],"explanation":"Among the options given, empathy is the only interpersonal component: it is the ability to understand others' feelings, which underlies how we relate to them. Self-awareness, motivation, and emotional regulation are intrapersonal components.","note":"Ambiguous: in Goleman's model, handling relationships is most directly the 'social skills' component; empathy is the closest option offered here."},{"id":"w6q2","run":"2026","week":"6","wn":6,"n":2,"q":"Emotional intelligence can be considered a type of ____ intelligence.","options":["academic","genetic","social","external"],"answer":[2],"explanation":"Salovey and Mayer originally defined emotional intelligence as a subset of social intelligence, involving the ability to monitor one's own and others' emotions. It is not academic (IQ-type) intelligence."},{"id":"w6q3","run":"2026","week":"6","wn":6,"n":3,"q":"Noticing a difficult emotion and slowing down or resisting any impulsive action that may follow highlights ____ component of emotional intelligence.","options":["Self-regulation","Motivation","Emotional literacy","Empathy"],"answer":[0],"explanation":"Self-regulation is the ability to manage one's emotions and control impulses rather than reacting immediately. Empathy concerns others' feelings, and motivation concerns drive toward goals."},{"id":"w6q4","run":"2026","week":"6","wn":6,"n":4,"q":"The following are signs of emotional intelligence, except ____.","options":["strong sense of curiosity","holding onto mistakes","ability to manage emotions in difficult situations","self-confidence"],"answer":[1],"explanation":"Emotionally intelligent people learn from mistakes and move on rather than dwelling on them. Curiosity, emotional management under stress, and self-confidence are all commonly listed signs of high EI."},{"id":"w6q5","run":"2026","week":"6","wn":6,"n":5,"q":"Perceiving emotions means ____.","options":["Ignoring signals","Understanding only what somebody is saying to you","Understanding only somebody's facial expression","Understanding both verbal and nonverbal signals"],"answer":[3],"explanation":"Perceiving emotions, the first branch of the Mayer-Salovey model, involves accurately reading emotional cues from words as well as body language, tone, and facial expressions. Relying on only one channel misses much of the emotional information."},{"id":"w6q6","run":"2026","week":"6","wn":6,"n":6,"q":"____ suggests that 10 distinct components provide the scaffolding of emotionally and socially intelligent behaviors:","options":["Bar-On","Goleman","Salovey","Mayer"],"answer":[0],"explanation":"Reuven Bar-On's model of emotional-social intelligence identifies 10 key components (such as self-regard, empathy, stress tolerance, and impulse control) plus facilitators. Goleman's model has five components, and Salovey and Mayer describe four branches."},{"id":"w6q7","run":"2026","week":"6","wn":6,"n":7,"q":"Which of the following is a facilitator of EQ?","options":["optimism","happiness","independence","all of the given"],"answer":[3],"explanation":"In Bar-On's model, optimism, happiness, independence, self-actualization, and social responsibility are treated as facilitators that support emotionally intelligent behavior. Since all three listed qualities are facilitators, 'all of the given' is correct.","note":"PDF key is internally inconsistent: it reads 'Ans. a= all of the given', but option a is 'optimism' and 'all of the given' is option d. The answer text 'all of the given' (index 3) was used."},{"id":"w6q8","run":"2026","week":"6","wn":6,"n":8,"q":"____ is a strategy for improving one's self-awareness.","options":["rejecting feedback","using critical self-talk daily","developing a fixed mindset","pursuing one's passion"],"answer":[3],"explanation":"Pursuing one's passion helps people discover what truly matters to them, their strengths, and their values, which builds self-awareness. Rejecting feedback, harsh self-talk, and a fixed mindset all block honest self-reflection."},{"id":"w6q9","run":"2026","week":"6","wn":6,"n":9,"q":"Having students create autobiographies is an example of creating opportunities for ____.","options":["emotional labor","emotional contagion","metacognition","none of the given"],"answer":[2],"explanation":"Writing an autobiography requires students to reflect on their own experiences, feelings, and thought processes, which is a metacognitive activity. Emotional labor and emotional contagion concern managing displayed emotions and catching others' emotions, respectively."},{"id":"w6q10","run":"2026","week":"6","wn":6,"n":10,"q":"Which of the following is not true about management of emotions?","options":["It is essentially a private act","It is directly regulated by others","It is influenced by cultural norms","It is influenced by what society defines as appropriate to feel and express"],"answer":[1],"explanation":"Emotion management is essentially carried out by the individual, though shaped by cultural and social display rules about what is appropriate to feel and express. It is influenced by others but not directly regulated by them, so that statement is the false one."},{"id":"w7Aq1","run":"2026","week":"7A","wn":7,"n":1,"q":"Which of the following is false about learning according to Gagne’s definition?","options":["It is a change in human disposition","It persists over a period of time","It is simply ascribable to processes of growth","None of the above"],"answer":[2],"explanation":"Gagne defined learning as a change in human disposition or capability that persists over time and is NOT simply ascribable to processes of growth (maturation). So saying it is simply due to growth is the false statement.","rep":["2026","2025"],"grp":70},{"id":"w7Aq2","run":"2026","week":"7A","wn":7,"n":2,"q":"Manual or physical skills come under ____ component of Bloom’s taxonomy.","options":["Cognitive","Affective","Psychomotor","Physical"],"answer":[2],"explanation":"Bloom's taxonomy has three domains: cognitive (knowledge), affective (attitudes and feelings) and psychomotor (manual or physical skills). 'Physical' is not one of the named domains.","rep":["2026","2025"],"grp":71},{"id":"w7Aq3","run":"2026","week":"7A","wn":7,"n":3,"q":"Reflection, learning and education was explored by ____.","options":["Carl Rogers","John Watson","Benjamin Bloom","John Dewey"],"answer":[3],"explanation":"John Dewey wrote extensively on reflective thinking and its role in learning and education (e.g., How We Think, Democracy and Education). Watson was a behaviorist and Rogers a humanistic psychologist.","rep":["2026","2025"],"grp":72},{"id":"w7Aq4","run":"2026","week":"7A","wn":7,"n":4,"q":"The principles of ____ refer to how close in time two events must be for a bond to be formed.","options":["behavior","reinforcement","repetition","contiguity"],"answer":[3],"explanation":"Contiguity is the principle that events occurring close together in time (and space) become associated. Reinforcement concerns consequences that strengthen a response, not timing between paired events.","rep":["2026","2025"],"grp":73},{"id":"w7Aq5","run":"2026","week":"7A","wn":7,"n":5,"q":"____ gives information to learners about their success or failure concerning the task at hand.","options":["Cognitive feedback","Emotional feedback","Reinforcement","Physical feedback"],"answer":[0],"explanation":"Cognitive feedback informs learners about whether they succeeded or failed on a task, helping them correct their understanding. Reinforcement strengthens behavior through consequences rather than conveying task information.","rep":["2026","2025"],"grp":74},{"id":"w7Aq6","run":"2026","week":"7A","wn":7,"n":6,"q":"The ____ orientation to learning has a quality of personal involvement—the whole person in both feeling and cognitive aspects being in the learning event.","options":["behavioral","cognitive","humanistic","social"],"answer":[2],"explanation":"The humanistic orientation (Carl Rogers) emphasises whole-person, self-initiated learning involving both feelings and cognition. The cognitive orientation focuses mainly on mental processes rather than the whole person.","rep":["2026","2025"],"grp":75},{"id":"w7Aq7","run":"2026","week":"7A","wn":7,"n":7,"q":"Learning through play is ____ learning.","options":["primary","secondary","passive","active"],"answer":[3],"explanation":"In play, learners explore, manipulate and engage directly with materials and ideas, which makes it a form of active learning rather than passive reception of information.","rep":["2026","2025"],"grp":76},{"id":"w7Aq8","run":"2026","week":"7A","wn":7,"n":8,"q":"People with ____ learning style are prone to sorting their ideas after speaking, rather than thinking ideas through before.","options":["logical","solitary","visual","auditory"],"answer":[3],"explanation":"Auditory (aural/verbal) learners process information by hearing and talking, so they often work out their ideas by speaking them aloud. Solitary learners, by contrast, prefer to think things through alone.","rep":["2026","2025"],"grp":77},{"id":"w7Aq9","run":"2026","week":"7A","wn":7,"n":9,"q":"Which of the following statements is false?","options":["Effective instruction is static","Effective instruction is eclectic","Effective instruction is generative","Effective instruction is interactive"],"answer":[0],"explanation":"Effective instruction is dynamic, drawing on multiple approaches (eclectic), encouraging learners to generate knowledge, and involving interaction. Describing it as static is therefore false.","rep":["2026","2025"],"grp":78},{"id":"w7Aq10","run":"2026","week":"7A","wn":7,"n":10,"q":"In ADDIE model, I stand for ____.","options":["instruction","implementation","integration","induction"],"answer":[1],"explanation":"ADDIE stands for Analysis, Design, Development, Implementation and Evaluation, a common instructional design model. 'Instruction' is a tempting guess but is not part of the acronym.","rep":["2026","2025"],"grp":79},{"id":"w7Bq1","run":"2026","week":"7B","wn":7,"n":1,"q":"Simon defined learning as changes in a system that result in ____ over time on tasks similar to those done previously.","options":["boredom","decreased anxiety","improved performance","reduced performance"],"answer":[2],"explanation":"Herbert Simon defined learning as changes in a system that make it perform the same or similar tasks more effectively the next time, i.e. improved performance over time."},{"id":"w7Bq2","run":"2026","week":"7B","wn":7,"n":2,"q":"Robert Gagne defined learning as ____.","options":["a change in human disposition or capacity","a change that persists over a period of time","a change not simply ascribable to processes of growth","all of the given"],"answer":[3],"explanation":"Gagne's definition has all three parts: learning is a change in human disposition or capability, it persists over a period of time, and it is not simply ascribable to processes of growth."},{"id":"w7Bq3","run":"2026","week":"7B","wn":7,"n":3,"q":"Psychomotor skills are ____ skills.","options":["cognitive","spiritual","mental","physical"],"answer":[3],"explanation":"The psychomotor domain of Bloom's taxonomy covers physical (manual or motor) skills such as movement, coordination and manipulation; cognitive and mental skills belong to the cognitive domain."},{"id":"w7Bq4","run":"2026","week":"7B","wn":7,"n":4,"q":"Returning to experience refers to ____.","options":["attending to feelings","re-examining experience in the light of one's intent and existing knowledge","using helpful feelings and removing obstructive ones","recalling or detailing salient events"],"answer":[3],"explanation":"In Boud, Keogh and Walker's reflection model, returning to experience means recalling or detailing the salient events. Attending to feelings (using helpful ones, removing obstructive ones) and re-evaluating the experience are the later stages."},{"id":"w7Bq5","run":"2026","week":"7B","wn":7,"n":5,"q":"Which of the following assumptions does not come under the behaviorist orientation to learning?","options":["Differences between individuals are important as they will affect learning","Observable behavior rather than internal thought processes are the focus of study.","Environment shapes one's behavior","The principle of contiguity is central"],"answer":[0],"explanation":"Behaviorism focuses on observable behavior, holds that the environment shapes behavior, and treats contiguity (and reinforcement) as central. Emphasising individual differences is not one of its core assumptions."},{"id":"w7Bq6","run":"2026","week":"7B","wn":7,"n":6,"q":"Reinforcement can come through sharing of results rather than a reward.","options":["True","False"],"answer":[0],"explanation":"True. Reinforcement does not have to be a tangible reward: sharing results or giving feedback on performance can also strengthen the desired behavior."},{"id":"w7Bq7","run":"2026","week":"7B","wn":7,"n":7,"q":"____ has contributed to the humanistic orientations to learning.","options":["linguistic","kinesthetic","visual","Carl Rogers"],"answer":[3],"explanation":"Carl Rogers, together with Abraham Maslow, is a key figure of the humanistic orientation, which stresses self-directed, experiential learning and personal growth. The other options are learning styles, not contributors."},{"id":"w7Bq8","run":"2026","week":"7B","wn":7,"n":8,"q":"In the process of learning, which of the following is not a component of output?","options":["certification","attitude change","knowledge enhancement","training plan"],"answer":[3],"explanation":"Outputs are the results of learning, such as certification, attitude change and knowledge enhancement. A training plan is an input or part of the process, not an output."},{"id":"w7Bq9","run":"2026","week":"7B","wn":7,"n":9,"q":"Ambience, space and decorum do not affect learning.","options":["True","False"],"answer":[1],"explanation":"False. The physical learning environment, including ambience, space and decorum, affects attention, comfort and motivation, and therefore affects learning."},{"id":"w7Bq10","run":"2026","week":"7B","wn":7,"n":10,"q":"Role-playing can motivate ____ type of learners effectively.","options":["solitary","social","reading/writing","logical/analytical"],"answer":[1],"explanation":"Role-play is an interactive, group-based activity, so it suits social (interpersonal) learners who learn best by working with others."},{"id":"w8q1","run":"2026","week":"8","wn":8,"n":1,"q":"The word ‘pedagogy’ has been derived from the ____ word “pedagogue”.","options":["Latin","Sanskrit","Greek","English"],"answer":[2],"explanation":"Pedagogy comes from the Greek paidagogos (pais, child + agogos, leader), originally the person who led children to school. It is not of Latin origin."},{"id":"w8q2","run":"2026","week":"8","wn":8,"n":2,"q":"Which of the following statements is not true about pedagogy?","options":["It is a method or way of teaching","It is derived from the Greek word “pedagogue”","It helps a teacher understand how learning should be facilitated.","It harms the quality of teaching and learning."],"answer":[3],"explanation":"Pedagogy is the method and practice of teaching; it derives from Greek and guides how teachers facilitate learning. Good pedagogy improves, rather than harms, the quality of teaching and learning."},{"id":"w8q3","run":"2026","week":"8","wn":8,"n":3,"q":"Pedagogy can enhance the student-teacher relationship.","options":["True","False"],"answer":[0],"explanation":"A well-chosen pedagogy builds understanding, engagement and communication between teacher and students, thereby strengthening the student-teacher relationship."},{"id":"w8q4","run":"2026","week":"8","wn":8,"n":4,"q":"____ learning is based on the model that knowledge can be created within a population where members actively interact by sharing experiences and take on asymmetry roles.","options":["integrative","inquiry-based","collaborative","constructivist"],"answer":[2],"explanation":"Collaborative learning holds that knowledge is co-created within a group whose members interact, share experiences and take on different (asymmetric) roles. Constructivism is broader and need not involve group interaction."},{"id":"w8q5","run":"2026","week":"8","wn":8,"n":5,"q":"The Pedagogical Model provides an overview of the learning cycle and breaks it down into ____ domains or phases of instruction.","options":["five","three","two","seven"],"answer":[0],"explanation":"As taught in the lecture, the Pedagogical Model divides the learning cycle into five domains or phases of instruction (commonly listed as engage, explore, explain, elaborate and evaluate)."},{"id":"w8q6","run":"2026","week":"8","wn":8,"n":6,"q":"Which of the following is not a type of inquiry-based approach?","options":["confrontation","structure","guided","open"],"answer":[0],"explanation":"The recognised levels of inquiry-based learning are confirmation, structured, guided and open inquiry. 'Confrontation' is a distractor resembling 'confirmation' and is not one of them."},{"id":"w8q7","run":"2026","week":"8","wn":8,"n":7,"q":"In experiential learning, students are engaged ____.","options":["intellectually","soulfully","socially","all of the given"],"answer":[3],"explanation":"Experiential learning involves the whole person, engaging learners intellectually, emotionally (soulfully), socially and physically through direct experience and reflection."},{"id":"w8q8","run":"2026","week":"8","wn":8,"n":8,"q":"____ stage of experiential theory by Kolb focuses on planning.","options":["concrete experience","abstract conceptualization","reflective observation","active experimentation"],"answer":[3],"explanation":"In Kolb's cycle, active experimentation is where learners plan and try out what they have learned in new situations. Abstract conceptualization is about forming concepts and conclusions, not planning action."},{"id":"w8q9","run":"2026","week":"8","wn":8,"n":9,"q":"People with a ____ learning style can often act on “gut feeling” and will rely on others' analysis rather than their own.","options":["accommodating","converging","diverging","assimilating"],"answer":[0],"explanation":"Kolb's accommodating (doing and feeling) style is hands-on and intuitive; such learners act on gut feeling and lean on others' analysis. Assimilators, by contrast, prefer careful logical analysis of their own."},{"id":"w8q10","run":"2026","week":"8","wn":8,"n":10,"q":"According to the ____ principle, students learn better from animation and narration than from animation and on-screen text.","options":["multimedia","modality","coherence","temporal contiguity"],"answer":[1],"explanation":"Mayer's modality principle states that presenting words as spoken narration rather than on-screen text with graphics reduces visual overload by using both auditory and visual channels. The multimedia principle concerns words plus pictures versus words alone."},{"id":"w9q1","run":"2026","week":"9","wn":9,"n":1,"q":"E-learning is any form of ____.","options":["teaching","training","tutoring","all of the given"],"answer":[3],"explanation":"E-learning covers any form of teaching, training or tutoring delivered through electronic media, so all the listed options apply."},{"id":"w9q2","run":"2026","week":"9","wn":9,"n":2,"q":"____ is a feature of e-learning.","options":["difficulty in access","user friendliness","social injustice","closed learning"],"answer":[1],"explanation":"E-learning is designed to be user-friendly, flexible and easily accessible. The other options describe the opposite of what e-learning aims for."},{"id":"w9q3","run":"2026","week":"9","wn":9,"n":3,"q":"E-learning is a synonym of audio-visual learning, multimedia learning, and distance learning.","options":["True","False"],"answer":[1],"explanation":"E-learning overlaps with audio-visual, multimedia and distance learning but is not synonymous with them; each is a distinct concept (e.g., distance learning can be paper-based and multimedia learning can occur face to face)."},{"id":"w9q4","run":"2026","week":"9","wn":9,"n":4,"q":"Which of the following is not a type of e-learning?","options":["text-driven","interactive","simulation","physical"],"answer":[3],"explanation":"Types of e-learning include text-driven, interactive and simulation-based courses. 'Physical' learning is not delivered electronically, so it is not a type of e-learning."},{"id":"w9q5","run":"2026","week":"9","wn":9,"n":5,"q":"Which of the following is not a benefit of e-learning?","options":["It can accommodate the need of a housewife","People can revise the learning content as many times as they want","It facilitates in developing and communicating new training policies","None of the given"],"answer":[3],"explanation":"All three statements are genuine benefits of e-learning: flexibility for people like housewives, unlimited revision of content, and easy roll-out of new training policies. Hence none of them is a non-benefit."},{"id":"w9q6","run":"2026","week":"9","wn":9,"n":6,"q":"Good learners know ____.","options":["What they are learning","Why they are learning","How they are learning","All of the given"],"answer":[3],"explanation":"Good learners are metacognitively aware: they know what they are learning, why they are learning it and how they are learning it."},{"id":"w9q7","run":"2026","week":"9","wn":9,"n":7,"q":"Learners may multitask when engaging in an online course, which could be resulting in ____.","options":["hyperfocus","better retrieval","shorter attention spans","None of the given"],"answer":[2],"explanation":"Multitasking splits attention across activities, which shortens attention spans and impairs encoding. It does not produce hyperfocus or better retrieval.","rep":["2026","2025","2024"],"grp":106},{"id":"w9q8","run":"2026","week":"9","wn":9,"n":8,"q":"____ learning is the crucial determinant of successful e-learning.","options":["passive","retrospective","social","active"],"answer":[3],"explanation":"Successful e-learning depends on learners actively engaging with content, through interaction, practice and reflection, rather than passively watching or reading."},{"id":"w9q9","run":"2026","week":"9","wn":9,"n":9,"q":"The brain can process 36,000 visual cues per____.","options":["hour","second","day","year"],"answer":[0],"explanation":"The lecture cites the commonly quoted figure that the brain can process about 36,000 visual messages per hour, used to argue for visual design in online courses."},{"id":"w9q10","run":"2026","week":"9","wn":9,"n":10,"q":"For effective learning, online courses should ____.","options":["use headings","use complex language","present long pieces of text","use random images"],"answer":[0],"explanation":"Headings chunk content and make it easy to scan and navigate, aiding comprehension. Complex language, long text blocks and irrelevant images increase cognitive load."},{"id":"w10q1","run":"2026","week":"10","wn":10,"n":1,"q":"During Covid-19 the world was busy in preparing 1.5 billion learners for the new normal, i.e., ____ learning.","options":["ineffective","physical","remote","experiential"],"answer":[2],"explanation":"School closures during the pandemic pushed about 1.5 billion learners worldwide into remote (online, distance) learning, which became the new normal. Physical classroom learning was exactly what was disrupted."},{"id":"w10q2","run":"2026","week":"10","wn":10,"n":2,"q":"To develop learner readiness for online learning, training sessions on ____ are helpful.","options":["netiquettes","time management","developing study skills","all of the given"],"answer":[3],"explanation":"Online learners need to know online etiquette, manage their own time, and study independently, so training on all three builds readiness for online learning."},{"id":"w10q3","run":"2026","week":"10","wn":10,"n":3,"q":"The typical picture of a teacher being a dispenser of knowledge to the students has been replaced by that of a ____.","options":["obstructor","parent","friend","facilitator"],"answer":[3],"explanation":"In learner-centred and online education, the teacher guides, supports and scaffolds students' own construction of knowledge, acting as a facilitator rather than a one-way transmitter of information."},{"id":"w10q4","run":"2026","week":"10","wn":10,"n":4,"q":"In 2018, Global Education and Skills Forum noted that the 'future' teacher would need the 5 skills to thrive in the 21st century. Which of the following is not one of them?","options":["Strong social skills","Data analysis","External focus","Strictness"],"answer":[3],"explanation":"The forum's list of future-teacher skills included strong social skills, data analysis and an external focus, among others. Strictness was not on it; the emphasis is on flexible, facilitative teaching rather than rigid control."},{"id":"w10q5","run":"2026","week":"10","wn":10,"n":5,"q":"Participatory education demands ____ so as to build a needs-based approach to teaching.","options":["creativity","stubbornness","reward","none of the given"],"answer":[0],"explanation":"Participatory education adapts teaching to learners' needs and involves them actively, which calls for creativity in designing activities and methods. Stubbornness works against such a flexible, needs-based approach."},{"id":"w10q6","run":"2026","week":"10","wn":10,"n":6,"q":"Students who consider intelligence as a malleable entity tend to focus on their obstacles instead of goals.","options":["True","False"],"answer":[1],"explanation":"Students with an incremental (growth) view of intelligence believe ability can be developed through effort, so they focus on learning goals and persist through difficulties. Dwelling on obstacles is more typical of students who see intelligence as fixed."},{"id":"w10q7","run":"2026","week":"10","wn":10,"n":7,"q":"Which of the following is not a principle to enhance student learning.","options":["What students already know affects their learning","Learning is context-based","Students' cognitive development and learning is limited by the general stages of development.","The acquisition of knowledge and skills in the long term depends largely on practice."],"answer":[2],"explanation":"The actual principle (APA's top 20 principles) states that students' cognitive development and learning are NOT limited by general stages of development, so this option reverses it. The other options are genuine principles: prior knowledge, context and practice all shape learning."},{"id":"w10q8","run":"2026","week":"10","wn":10,"n":8,"q":"____ feedback to students is important for learning.","options":["Unclear","Late","Harsh","Explanatory"],"answer":[3],"explanation":"Effective feedback is clear, explanatory, specific and timely: it tells students why something is right or wrong and how to improve. Unclear, late or harsh feedback reduces its value for learning."},{"id":"w10q9","run":"2026","week":"10","wn":10,"n":9,"q":"Mastery goals are those that are geared towards the acquisition or improvement of____.","options":["Skills","Number of students in a classroom","Teacher feedback","None of the given"],"answer":[0],"explanation":"Mastery (learning) goals focus on developing competence, that is, acquiring or improving skills and understanding. Performance goals, by contrast, focus on demonstrating ability relative to others."},{"id":"w10q10","run":"2026","week":"10","wn":10,"n":10,"q":"The vast majority of formative assessment is____.","options":["Formal","Incorrect","Written","informal"],"answer":[3],"explanation":"Formative assessment happens continuously during instruction, mostly through informal means such as questioning, observation and quick checks for understanding. Formal, written tests are more typical of summative assessment."},{"id":"w11q1","run":"2026","week":"11","wn":11,"n":1,"q":"Social cognition has a protracted development through infancy to ____.","options":["teenage","old-age","adulthood","death"],"answer":[2],"explanation":"Social cognitive abilities start emerging in infancy and keep maturing through childhood and adolescence into adulthood, alongside the late-developing social brain. Development does not stop at the teenage years."},{"id":"w11q2","run":"2026","week":"11","wn":11,"n":2,"q":"Which of the following abilities comes under social cognition?","options":["Face processing","Joint attention","Theory of mind","All of the given"],"answer":[3],"explanation":"Social cognition covers the processes used to perceive, interpret and respond to others, including face processing, joint attention and theory of mind."},{"id":"w11q3","run":"2026","week":"11","wn":11,"n":3,"q":"Under social cognition, abilities involved in affective processing are often called ____.","options":["hot","cold","white","black"],"answer":[0],"explanation":"Social-cognitive processes involving emotion and affect (such as empathy or processing emotional faces) are called 'hot', while more purely cognitive, non-emotional processes are called 'cold'."},{"id":"w11q4","run":"2026","week":"11","wn":11,"n":4,"q":"Social schemas refer to people's mental representations of social ____.","options":["values","memories","skills","patterns"],"answer":[3],"explanation":"Social schemas are organised knowledge structures that capture regular patterns in social life, such as roles, events and the behaviour of types of people. They help us interpret social situations and predict what will happen."},{"id":"w11q5","run":"2026","week":"11","wn":11,"n":5,"q":"During the earliest stages of development, children are very ____-centric. They see the world from their own perspective and struggle to think about how other people may view the world.","options":["selfish","ego","conscious","emotional"],"answer":[1],"explanation":"Piaget called young children egocentric: in the preoperational stage they struggle to take another person's perspective. This is a cognitive limitation, not selfishness."},{"id":"w11q6","run":"2026","week":"11","wn":11,"n":6,"q":"A theory of mind refers to a person's ability to understand and think about the ____ of other people.","options":["behaviors","family backgrounds","mental states","language"],"answer":[2],"explanation":"Theory of mind is the ability to attribute mental states (beliefs, desires, intentions, knowledge) to others and to understand that these can differ from one's own. Behaviour is what we observe; theory of mind infers the mental states behind it.","rep":["2026","2025"],"grp":125},{"id":"w11q7","run":"2026","week":"11","wn":11,"n":7,"q":"The same social behavior in one cultural setting might have a very different meaning and interpretation if it were to occur or be observed in another culture.","options":["True","False"],"answer":[0],"explanation":"Social cognition is shaped by culture: norms and schemas differ across cultures, so the same gesture or behaviour can be read very differently depending on the cultural context."},{"id":"w11q8","run":"2026","week":"11","wn":11,"n":8,"q":"Social cognitive theory by Bandura focuses on concepts of ____.","options":["self-efficacy","modeling","observational learning","all of the given"],"answer":[3],"explanation":"Bandura's social cognitive theory explains learning through observing and imitating models (observational learning and modeling). It also stresses self-efficacy, a person's belief in their ability to succeed."},{"id":"w11q9","run":"2026","week":"11","wn":11,"n":9,"q":"The central tenet of Bandura's social-cognitive theory is that people seek to develop a sense of ____ over the important events in their lives.","options":["agency","dependency","attachment","emotion"],"answer":[0],"explanation":"Bandura's agentic perspective holds that people are active agents who seek to exercise control over the important events in their lives through intentionality, forethought, self-reactiveness and self-reflection."},{"id":"w11q10","run":"2026","week":"11","wn":11,"n":10,"q":"____ hypothesis suggests that social processes influence how information is selected, organized, integrated, and retrieved.","options":["activation","cognitive influence","interaction","social cue strength"],"answer":[1],"explanation":"The cognitive influence hypothesis proposes that social processes shape cognitive processing itself: how information is selected, organised, integrated and later retrieved."},{"id":"w12q1","run":"2026","week":"12","wn":12,"n":1,"q":"Sustainability in economic sustainability is ____.","options":["multidimensional","bidimensional","unidimensional","none of the given"],"answer":[2],"explanation":"In the course's framing, economic sustainability views sustainability along a single dimension: maintaining economic capital and growth over time, without the social or environmental dimensions that broader sustainability adds.","note":"The accepted answer is C (unidimensional), but sustainability is usually described as multidimensional (option A). The user's choice of A was marked wrong. The JSON keeps the official answer."},{"id":"w12q2","run":"2026","week":"12","wn":12,"n":2,"q":"The term \"sustainable development\" was first mentioned in a book related to the 1972 UN Stockholm conference on ____.","options":["water","poverty","economic crisis","human environment"],"answer":[3],"explanation":"The 1972 UN Conference on the Human Environment in Stockholm produced early literature in which the term 'sustainable development' first appeared."},{"id":"w12q3","run":"2026","week":"12","wn":12,"n":3,"q":"Environmental sustainability focuses on impacts of processes, products and services on ____.","options":["water","biodiversity","human health","all of the given"],"answer":[3],"explanation":"Environmental sustainability looks at all ecological impacts, including those on water, biodiversity and human health, so every option applies."},{"id":"w12q4","run":"2026","week":"12","wn":12,"n":4,"q":"Which of the following does not come under social sustainability?","options":["Labour practices","Revenue generation","Human rights","Business ethics"],"answer":[1],"explanation":"Revenue generation is an economic concern. Labour practices, human rights and business ethics are social sustainability issues."},{"id":"w12q5","run":"2026","week":"12","wn":12,"n":5,"q":"SDG ____ focuses on clean water and sanitation.","options":["1","17","6","3"],"answer":[2],"explanation":"SDG 6 is Clean Water and Sanitation. SDG 1 is No Poverty, SDG 3 is Good Health and Well-being, and SDG 17 is Partnerships for the Goals."},{"id":"w12q6","run":"2026","week":"12","wn":12,"n":6,"q":"SDG 16 focuses on ____.","options":["No poverty","No hunger","Good health","Peace and justice"],"answer":[3],"explanation":"SDG 16 is Peace, Justice and Strong Institutions. The other options are SDGs 1, 2 and 3."},{"id":"w12q7","run":"2026","week":"12","wn":12,"n":7,"q":"On 20 October 2020, the Higher Education Sustainability Initiative (HESI) raised the flag of higher education as a driver for sustainable development and inclusive societies on the first day of the ____ 2020.","options":["National Sustainability Meeting","National Teachers Meeting","Global Childrens' Meeting","Global Education Meeting"],"answer":[3],"explanation":"HESI used the opening day of UNESCO's Global Education Meeting 2020 to promote higher education as a driver of sustainable development and inclusive societies."},{"id":"w12q8","run":"2026","week":"12","wn":12,"n":8,"q":"Education is related to all SDGs.","options":["True","False"],"answer":[0],"explanation":"Education is a goal in its own right (SDG 4), and it also builds the knowledge, skills and values needed to reach every other SDG."},{"id":"w12q9","run":"2026","week":"12","wn":12,"n":9,"q":"Successful implementation of ESD requires a shift in focus from ____.","options":["teaching to learning","learning to teaching","reading to speaking","knowing to ignoring"],"answer":[0],"explanation":"Education for Sustainable Development calls for learner-centred, action-oriented pedagogy, which moves the focus from teaching to learning.","rep":["2026","2024"],"grp":138},{"id":"w12q10","run":"2026","week":"12","wn":12,"n":10,"q":"____ competency is the ability to reflect on one's own role in the local community and (global) society.","options":["collaboration","self-awareness","strategic","normative"],"answer":[1],"explanation":"In UNESCO's key sustainability competencies, self-awareness competency means reflecting on one's own role in the local community and global society and evaluating one's own actions."},{"id":"r2025w0q1","run":"2025","week":"0","wn":0,"n":1,"q":"What is Psychology?","options":["A Science subject","Is objective perception","An art of living","A thought process","A study of cognitive processes & behavior"],"answer":[4],"explanation":"Psychology is the scientific study of mind (cognitive processes) and behavior. It is not merely an art of living or a thought process, and it is broader than any single science subject.","rep":["2026","2025","2024"],"grp":0},{"id":"r2025w0q2","run":"2025","week":"0","wn":0,"n":2,"q":"A broad field of study that explores a variety of questions about thoughts, feelings and actions is___?","options":["Society","Globalization","Psychology","Social Science","Human Development"],"answer":[2],"explanation":"Psychology specifically investigates the thoughts, feelings and actions of individuals. Social science is a broader umbrella that also includes economics, sociology and politics, so it is less precise.","rep":["2026","2025","2024"],"grp":1},{"id":"r2025w0q3","run":"2025","week":"0","wn":0,"n":3,"q":"A systematic assessment that provides information on political views, consumer buying habits and many other topics is called___?","options":["Standardized test","Projects","Experiments","Survey","Psychological tests"],"answer":[3],"explanation":"A survey systematically collects self-reported information from many people about attitudes, opinions and habits such as political views or buying behavior. Experiments manipulate variables, and psychological tests measure individual traits or abilities.","rep":["2025","2024"],"grp":140},{"id":"r2025w0q4","run":"2025","week":"0","wn":0,"n":4,"q":"The word Psyche means","options":["Body or physique","Mind or soul","Science & spirituality","Mental health","Neuropsychology"],"answer":[1],"explanation":"Psychology comes from the Greek words psyche (mind or soul) and logos (study). Hence psychology originally meant the study of the mind or soul.","rep":["2026","2025","2024"],"grp":3},{"id":"r2025w0q5","run":"2025","week":"0","wn":0,"n":5,"q":"Who established psychology laboratory in Germany?","options":["B.F. Skinner","J. Thorndike","Sigmund Freud","David Kolb","Wilhelm Wundt"],"answer":[4],"explanation":"Wilhelm Wundt founded the first formal psychology laboratory at Leipzig, Germany, in 1879, marking psychology's start as an independent experimental science. Skinner, Thorndike and Kolb were later figures, and Freud worked clinically in Vienna.","rep":["2025","2024"],"grp":141},{"id":"r2025w0q6","run":"2025","week":"0","wn":0,"n":6,"q":"To help people to function effectively and fulfill their own unique potential\" is the aim of___?","options":["Humanistic psychology","Social Psychiatry","Philosophy","Development studies","Sustainable development"],"answer":[0],"explanation":"Humanistic psychology (Maslow, Rogers) emphasizes personal growth, free will and self-actualization, i.e., helping people function effectively and fulfill their unique potential.","rep":["2026","2025","2024"],"grp":5},{"id":"r2025w0q7","run":"2025","week":"0","wn":0,"n":7,"q":"Behaviorists use a learning process to change abnormal behavior is called___?","options":["Rationalism","Experiential intervention","Gestalt mechanism","Hypotheses verification","Conditioning"],"answer":[4],"explanation":"Behaviorists treat abnormal behavior as learned, so they use conditioning (classical and operant, e.g., systematic desensitization or reinforcement programs) to unlearn it and build adaptive behavior.","rep":["2025","2024"],"grp":142},{"id":"r2025w0q8","run":"2025","week":"0","wn":0,"n":8,"q":"The study of changes in behavior during life time is called","options":["Behaviorism","Individual difference","Developmental Psychology","Maturational theory","Genetics or Heredity"],"answer":[2],"explanation":"Developmental psychology studies how behavior, cognition and emotion change across the lifespan, from infancy through old age. Maturation and heredity are factors it studies, not the field itself.","rep":["2025","2024"],"grp":143},{"id":"r2025w0q9","run":"2025","week":"0","wn":0,"n":9,"q":"The study of differences and similarities in the behavior of animals of different species is called","options":["Sociology","Social work","Rehabilitation studies","Comparative Psychology","Cultural Psychology"],"answer":[3],"explanation":"Comparative psychology compares behavior across species to understand evolutionary and functional similarities and differences. Cultural psychology compares human cultures, not species.","rep":["2026","2025","2024"],"grp":8},{"id":"r2025w1q1","run":"2025","week":"1","wn":1,"n":1,"q":"Which of the following is true regarding learning in psychology?","options":["Learning has not been an important topic in psychology","Learning involves no change in the organism","Learning focuses on how humans speak","Learning can be defined in many ways"],"answer":[3],"explanation":"Learning has been defined in many ways, for example as a relatively permanent change in behavior due to experience, or as acquiring knowledge and skills. The other statements are false: learning is central to psychology and always involves some change in the organism."},{"id":"r2025w1q2","run":"2025","week":"1","wn":1,"n":2,"q":"Learning is seen as an effect attributed to an element in","options":["blood","environment","hormones","none of the above"],"answer":[1],"explanation":"Learning is attributed to experience with the environment: it is a change in behavior caused by interaction with environmental events, not by blood, hormones or other biological factors such as maturation."},{"id":"r2025w1q3","run":"2025","week":"1","wn":1,"n":3,"q":"Non-associative learning refers to ____ in the intensity of a response as the result of the repeated presentation of a stimulus.","options":["a decrease","an increase","no change","none of the above"],"answer":[0],"explanation":"The keyed answer reflects habituation, the most basic form of non-associative learning, where repeated presentation of a stimulus weakens the response.","note":"Ambiguous: non-associative learning covers both habituation (decrease) and sensitization (increase), so 'a decrease' describes only habituation; Q10 of this same set acknowledges sensitization as an increase."},{"id":"r2025w1q4","run":"2025","week":"1","wn":1,"n":4,"q":"Which of the following is a type of learning style?","options":["visual","auditory","kinesthetic","all of the above"],"answer":[3],"explanation":"Visual, auditory and kinesthetic (VAK) are the commonly described learning styles, referring to learning through seeing, hearing and doing/movement respectively."},{"id":"r2025w1q5","run":"2025","week":"1","wn":1,"n":5,"q":"'Psychology as the Behaviorist Views It' is the famous work of","options":["Sigmund Freud","John Watson","Albert Bandura","Ivan Pavlov"],"answer":[1],"explanation":"John B. Watson's 1913 paper 'Psychology as the Behaviorist Views It' is known as the behaviorist manifesto, arguing psychology should study only observable behavior."},{"id":"r2025w1q6","run":"2025","week":"1","wn":1,"n":6,"q":"The state of conscious incompetence may be valuable ____ of a learning experience.","options":["at the start","at the end","in the middle","throughout the process"],"answer":[0],"explanation":"In the conscious competence model, realizing what you do not know (conscious incompetence) motivates learning, so it is valuable at the start. Ending a learning experience still in this stage would indicate the learning was not completed.","rep":["2026","2025"],"grp":17},{"id":"r2025w1q7","run":"2025","week":"1","wn":1,"n":7,"q":"Adding to existing student knowledge is known as","options":["conceptual change","conceptual pattern","conceptual exploration","conceptual growth"],"answer":[3],"explanation":"Conceptual growth means adding new information to what students already know without restructuring it. Conceptual change, by contrast, involves revising or replacing existing (often mistaken) ideas."},{"id":"r2025w1q8","run":"2025","week":"1","wn":1,"n":8,"q":"Deliberate practice involves the following, except","options":["attention","rehearsal","repetition","forgetting"],"answer":[3],"explanation":"Deliberate practice is focused, effortful practice that requires attention, rehearsal and repetition with feedback. Forgetting is not a component of practice; practice works against it."},{"id":"r2025w1q9","run":"2025","week":"1","wn":1,"n":9,"q":"Students persist in the face of challenging tasks and process information more deeply when they adopt ____ goals.","options":["performance","insignificant","mastery","repetitive"],"answer":[2],"explanation":"Mastery goals focus on understanding and improving competence, which leads learners to persist and use deep processing. Performance goals focus on appearing able relative to others and are linked to more surface-level strategies."},{"id":"r2025w1q10","run":"2025","week":"1","wn":1,"n":10,"q":"____ refers to a decrease in response rate while ____ refers to an increase in response rate.","options":["sensitization, habituation","meaningful learning, association","habituation, sensitization","association, meaningful learning"],"answer":[2],"explanation":"Habituation is a decrease in responding to a repeated stimulus, while sensitization is an increase in responding, often after an intense or noxious stimulus. Both are forms of non-associative learning."},{"id":"r2025w2q1","run":"2025","week":"2","wn":2,"n":1,"q":"According to constructivism, reality is determined by","options":["the experiences of the learner","the blood type of the learner","the future goals of the learner","none of the above"],"answer":[0],"explanation":"Constructivism holds that learners actively build their own understanding, so reality and knowledge are shaped by the experiences of the learner rather than simply received from outside."},{"id":"r2025w2q2","run":"2025","week":"2","wn":2,"n":2,"q":"Teachers and instructors who understand the constructivist learning theory understand that their students","options":["are all the same","bring their own unique experiences","do not demand much effort in the classroom","are careless"],"answer":[1],"explanation":"Constructivist teachers recognize that each student brings unique prior experiences and knowledge, which influence how new information is interpreted and constructed."},{"id":"r2025w2q3","run":"2025","week":"2","wn":2,"n":3,"q":"The domain of social constructivism is largely attributed to the work done by ____ by adding the focus on societal and peer influence on learning.","options":["Jean Piaget","Lev Vygotsky","Sigmund Freud","John Watson"],"answer":[1],"explanation":"Lev Vygotsky emphasized that learning is shaped by social interaction, language and culture (e.g., the zone of proximal development), founding social constructivism. Piaget's constructivism focused more on the individual learner."},{"id":"r2025w2q4","run":"2025","week":"2","wn":2,"n":4,"q":"Which of the following is not a major type of learning described by behavioral psychology?","options":["classical conditioning","operant conditioning","observational learning","traditional learning"],"answer":[3],"explanation":"Behavioral psychology describes three major types of learning: classical conditioning, operant conditioning and observational learning. 'Traditional learning' is not a recognized type."},{"id":"r2025w2q5","run":"2025","week":"2","wn":2,"n":5,"q":"Which of the following is true according to behaviorism?","options":["all behaviors can be unlearned","all behaviors are directed by one's parents","all behaviors are fundamentally destructive in nature","all behaviors are unobservable"],"answer":[0],"explanation":"Behaviorism holds that behaviors are learned through conditioning, so they can also be unlearned and replaced through new conditioning. Behaviorism studies observable behavior, so 'all behaviors are unobservable' contradicts it."},{"id":"r2025w2q6","run":"2025","week":"2","wn":2,"n":6,"q":"In ____ conditioning, presentation of unconditioned stimulus precedes the presentation of the conditioned stimulus.","options":["backward","delay","trace","simultaneous"],"answer":[0],"explanation":"In backward conditioning the unconditioned stimulus comes before the conditioned stimulus, which generally produces weak or no conditioning. In delay and trace conditioning the CS comes first."},{"id":"r2025w2q7","run":"2025","week":"2","wn":2,"n":7,"q":"Smiling and complimenting students for good performance is a type of","options":["negative punishment","positive punishment","negative reinforcement","positive reinforcement"],"answer":[3],"explanation":"Smiling and complimenting add a pleasant stimulus after good performance, which increases that behavior, so it is positive reinforcement. Negative reinforcement removes an unpleasant stimulus, and punishment decreases behavior."},{"id":"r2025w2q8","run":"2025","week":"2","wn":2,"n":8,"q":"Which of the following psychologists was instrumental in engendering the dramatic shift from behaviorism to cognitive theories?","options":["Tolman","Bruner","Gestalt","All of the above"],"answer":[3],"explanation":"Tolman's cognitive maps, Bruner's work on cognition and discovery learning, and the Gestalt psychologists' work on insight and perception all emphasized internal mental processes, driving the shift from behaviorism to cognitive theories."},{"id":"r2025w2q9","run":"2025","week":"2","wn":2,"n":9,"q":"IQ is a typical measurement for","options":["intelligence","personality","emotions","classical learning"],"answer":[0],"explanation":"IQ (intelligence quotient) is a standardized score derived from intelligence tests, used to measure intelligence. It does not measure personality or emotions."},{"id":"r2025w2q10","run":"2025","week":"2","wn":2,"n":10,"q":"BBL deals with the concept of learning in a ____ context.","options":["neuro-physiological","cognitive","social","behavioral"],"answer":[0],"explanation":"Brain-based learning (BBL) explains learning in terms of how the brain works, i.e., in a neuro-physiological context, and uses that knowledge to design instruction."},{"id":"r2025w3q1","run":"2025","week":"3","wn":3,"n":1,"q":"Which of the following is true?","options":["Human memory involves the ability to only preserve information","Human memory involves the ability to only recover information","Human memory involves the ability to neither preserve nor recover information","Human memory involves the ability to both preserve and recover information"],"answer":[3],"explanation":"Human memory involves encoding and storing (preserving) information and also retrieving (recovering) it when needed. Memory without either part would be useless."},{"id":"r2025w3q2","run":"2025","week":"3","wn":3,"n":2,"q":"____ refers to connections between the nerve cells","options":["Storage","Synapses","Neuron","Blood"],"answer":[1],"explanation":"Synapses are the junctions where one nerve cell communicates with another. Neurons are the nerve cells themselves, not the connections between them."},{"id":"r2025w3q3","run":"2025","week":"3","wn":3,"n":3,"q":"In order to create a new memory, information must be changed into ____","options":["a usable form","a long form","a short form","a visual form"],"answer":[0],"explanation":"Encoding, the first stage of memory formation, transforms incoming information into a usable form that can be stored as a new memory."},{"id":"r2025w3q4","run":"2025","week":"3","wn":3,"n":4,"q":"The memory ____ process allows us to bring stored memories into conscious awareness.","options":["storage","retrieval","encoding","forgetting"],"answer":[1],"explanation":"Retrieval is the process of bringing stored information back into conscious awareness. Encoding puts information in, storage keeps it, and forgetting is the failure of retrieval or storage."},{"id":"r2025w3q5","run":"2025","week":"3","wn":3,"n":5,"q":"Which of the following is not a major domain of cognition?","options":["Judgment","Attention","Aggression","Intelligence"],"answer":[2],"explanation":"Major cognitive domains include attention, memory, perception, judgment/reasoning, language and intelligence. Aggression is a behavior or emotional disposition, not a domain of cognition."},{"id":"r2025w3q6","run":"2025","week":"3","wn":3,"n":6,"q":"Which of the following is not an assumption of the information processing view?","options":["Information is processed in steps or stages","There are limits on how much information can be processed","The human information processing system is interactive","Information processing is analogous to computer processing"],"answer":[1],"explanation":"The keyed answer treats the limited-capacity idea as not being an assumption of the information processing view.","note":"Likely wrong key: limited capacity (e.g., 7 plus or minus 2 items in short-term memory) is a core assumption of the information processing view, and 2026 week03 states this as True. The computer analogy is more of a metaphor than an assumption and is probably the intended answer."},{"id":"r2025w3q7","run":"2025","week":"3","wn":3,"n":7,"q":"____ refers to rote rehearsal of repetition","options":["elaborative rehearsal","maintenance rehearsal","meaningful rehearsal","none of the above"],"answer":[1],"explanation":"Maintenance rehearsal is simple rote repetition that keeps information active in short-term memory. Elaborative rehearsal links information to existing knowledge and is more effective for long-term retention."},{"id":"r2025w3q8","run":"2025","week":"3","wn":3,"n":8,"q":"____ presentations can enhance working memory capacity","options":["multimodal","unimodal","one by one","antimodal"],"answer":[0],"explanation":"Presenting information through multiple modes (e.g., visual and auditory) spreads load across separate working-memory subsystems (visuo-spatial sketchpad and phonological loop), effectively increasing capacity (the modality effect)."},{"id":"r2025w3q9","run":"2025","week":"3","wn":3,"n":9,"q":"Episodic and semantic memories are categorized under ____ memory","options":["procedural","structural","phonemic","declarative"],"answer":[3],"explanation":"Declarative (explicit) memory includes episodic memory for personal events and semantic memory for facts and general knowledge. Procedural memory is a non-declarative memory for skills."},{"id":"r2025w3q10","run":"2025","week":"3","wn":3,"n":10,"q":"According to the neural network model, memory capacity depends on ____","options":["complexity of the synapses","sparseness of representations","spatial and temporal correlations between memories","all of the above"],"answer":[3],"explanation":"In neural network models, how many memories can be stored depends on synaptic complexity, the sparseness of representations, and the spatial and temporal correlations among stored memories, so all options apply."},{"id":"r2025w4q1","run":"2025","week":"4","wn":4,"n":1,"q":"Creative thinking is the ability to generate ____ ideas.","options":["innovative","unconventional","useful","all of the above"],"answer":[3],"explanation":"Creative thinking involves generating ideas that are novel or unconventional and also useful or appropriate, so innovative, unconventional and useful all describe creative ideas."},{"id":"r2025w4q2","run":"2025","week":"4","wn":4,"n":2,"q":"____ are representative items within each concept.","options":["Constructs","Symbols","Prototypes","Categories"],"answer":[2],"explanation":"A prototype is the most typical or best example of a concept, against which new items are compared to decide category membership.","rep":["2025","2023"],"grp":174},{"id":"r2025w4q3","run":"2025","week":"4","wn":4,"n":3,"q":"A mental representation can take the form of a ____.","options":["word","image","sound","all of the given"],"answer":[3],"explanation":"Mental representations can be verbal (words), visual or other images, and sounds, among other forms, so all of the given apply."},{"id":"r2025w4q4","run":"2025","week":"4","wn":4,"n":4,"q":"Which of the following is true?","options":["Thinking is a lower mental process","Thinking is a sub-vocal talking","Thinking is unrelated to problem solving","We can only think in numbers or words"],"answer":[1],"explanation":"Watson, a behaviorist, described thinking as sub-vocal talking, i.e., inner speech involving small movements of the speech organs. Thinking is actually a higher mental process closely tied to problem solving and can use images as well as words."},{"id":"r2025w4q5","run":"2025","week":"4","wn":4,"n":5,"q":"Cognitive architecture is a theory about the ____ that create a mind in natural or artificial systems.","options":["structures","facts","images","sounds"],"answer":[0],"explanation":"Cognitive architecture is a theory of the fixed structures (memory stores, processing modules and their organization) that give rise to a mind, whether natural or artificial, such as ACT-R or Soar."},{"id":"r2025w4q6","run":"2025","week":"4","wn":4,"n":6,"q":"Bloom's Taxonomy is a system of hierarchical models (arranged in a hierarchical rank,) used to categorize ____ into varying levels of complexity.","options":["learning objectives","attention goals","prototypes","none of the above"],"answer":[0],"explanation":"Bloom's taxonomy classifies educational learning objectives into hierarchical levels of complexity, from remembering up to creating in the revised version."},{"id":"r2025w4q7","run":"2025","week":"4","wn":4,"n":7,"q":"____ knowledge refers to knowledge of terminology and specific details.","options":["Metacognitive","Conceptual","Kinesthetic","Factual"],"answer":[3],"explanation":"In the revised Bloom's taxonomy, factual knowledge is the basic elements a learner must know: terminology and specific details. Conceptual knowledge concerns relationships, and metacognitive knowledge concerns awareness of one's own cognition.","rep":["2025","2024"],"grp":179},{"id":"r2025w4q8","run":"2025","week":"4","wn":4,"n":8,"q":"Choosing to skim subheadings of unimportant information to get to the information we need as a metacognitive skill is called ____.","options":["skimming","rehearsing","self-monitoring","modifying"],"answer":[0],"explanation":"Skimming means quickly scanning headings and subheadings to skip unimportant material and locate needed information, which is a deliberate, strategic metacognitive reading skill."},{"id":"r2025w4q9","run":"2025","week":"4","wn":4,"n":9,"q":"____ refers to the ability to regulate your thoughts and set aside any personal biases to come to the best conclusion.","options":["Self-regulation","Openmindedness","Observation","Interpretation","elaboration"],"answer":[0],"explanation":"In lists of critical thinking skills, self-regulation is described as monitoring and regulating one's own thinking and setting aside personal biases to reach the best conclusion. Open-mindedness is related but refers to being receptive to different viewpoints."},{"id":"r2025w4q10","run":"2025","week":"4","wn":4,"n":10,"q":"____ method of solving problems refers to a rule that guarantees the solution to a problem","options":["imagination","trial and error","analogy","algorithm"],"answer":[3],"explanation":"An algorithm is a step-by-step rule or procedure that guarantees a correct solution if followed, though it may be slow. Heuristics, analogies and trial and error do not guarantee a solution."},{"id":"r2025w5q1","run":"2025","week":"5","wn":5,"n":1,"q":"Motivation is seen as a ____ that drives and directs human behavior.","options":["hormonal impulse","mental impulse","attention deficit","judgment delay"],"answer":[1],"explanation":"Motivation is an internal (mental) impulse or force that energizes and directs behavior toward goals. It is not a hormonal impulse, an attention deficit or a judgment delay."},{"id":"r2025w5q2","run":"2025","week":"5","wn":5,"n":2,"q":"Which of the following is false regarding motivation?","options":["Motivation is an internal process","Motivation can be directly observed","Motivation activates people's actions","None of the above"],"answer":[1],"explanation":"Motivation is an internal process that activates and directs behavior, but it cannot be directly observed; it is inferred from behavior such as effort and persistence."},{"id":"r2025w5q3","run":"2025","week":"5","wn":5,"n":3,"q":"Which of the following does not come under intrinsic motivation?","options":["interests","social pressure","curiosity","self-satisfaction"],"answer":[1],"explanation":"Intrinsic motivation comes from within, such as interests, curiosity and self-satisfaction. Social pressure is an external source, so it belongs to extrinsic motivation."},{"id":"r2025w5q4","run":"2025","week":"5","wn":5,"n":4,"q":"Doing something/behaving well because one feels pressure from within is called ____.","options":["introjected regulation","amotivation","identified motivation","None of the given"],"answer":[0],"explanation":"In self-determination theory, introjected regulation is behavior driven by internal pressure such as guilt, anxiety or ego, i.e., partially internalized but still controlled. Identified regulation involves valuing the behavior, and amotivation is a lack of motivation."},{"id":"r2025w5q5","run":"2025","week":"5","wn":5,"n":5,"q":"Which of the following is not a biological need/drive?","options":["love","food","water","oxygen"],"answer":[0],"explanation":"Food, water and oxygen are basic biological (physiological) needs for survival. Love is a psychological or social need (belonging in Maslow's hierarchy), not a biological drive."},{"id":"r2025w5q6","run":"2025","week":"5","wn":5,"n":6,"q":"____ theory suggests that people are motivated to take action in order to receive a reward","options":["incentive","biological","arousal","goal setting"],"answer":[0],"explanation":"Incentive theory holds that people are pulled toward behavior by external rewards (incentives) and away from negative outcomes. Drive and arousal theories focus on internal states."},{"id":"r2025w5q7","run":"2025","week":"5","wn":5,"n":7,"q":"The Arousal Theory of Motivation was first proposed by ____.","options":["Hall","Watson","Bandura","Murray"],"answer":[3],"explanation":"The course credits Murray with first proposing the arousal theory of motivation.","note":"Questionable key: arousal theory is usually traced to Yerkes and Dodson (1908) and Hebb, while Henry Murray is known for his theory of psychogenic needs; none of the options is the standard attribution ('Hall' may be a misspelling of Hull, the drive theorist)."},{"id":"r2025w5q8","run":"2025","week":"5","wn":5,"n":8,"q":"____ theory is based on the assumption that our behavior is based on making a conscious choice from a set of possible alternative behaviors.","options":["arousal","expectancy","drive","goal setting"],"answer":[1],"explanation":"Vroom's expectancy theory assumes people consciously choose among alternative behaviors based on expectancy, instrumentality and valence. Drive and arousal theories focus on internal states, not conscious choice."},{"id":"r2025w5q9","run":"2025","week":"5","wn":5,"n":9,"q":"Which of the following is not an attribute of effective goal setting?","options":["unrealistic goals","specific goals","time based goals","assignable goals"],"answer":[0],"explanation":"Effective goals are SMART: specific, measurable, achievable/assignable, realistic and time-based. Unrealistic goals lead to frustration and lower motivation, so they are not an attribute of effective goal setting."},{"id":"r2025w5q10","run":"2025","week":"5","wn":5,"n":10,"q":"Maslow's hierarchy of needs consists of ____ tiers.","options":["four","three","six","five"],"answer":[3],"explanation":"Maslow's classic hierarchy has five tiers: physiological, safety, love and belonging, esteem, and self-actualization. Later expanded versions add more levels, but the standard model has five."},{"id":"r2025w6q1","run":"2025","week":"6","wn":6,"n":1,"q":"____ is mainly responsible for popularizing emotional intelligence.","options":["John Watson","Daniel Goleman","Sigmund Freud","Albert Bandura"],"answer":[1],"explanation":"Daniel Goleman's 1995 book 'Emotional Intelligence' made the concept widely popular. The term was earlier defined academically by Salovey and Mayer."},{"id":"r2025w6q2","run":"2025","week":"6","wn":6,"n":2,"q":"EQ is used to measure ____.","options":["cognitive intelligence","memory","emotional intelligence","attention"],"answer":[2],"explanation":"EQ (emotional quotient) is a measure of emotional intelligence, the ability to perceive, understand and manage emotions. IQ measures cognitive intelligence."},{"id":"r2025w6q3","run":"2025","week":"6","wn":6,"n":3,"q":"Experts suggest that EQ is more important than IQ.","options":["True","False"],"answer":[0],"explanation":"Goleman and other proponents argue that EQ matters as much as or more than IQ for success at work and in relationships, and the course follows this view.","note":"Contested claim: 'EQ is more important than IQ' is a popular claim (Goleman) rather than an established finding; research generally shows IQ remains a strong predictor of performance. Keyed True per the course."},{"id":"r2025w6q4","run":"2025","week":"6","wn":6,"n":4,"q":"Being able to put words to feelings refers to ____.","options":["emotional responsibility","emotional cognition","emotional attention","emotional literacy"],"answer":[3],"explanation":"Emotional literacy is the ability to recognize, understand and put words to one's feelings. The other options are not standard terms."},{"id":"r2025w6q5","run":"2025","week":"6","wn":6,"n":5,"q":"The first step in emotional intelligence is ____.","options":["perceiving emotions accurately","reasoning with emotions","managing emotions","dismissing emotions"],"answer":[0],"explanation":"In the Mayer-Salovey model, the first and most basic branch is perceiving emotions accurately in oneself and others. Reasoning with, understanding and managing emotions build on this."},{"id":"r2025w6q6","run":"2025","week":"6","wn":6,"n":6,"q":"According to nine-layer model pyramid, ____ lies at the bottom of the pyramid.","options":["Emotional stimuli","Self awareness","Self management","Transcendence"],"answer":[0],"explanation":"In the nine-layer pyramid model of emotional intelligence, emotional stimuli form the base layer, followed by emotion recognition, self-awareness, self-management and so on up to transcendence and emotional unity at the top."},{"id":"r2025w6q7","run":"2025","week":"6","wn":6,"n":7,"q":"The mixed model by ____ claims that EQ is a combination of competencies, skills, and “facilitators” that contribute to how people express themselves, respond to challenges in their environment, and connect with others.","options":["Watson","Goleman","Salovey and Mayer","Bar-On"],"answer":[3],"explanation":"Bar-On's mixed model describes EQ as interrelated emotional and social competencies, skills and facilitators that determine how people express themselves, cope with demands and relate to others. Salovey and Mayer proposed an ability model instead."},{"id":"r2025w6q8","run":"2025","week":"6","wn":6,"n":8,"q":"The transfer of emotions from one person to another is called ____.","options":["social effect","emotional effect","social contagion","emotional contagion"],"answer":[3],"explanation":"Emotional contagion is the tendency for emotions to spread from one person to another, often through unconscious mimicry of expressions and tone. Social contagion refers more broadly to spreading behaviors or ideas."},{"id":"r2025w6q9","run":"2025","week":"6","wn":6,"n":9,"q":"Hochschild has given the concept of ____ using the example of flight attendants.","options":["emotional indifference","emotional difficulty","emotional labor","emotional literacy"],"answer":[2],"explanation":"Arlie Hochschild, in 'The Managed Heart' (1983), introduced emotional labor: managing one's feelings and expressions as part of a job, illustrated by flight attendants required to stay cheerful."},{"id":"r2025w6q10","run":"2025","week":"6","wn":6,"n":10,"q":"Review of literature shows that ____ is associated with increasing levels of burnout.","options":["emotional intelligence","deep acting","surface acting","emotional literacy"],"answer":[2],"explanation":"Surface acting means displaying emotions one does not actually feel, which creates emotional dissonance and is consistently linked to higher burnout. Deep acting, where one tries to actually feel the required emotion, is less harmful."},{"id":"r2025w7q1","run":"2025","week":"7","wn":7,"n":1,"q":"Which of the following is false about learning according to Gagne’s definition?","options":["It is a change in human disposition","It persists over a period of time","It is simply ascribable to processes of growth","None of the above"],"answer":[2],"explanation":"Gagne defined learning as a change in human disposition or capability that persists over a period of time and is not simply ascribable to processes of growth. Attributing it simply to growth (maturation) is therefore the false statement.","rep":["2026","2025"],"grp":70},{"id":"r2025w7q2","run":"2025","week":"7","wn":7,"n":2,"q":"Manual or physical skills come under ____ component of Bloom’s taxonomy.","options":["Cognitive","Affective","Psychomotor","Physical"],"answer":[2],"explanation":"Bloom's taxonomy has three domains: cognitive (knowledge), affective (attitudes and feelings) and psychomotor (manual or physical skills). 'Physical' is not one of the named domains.","rep":["2026","2025"],"grp":71},{"id":"r2025w7q3","run":"2025","week":"7","wn":7,"n":3,"q":"Reflection, learning and education was explored by ____.","options":["Carl Rogers","John Watson","Benjamin Bloom","John Dewey"],"answer":[3],"explanation":"John Dewey wrote extensively on reflective thinking and its place in learning and education (e.g., How We Think, Democracy and Education). Watson was a behaviorist, Rogers a humanistic psychologist and Bloom is known for his taxonomy.","rep":["2026","2025"],"grp":72},{"id":"r2025w7q4","run":"2025","week":"7","wn":7,"n":4,"q":"The principles of ____ refer to how close in time two events must be for a bond to be formed.","options":["behavior","reinforcement","repetition","contiguity"],"answer":[3],"explanation":"Contiguity is the principle that events occurring close together in time become associated. Reinforcement concerns consequences that strengthen a response, not the timing between paired events.","rep":["2026","2025"],"grp":73},{"id":"r2025w7q5","run":"2025","week":"7","wn":7,"n":5,"q":"____ gives information to learners about their success or failure concerning the task at hand.","options":["Cognitive feedback","Emotional feedback","Reinforcement","Physical feedback"],"answer":[0],"explanation":"Cognitive feedback tells learners whether they succeeded or failed on the task, helping them correct their understanding. Reinforcement strengthens behavior through consequences rather than conveying task information.","rep":["2026","2025"],"grp":74},{"id":"r2025w7q6","run":"2025","week":"7","wn":7,"n":6,"q":"The ____ orientation to learning has a quality of personal involvement—the whole person in both feeling and cognitive aspects being in the learning event.","options":["behavioral","cognitive","humanistic","social"],"answer":[2],"explanation":"The humanistic orientation (Carl Rogers) emphasises whole-person, self-initiated learning involving both feelings and cognition. The cognitive orientation focuses mainly on mental processes rather than the whole person.","rep":["2026","2025"],"grp":75},{"id":"r2025w7q7","run":"2025","week":"7","wn":7,"n":7,"q":"Learning through play is ____ learning.","options":["primary","secondary","passive","active"],"answer":[3],"explanation":"In play, learners explore, manipulate and engage directly with materials and ideas, which makes it active learning rather than passive reception of information.","rep":["2026","2025"],"grp":76},{"id":"r2025w7q8","run":"2025","week":"7","wn":7,"n":8,"q":"People with ____ learning style are prone to sorting their ideas after speaking, rather than thinking ideas through before.","options":["logical","solitary","visual","auditory"],"answer":[3],"explanation":"Auditory (aural/verbal) learners process information by hearing and talking, so they often sort out their ideas by speaking them aloud. Solitary learners, by contrast, prefer to think things through alone first.","rep":["2026","2025"],"grp":77},{"id":"r2025w7q9","run":"2025","week":"7","wn":7,"n":9,"q":"Which of the following statements is false?","options":["Effective instruction is static","Effective instruction is eclectic","Effective instruction is generative","Effective instruction is interactive"],"answer":[0],"explanation":"Effective instruction is dynamic: it draws on multiple approaches (eclectic), encourages learners to generate knowledge (generative) and involves interaction. Calling it static is therefore false.","rep":["2026","2025"],"grp":78},{"id":"r2025w7q10","run":"2025","week":"7","wn":7,"n":10,"q":"In ADDIE model, I stand for ____.","options":["instruction","implementation","integration","induction"],"answer":[1],"explanation":"ADDIE stands for Analysis, Design, Development, Implementation and Evaluation, a common instructional design model. 'Instruction' is a tempting guess but is not part of the acronym.","rep":["2026","2025"],"grp":79},{"id":"r2025w8q1","run":"2025","week":"8","wn":8,"n":1,"q":"Pedagogy can be defined as a way of ____ any theoretical topic or academic subject.","options":["forgetting","teaching","remembering","memorizing"],"answer":[1],"explanation":"Pedagogy is the method and practice of teaching, i.e. the way a teacher teaches a theoretical topic or academic subject."},{"id":"r2025w8q2","run":"2025","week":"8","wn":8,"n":2,"q":"Good pedagogy is about ____.","options":["enabling self to be good at rote memorization","eliciting responses that demonstrate understanding","hampering cognitive development of learners","None of the above"],"answer":[1],"explanation":"Good pedagogy aims at real understanding, so it elicits responses from learners that demonstrate understanding. Rote memorization and hampering cognitive development are the opposite of good pedagogy."},{"id":"r2025w8q3","run":"2025","week":"8","wn":8,"n":3,"q":"Which of the following is a pedagogical approach in teaching?","options":["inductive","integrative","instance-based","intuitive"],"answer":[1],"explanation":"Integrative pedagogy, which connects ideas across topics and disciplines, is one of the pedagogical approaches discussed alongside constructivist, collaborative, reflective and inquiry-based approaches."},{"id":"r2025w8q4","run":"2025","week":"8","wn":8,"n":4,"q":"According to the ____ approach, learners are the makers of meaning and knowledge.","options":["solitary learning","passive learning","constructivist learning","metalearning"],"answer":[2],"explanation":"Constructivist learning holds that learners actively construct their own meaning and knowledge from experience rather than passively receiving it."},{"id":"r2025w8q5","run":"2025","week":"8","wn":8,"n":5,"q":"Which of the following is false about inquiry-based learning?","options":["is a form of passive learning","includes problem-based learning","generally used in small scale investigations","starts by posing questions"],"answer":[0],"explanation":"Inquiry-based learning is a form of active learning that starts by posing questions or problems and includes problem-based learning, so calling it passive is false."},{"id":"r2025w8q6","run":"2025","week":"8","wn":8,"n":6,"q":"The ____ model describes what effective teachers do in their classrooms to engage students in intellectually challenging work.","options":["pedagogical","systematic","engagement","intellectual"],"answer":[0],"explanation":"The Pedagogical Model describes what effective teachers do in their classrooms to engage students in intellectually challenging work, breaking the learning cycle into phases of instruction."},{"id":"r2025w8q7","run":"2025","week":"8","wn":8,"n":7,"q":"In experiential learning, experiences are structured to require the student to ____.","options":["take initiative","make decisions","be accountable for results","all of the above"],"answer":[3],"explanation":"Experiential learning structures experiences so that students must take initiative, make decisions and be accountable for the results, so all the options apply."},{"id":"r2025w8q8","run":"2025","week":"8","wn":8,"n":8,"q":"The following are the roles of an instructor in experiential learning, except ____.","options":["setting suitable experiences","posing problems","supporting students","blurring the boundaries"],"answer":[3],"explanation":"In experiential learning the instructor sets suitable experiences, poses problems, sets boundaries and supports students. Blurring the boundaries is not one of the instructor's roles; setting clear boundaries is."},{"id":"r2025w8q9","run":"2025","week":"8","wn":8,"n":9,"q":"Kolb's experiential learning style theory is typically represented by a ____-stage learning cycle","options":["three","five","four","seven"],"answer":[2],"explanation":"Kolb's cycle has four stages: concrete experience, reflective observation, abstract conceptualization and active experimentation."},{"id":"r2025w8q10","run":"2025","week":"8","wn":8,"n":10,"q":"People with ____ learning style are hands-on learners, and rely on intuition over logic.","options":["converging","accommodating","integrating","emotional"],"answer":[1],"explanation":"Kolb's accommodating (doing and feeling) style is hands-on and intuitive; such learners rely on intuition and gut feeling more than logic. Converging learners, by contrast, prefer technical problem solving and practical application of ideas."},{"id":"r2025w9q1","run":"2025","week":"9","wn":9,"n":1,"q":"A ____ classroom is the changing face of learning.","options":["digital","closed","passive","none of the above"],"answer":[0],"explanation":"The digital classroom, using technology and online tools, reflects how learning is changing; closed or passive classrooms are what it moves away from."},{"id":"r2025w9q2","run":"2025","week":"9","wn":9,"n":2,"q":"Which of the following is not a feature of e-learning?","options":["accessibility","teacher-centeredness","social justice","personalization"],"answer":[1],"explanation":"E-learning is learner-centred, offering accessibility, personalization and wider access (social justice). Teacher-centeredness is not one of its features."},{"id":"r2025w9q3","run":"2025","week":"9","wn":9,"n":3,"q":"Which of the following is a synonym of e-learning?","options":["audio-visual learning","multimedia learning","distance learning","none of the above"],"answer":[3],"explanation":"E-learning overlaps with audio-visual, multimedia and distance learning but is not synonymous with any of them; each is a distinct concept, so 'none of the above' is correct."},{"id":"r2025w9q4","run":"2025","week":"9","wn":9,"n":4,"q":"In ____ e-learning course, the content is simple and comprises text, images, audio, powerpoint presentation and text questions.","options":["simulation-based","interactive","powerpoint-driven","text-driven"],"answer":[3],"explanation":"Text-driven e-learning courses are simple, made up of text, images, audio, presentations and test questions. Interactive and simulation-based courses add more engagement and realistic practice."},{"id":"r2025w9q5","run":"2025","week":"9","wn":9,"n":5,"q":"Recent thinking in cognitive psychology places the ____ firmly at the center of the learning experience.","options":["computer","parent","teacher","individual"],"answer":[3],"explanation":"Cognitive psychology views learning as the learner's own active mental construction, so the individual learner is placed at the centre of the learning experience."},{"id":"r2025w9q6","run":"2025","week":"9","wn":9,"n":6,"q":"Which of the following is true?","options":["Learning depends on self-awareness.","Learning is social","Learning is goal-oriented","All of the above"],"answer":[3],"explanation":"Learning depends on self-awareness (metacognition), is social (shaped by interaction with others) and is goal-oriented, so all the statements are true."},{"id":"r2025w9q7","run":"2025","week":"9","wn":9,"n":7,"q":"Learners may multitask when engaging in an online course, which could be resulting in ____.","options":["hyperfocus","better retrieval","shorter attention spans","None of the given"],"answer":[2],"explanation":"Multitasking splits attention across activities, which shortens attention spans and impairs encoding. It does not produce hyperfocus or better retrieval.","rep":["2026","2025","2024"],"grp":106},{"id":"r2025w9q8","run":"2025","week":"9","wn":9,"n":8,"q":"The brain can process ____ visual cues per hour!","options":["36","360","3600","36,000"],"answer":[3],"explanation":"The lecture cites the commonly quoted figure that the brain can process about 36,000 visual cues per hour, used to argue for visual design in online courses."},{"id":"r2025w9q9","run":"2025","week":"9","wn":9,"n":9,"q":"Our brain has approximately ____ neurons that send information to one another.","options":["85 billion","85 million","85 lakhs","85,000"],"answer":[0],"explanation":"The human brain contains roughly 85-86 billion neurons that communicate with one another through synapses."},{"id":"r2025w9q10","run":"2025","week":"9","wn":9,"n":10,"q":"____ is referring to learners' automatic performance on specific procedures with predetermined steps to be followed.","options":["chaining","automatization","framing","none of the above"],"answer":[0],"explanation":"The key treats chaining as learners' automatic performance of a fixed sequence of predetermined steps, where each step cues the next.","note":"Ambiguous: the description ('automatic performance on specific procedures with predetermined steps') reads most naturally as automatization (option B); chaining is linking steps into a sequence. Key keeps chaining, presumably as worded in the lecture."},{"id":"r2025w10q1","run":"2025","week":"10","wn":10,"n":1,"q":"The ____ Model for New Normal in Education has been designed by many educational institutions.","options":["Pedagogical","Readiness","Instructional","Systematic"],"answer":[1],"explanation":"The Readiness Model was designed by educational institutions for the new normal, focusing on preparing learners, teachers and systems for remote learning."},{"id":"r2025w10q2","run":"2025","week":"10","wn":10,"n":2,"q":"The most critical factor that plays a significant role in the success of any remote learning program is the ____.","options":["software used by teacher","readiness of the participants","personality of the teacher","the quality of schooling"],"answer":[1],"explanation":"Readiness of the participants (learners and teachers) is the most critical factor for remote learning success; software and teacher personality matter less if participants are not ready."},{"id":"r2025w10q3","run":"2025","week":"10","wn":10,"n":3,"q":"The typical picture of a teacher being a ____ of knowledge to the students has been replaced.","options":["absorber","collector","exploiter","dispenser"],"answer":[3],"explanation":"The traditional image of the teacher as a dispenser of knowledge to students has been replaced by that of a facilitator who guides learners' own construction of knowledge."},{"id":"r2025w10q4","run":"2025","week":"10","wn":10,"n":4,"q":"What does today's teacher need to be successful in the classroom?","options":["digital skills","life skills","communication skills","all of the above"],"answer":[3],"explanation":"Today's teacher needs digital skills for technology-mediated teaching, life skills and communication skills, so all of these are required."},{"id":"r2025w10q5","run":"2025","week":"10","wn":10,"n":5,"q":"Students who consider intelligence as a ____ entity tend to focus on their goals despite obstacles.","options":["malleable","rigid","God-given","unreliable"],"answer":[0],"explanation":"Students who see intelligence as malleable (growth mindset) believe effort improves ability, so they keep focusing on their goals despite obstacles. Those who see it as fixed tend to give up when they hit difficulties."},{"id":"r2025w10q6","run":"2025","week":"10","wn":10,"n":6,"q":"____ feedback to students is important for learning.","options":["clear","explanatory","timely","all of the above"],"answer":[3],"explanation":"Useful feedback is clear, explanatory and timely: it tells students why something is right or wrong and how to improve while it still matters, so all the options apply."},{"id":"r2025w10q7","run":"2025","week":"10","wn":10,"n":7,"q":"Students tend to enjoy learning and have better outcomes when their motivation is more intrinsic than extrinsic.","options":["False","True"],"answer":[1],"explanation":"True. Intrinsic motivation (learning for interest and satisfaction) is linked to greater enjoyment, persistence and better outcomes than learning only for external rewards."},{"id":"r2025w10q8","run":"2025","week":"10","wn":10,"n":8,"q":"Long term goals are also called ____ goals.","options":["non urgent","principal","proximal","distal"],"answer":[3],"explanation":"Long-term goals are called distal goals; short-term, near goals are called proximal goals."},{"id":"r2025w10q9","run":"2025","week":"10","wn":10,"n":9,"q":"Which of the following is an example of a reward?","options":["clapping","giving money","giving a compliment","all of the above"],"answer":[3],"explanation":"Rewards can be social (clapping, compliments) or material (money), so all the options are examples of rewards."},{"id":"r2025w10q10","run":"2025","week":"10","wn":10,"n":10,"q":"____ is a teaching approach that generates feedback students can use to improve their performance.","options":["Assessment for performance","Assessment for marks","Assessment for rewards","Assessment for learning"],"answer":[3],"explanation":"Assessment for learning (formative assessment) is used during teaching to generate feedback that students can use to improve their performance, rather than just to award marks."},{"id":"r2025w11q1","run":"2025","week":"11","wn":11,"n":1,"q":"Social cognition is the cognitive processes that influence ____.","options":["social schema","social behavior","social media","none of the above"],"answer":[1],"explanation":"Social cognition refers to the cognitive processes (perceiving, interpreting, remembering information about others) that influence social behavior."},{"id":"r2025w11q2","run":"2025","week":"11","wn":11,"n":2,"q":"Smooth and adaptive social interactions depend on the recruitment of ____.","options":["perception","attention","language","all of the above"],"answer":[3],"explanation":"Smooth and adaptive social interaction draws on several cognitive processes at once, including perception, attention and language, so all the options apply."},{"id":"r2025w11q3","run":"2025","week":"11","wn":11,"n":3,"q":"Which of the following abilities does not come under social cognition?","options":["rote memory","face processing","joint attention","moral reasoning"],"answer":[0],"explanation":"Face processing, joint attention and moral reasoning are social-cognitive abilities. Rote memory is a general memory function, not specifically social cognition."},{"id":"r2025w11q4","run":"2025","week":"11","wn":11,"n":4,"q":"Social cognition develops primarily in old age.","options":["True","False"],"answer":[1],"explanation":"False. Social cognition develops from infancy through childhood and adolescence into adulthood; it does not primarily develop in old age."},{"id":"r2025w11q5","run":"2025","week":"11","wn":11,"n":5,"q":"A theory of mind refers to a person’s ability to understand and think about the ____ of other people.","options":["biological states","mental states","physical traits","none of the above"],"answer":[1],"explanation":"Theory of mind is the ability to attribute mental states (beliefs, desires, intentions, knowledge) to others and to understand that these may differ from one's own.","rep":["2026","2025"],"grp":125},{"id":"r2025w11q6","run":"2025","week":"11","wn":11,"n":6,"q":"The ____ theory details the processes of observational learning and modeling, and the influence of self-efficacy on the production of behavior.","options":["behavioral","socio-emotional","social-cognitive","cognitive-emotional"],"answer":[2],"explanation":"Bandura's social-cognitive theory explains learning through observation and modeling, and stresses self-efficacy as a key influence on whether behavior is produced."},{"id":"r2025w11q7","run":"2025","week":"11","wn":11,"n":7,"q":"____ processes account for the information that is selected for observation in the environment.","options":["motivational","production","retention","attentional"],"answer":[3],"explanation":"In Bandura's model, attentional processes determine what is selected for observation in the environment. Retention, production and motivational processes come after attention."},{"id":"r2025w11q8","run":"2025","week":"11","wn":11,"n":8,"q":"Children become more aggressive when they observe aggressive or violent models.","options":["True","False"],"answer":[0],"explanation":"True. Bandura's Bobo doll studies showed that children who observed aggressive models were more likely to imitate aggressive behavior."},{"id":"r2025w11q9","run":"2025","week":"11","wn":11,"n":9,"q":"The ____ model of observational learning involves real or fictional characters displaying behaviors in books, films, television programs, or online media.","options":["symbolic","live","verbal instructional","contextual"],"answer":[0],"explanation":"A symbolic model is a real or fictional character shown in books, films, television or online media. A live model is a person physically present, and a verbal instructional model describes the behavior in words."},{"id":"r2025w11q10","run":"2025","week":"11","wn":11,"n":10,"q":"____ refers to the anticipated consequences of a person’s behavior.","options":["self-efficacy","expectations","intrinsic reinforcement","extrinsic reinforcement"],"answer":[1],"explanation":"Outcome expectations are the anticipated consequences of a person's behavior. Self-efficacy, by contrast, is the belief in one's ability to perform the behavior."},{"id":"r2025w12q1","run":"2025","week":"12","wn":12,"n":1,"q":"Sustainability in the context of environmental sustainability is ____.","options":["multidimensional","bidimensional","unidimensional","none of the given"],"answer":[2],"explanation":"The key treats environmental sustainability as unidimensional, focusing on a single dimension: protecting natural systems and resources.","note":"Questionable: sustainability, including environmental sustainability, is usually described as multidimensional (option A). The key (unidimensional) matches the 2026 version of this question but is counter-intuitive."},{"id":"r2025w12q2","run":"2025","week":"12","wn":12,"n":2,"q":"As discussed by the Brundtland commission, sustainable development was the solution to the problems of ____.","options":["poor health","recession","poverty","environmental degradation"],"answer":[3],"explanation":"The Brundtland Commission (Our Common Future, 1987) proposed sustainable development as the answer to growing environmental degradation alongside development needs.","note":"The Brundtland report addressed both environmental degradation and poverty/development, so 'poverty' (C) is a plausible distractor; key D follows the common framing."},{"id":"r2025w12q3","run":"2025","week":"12","wn":12,"n":3,"q":"Environmental sustainability focuses on the impacts of processes, products and services on ____.","options":["biodiversity","ocean environment","air","all of the above"],"answer":[3],"explanation":"Environmental sustainability looks at the impacts of processes, products and services on all parts of the environment, including biodiversity, oceans and air, so all the options apply."},{"id":"r2025w12q4","run":"2025","week":"12","wn":12,"n":4,"q":"Social entrepreneurship is defined as solving social problems using ____.","options":["generational wealth","market-based methods","bank loans","magical methods"],"answer":[1],"explanation":"Social entrepreneurship addresses social problems with market-based, business-like methods, combining social mission with financial sustainability."},{"id":"r2025w12q5","run":"2025","week":"12","wn":12,"n":5,"q":"HESI stands for.","options":["Health and Education Sustainability Initiative","Higher Education Systematic Initiative","Higher Education Sustainability Initiative","none of the above"],"answer":[2],"explanation":"HESI is the Higher Education Sustainability Initiative, a UN partnership that links higher education institutions with sustainable development."},{"id":"r2025w12q6","run":"2025","week":"12","wn":12,"n":6,"q":"Universal primary and secondary education is an outcome target of ____.","options":["SDG 1","SDG 2","SDG 3","SDG 4"],"answer":[3],"explanation":"SDG 4 (Quality Education) includes targets for universal, free primary and secondary education. SDGs 1, 2 and 3 cover poverty, hunger and health."},{"id":"r2025w12q7","run":"2025","week":"12","wn":12,"n":7,"q":"____ is a target group for ESD for 2030 framework.","options":["policymakers","parents","institutional leaders","all of the above"],"answer":[3],"explanation":"The ESD for 2030 framework targets a wide range of stakeholders, including policymakers, institutional leaders, educators, parents and youth, so all the options apply."},{"id":"r2025w12q8","run":"2025","week":"12","wn":12,"n":8,"q":"Successful implementation of ESD requires a shift in focus to ____.","options":["learning","teaching","exploiting","reading"],"answer":[0],"explanation":"ESD calls for learner-centred, action-oriented pedagogy, shifting the focus from teaching to learning."},{"id":"r2025w12q9","run":"2025","week":"12","wn":12,"n":9,"q":"____ competency refers to the ability to reflect on one's own role in community and society.","options":["self-awareness","emotional","normative","anticipatory"],"answer":[0],"explanation":"In UNESCO's key sustainability competencies, self-awareness competency is the ability to reflect on one's own role in the local community and global society. Normative competency concerns norms and values; anticipatory concerns future scenarios."},{"id":"r2025w12q10","run":"2025","week":"12","wn":12,"n":10,"q":"In 2021, the European Centre for the Development of Vocational Training published a skills forecast scenario on the likely employment and skills implications of the ____.","options":["European Greenhouse Initiative","European Green Deal","European Green Agreement","none of the above"],"answer":[1],"explanation":"In 2021 Cedefop published a skills forecast scenario examining the employment and skills effects of the European Green Deal, the EU's plan for a climate-neutral economy."},{"id":"r2024w0q1","run":"2024","week":"0","wn":0,"n":1,"q":"What is Psychology?","options":["A Science subject","Is objective perception","An art of living","A thought process","A study of cognitive processes & behavior"],"answer":[4],"explanation":"Psychology is the scientific study of mind (cognitive processes) and behavior. It is more than an art of living or a thought process, which describe only parts of it.","rep":["2026","2025","2024"],"grp":0},{"id":"r2024w0q2","run":"2024","week":"0","wn":0,"n":2,"q":"A broad field of study that explores a variety of questions about thoughts, feelings and actions is ____?","options":["Society","Globalization","Psychology","Social Science","Human Development"],"answer":[2],"explanation":"Psychology specifically investigates thoughts, feelings and actions of individuals. Social science is a broader umbrella that also covers economics, sociology and politics, so it is less precise.","rep":["2026","2025","2024"],"grp":1},{"id":"r2024w0q3","run":"2024","week":"0","wn":0,"n":3,"q":"A systematic assessment that provides information on political views, consumer buying habits and many other topics is called ____?","options":["Standardized test.","Projects","Experiments","Survey","Psychological tests"],"answer":[3],"explanation":"A survey systematically collects self-reported information from many people, which is how opinions on politics or buying habits are gathered. Experiments manipulate variables, and standardized or psychological tests measure abilities or traits.","rep":["2025","2024"],"grp":140},{"id":"r2024w0q4","run":"2024","week":"0","wn":0,"n":4,"q":"The word Psyche means ____?","options":["Body or physique","Mind or soul","Science & spirituality","Mental health","Neuropsychology"],"answer":[1],"explanation":"Psychology comes from the Greek words psyche (mind or soul) and logos (study). Hence psychology originally meant the study of the mind or soul.","rep":["2026","2025","2024"],"grp":3},{"id":"r2024w0q5","run":"2024","week":"0","wn":0,"n":5,"q":"Who established psychology laboratory in Germany?","options":["B.F. Skinner","J. Thorndike","Sigmund Freud","David Kolb","Wilhelm Wundt"],"answer":[4],"explanation":"Wilhelm Wundt set up the first experimental psychology laboratory at Leipzig, Germany, in 1879. Skinner and Thorndike worked in the USA, and Freud developed psychoanalysis in Vienna rather than a lab.","rep":["2025","2024"],"grp":141},{"id":"r2024w0q6","run":"2024","week":"0","wn":0,"n":6,"q":"To help people to function effectively and fulfill their own unique potential\" is the aim of ____","options":["Humanistic psychology","Social Psychiatry","Philosophy","Development studies","Sustainable development"],"answer":[0],"explanation":"Humanistic psychology (Maslow, Rogers) emphasizes personal growth, free will and self-actualization, i.e., helping people fulfill their unique potential.","rep":["2026","2025","2024"],"grp":5},{"id":"r2024w0q7","run":"2024","week":"0","wn":0,"n":7,"q":"Behaviorists use a learning process to change abnormal behavior is called ____?","options":["Rationalism","Experiential intervention","Gestalt mechanism","Hypotheses verification","Conditioning"],"answer":[4],"explanation":"Behaviorists treat abnormal behavior as learned, so they use conditioning (classical and operant techniques such as desensitization or reinforcement) to change it. Gestalt and rationalism are not behaviorist learning processes.","rep":["2025","2024"],"grp":142},{"id":"r2024w0q8","run":"2024","week":"0","wn":0,"n":8,"q":"The study of changes in behavior during life time is called","options":["Behaviorism","Individual difference","Developmental Psychology","Maturational theory","Genetics or Heredity"],"answer":[2],"explanation":"Developmental psychology studies how behavior, cognition and emotion change across the lifespan, from infancy through old age. Maturation is only one factor within that study.","rep":["2025","2024"],"grp":143},{"id":"r2024w0q9","run":"2024","week":"0","wn":0,"n":9,"q":"The study of differences and similarities in the behavior of animals of different species is called","options":["Sociology","Social work","Rehabilitation studies","Comparative Psychology","Cultural Psychology"],"answer":[3],"explanation":"Comparative psychology compares behavior across species to understand evolutionary and functional similarities and differences. Cultural psychology compares human cultures, not species.","rep":["2026","2025","2024"],"grp":8},{"id":"r2024w1q1","run":"2024","week":"1","wn":1,"n":1,"q":"Which of the following is true regarding learning in psychology?","options":["The psychology of learning focuses on how people learn and how they interact with the environments in which they have not learnt","Learning does not involve any changes in the organism","Learning is a relatively temporary change in behavior","none of the given"],"answer":[3],"explanation":"Each statement is false: learning is a relatively permanent (not temporary) change, it does involve changes in the organism, and the psychology of learning studies how people interact with the environments in which they do learn. So none of the given is correct."},{"id":"r2024w1q2","run":"2024","week":"1","wn":1,"n":2,"q":"In order to say that learning has occurred, a/an ___ must occur during the lifetime of the organism.","options":["hidden change in behavior","small change in personality","visible change in emotions","observable change in behavior"],"answer":[3],"explanation":"Learning is inferred from an observable (overt) change in behavior or performance during the organism's lifetime. A hidden change cannot be used to establish that learning has occurred."},{"id":"r2024w1q3","run":"2024","week":"1","wn":1,"n":3,"q":"Learning changes the ___ through the process of continuous interactions between the learner and the external environment.","options":["physical structure of the brain","chemical structure of neurons","physical structure of the heart","chemical structure of the spinal cord"],"answer":[0],"explanation":"Learning physically alters the brain (neuroplasticity), for example by forming and strengthening synaptic connections through ongoing interaction with the environment."},{"id":"r2024w1q4","run":"2024","week":"1","wn":1,"n":4,"q":"Watson, one of the first psychologists to study learning and behavior is known for the","options":["Little Albert experiment","Little John experiment","Little Robert experiment","Little Johnny experiment"],"answer":[0],"explanation":"Watson and Rayner (1920) conditioned an infant, Little Albert, to fear a white rat by pairing it with a loud noise, demonstrating classical conditioning of emotions. The other names are not real experiments."},{"id":"r2024w1q5","run":"2024","week":"1","wn":1,"n":5,"q":"Which of the following is not explored and described by the psychology of learning?","options":["principles of motivation","principles of forgetting","principles of genetic disorders","principles of memory","principles of retention"],"answer":[2],"explanation":"The psychology of learning explains motivation, memory, retention and forgetting. Genetic disorders belong to genetics and medicine, not to the principles of learning."},{"id":"r2024w1q6","run":"2024","week":"1","wn":1,"n":6,"q":"The state of ___ may be valuable at the start of a learning experience.","options":["conscious incompetence","unconscious incompetence","conscious over-competence","unconscious over-competence"],"answer":[0],"explanation":"In the conscious competence model, realizing what you do not yet know (conscious incompetence) creates the motivation to learn, so it is useful at the start. Unconscious incompetence means you do not even see the gap."},{"id":"r2024w1q7","run":"2024","week":"1","wn":1,"n":7,"q":"___ is the decrease in the response that an organism gives to a stimulus to which it is exposed in numerous trials or occasions.","options":["Habituation","Sensitization","Forgetting","Meaningful learning"],"answer":[0],"explanation":"Habituation is a non-associative form of learning in which response to a repeated, harmless stimulus decreases. Sensitization is the opposite, an increased response after repeated or intense stimulation."},{"id":"r2024w1q8","run":"2024","week":"1","wn":1,"n":8,"q":"Cooperative learning is shaped by three crucial elements. Which of the following is one of them?","options":["formation of heterogeneous groups","positive interdependence","individual responsibility","all of the given"],"answer":[3],"explanation":"Cooperative learning rests on forming heterogeneous groups, positive interdependence among members, and individual responsibility (accountability). Since all three are listed, all of the given is correct."},{"id":"r2024w1q9","run":"2024","week":"1","wn":1,"n":9,"q":"Which of the following psychologists is an important contributor to the concept of observational learning?","options":["Watson","Dewey","Bruner","Bandura"],"answer":[3],"explanation":"Albert Bandura's social learning theory and Bobo doll studies showed that people learn by observing and imitating models. Watson was a behaviorist, Dewey a pragmatist educator, and Bruner a cognitive/constructivist theorist."},{"id":"r2024w1q10","run":"2024","week":"1","wn":1,"n":10,"q":"Which of the following is not considered a pioneer of the behaviorism school of thought in psychology?","options":["Watson","Skinner","Freud","Pavlov"],"answer":[2],"explanation":"Watson, Pavlov and Skinner are pioneers of behaviorism. Freud founded psychoanalysis, which focuses on unconscious mental processes rather than observable behavior."},{"id":"r2024w2q1","run":"2024","week":"2","wn":2,"n":1,"q":"___ is known as the father of modern psychology.","options":["Sigmund Freud","Wilhelm Wundt","John Watson","Lev Vygotsky"],"answer":[1],"explanation":"Wilhelm Wundt is called the father of modern (experimental) psychology because he founded the first psychology laboratory in Leipzig in 1879. Freud founded psychoanalysis and Watson founded behaviorism."},{"id":"r2024w2q2","run":"2024","week":"2","wn":2,"n":2,"q":"Cognitivists objected to behaviorists because they felt that behaviorists ignored the important role of ___.","options":["genetics","emotions","thinking","stimulus reaction"],"answer":[2],"explanation":"Cognitivists argued that behaviorists ignored internal mental processes such as thinking, memory and problem solving, focusing only on observable stimulus-response links."},{"id":"r2024w2q3","run":"2024","week":"2","wn":2,"n":3,"q":"___ is viewed as the mainstream for all research on learning designs.","options":["Psychoanalysis","Positive psychology","Cognitivism","Evolutionary psychology"],"answer":[2],"explanation":"Cognitivism, with its focus on how information is processed, stored and retrieved, became the mainstream framework for research on learning and instructional design after the cognitive revolution."},{"id":"r2024w2q4","run":"2024","week":"2","wn":2,"n":4,"q":"___ is a perspective in psychology focusing on the belief that human consciousness cannot be broken down into its elements and is based on the concept of a 'whole'.","options":["Cognitivism","Behaviorism","Gestalt psychology","Positive psychology"],"answer":[2],"explanation":"Gestalt psychology holds that the whole is different from the sum of its parts, so experience and consciousness should be studied as organized wholes rather than broken into elements."},{"id":"r2024w2q5","run":"2024","week":"2","wn":2,"n":5,"q":"Theory of multiple intelligences is given by","options":["Howard Gardner","Edward Tolman","German Gestalt","Robert J. Sternberg"],"answer":[0],"explanation":"Howard Gardner proposed the theory of multiple intelligences in 1983 (Frames of Mind). Sternberg proposed the triarchic theory, and Tolman is known for cognitive maps."},{"id":"r2024w2q6","run":"2024","week":"2","wn":2,"n":6,"q":"The general intelligence factor, also known as g, is what intelligence tests typically measure and refers only to ___ intelligence.","options":["academic","practical","linguistic","kinesthetic"],"answer":[0],"explanation":"Critics such as Sternberg and Gardner argue that g, as measured by standard IQ tests, captures only academic (analytical) intelligence and misses practical, creative and other abilities."},{"id":"r2024w2q7","run":"2024","week":"2","wn":2,"n":7,"q":"Cognitive evaluation for planning, attention, simultaneous, and successive processing of individuals can be done through CAS based on PASS theory. CAS here stands for ___.","options":["Cognitive Achievement System","Cognitive Ability System","Cognitive Appraisal System","Cognitive Assessment System"],"answer":[3],"explanation":"The Cognitive Assessment System (Das and Naglieri) operationalizes PASS theory by measuring Planning, Attention, Simultaneous and Successive processing."},{"id":"r2024w2q8","run":"2024","week":"2","wn":2,"n":8,"q":"BBL is a new science that shapes the learning process and is an approach that is based on the structure and function of the human brain. BBL stands for ___.","options":["Biological based learning","Brain based learning","Biological battery learning","Brain biology learning"],"answer":[1],"explanation":"BBL stands for brain-based learning, an approach that designs teaching around how the brain naturally learns, using findings from neuroscience."},{"id":"r2024w2q9","run":"2024","week":"2","wn":2,"n":9,"q":"Gagne's Conditions of Learning is also known as ___ Events of Instruction.","options":["nine","five","ten","seven"],"answer":[0],"explanation":"Gagne's Conditions of Learning gives nine events of instruction, from gaining attention to enhancing retention and transfer."},{"id":"r2024w2q10","run":"2024","week":"2","wn":2,"n":10,"q":"Which of the following is not a type of constructivism?","options":["biological","cognitive","social","radical"],"answer":[0],"explanation":"Common types of constructivism are cognitive (Piaget), social (Vygotsky) and radical (von Glasersfeld). Biological constructivism is not one of the recognized types."},{"id":"r2024w3q1","run":"2024","week":"3","wn":3,"n":1,"q":"Which of the following is not one of the three major processes involved in memory?","options":["encoding","retrieval","storage","imagination"],"answer":[3],"explanation":"The three major memory processes are encoding, storage and retrieval. Imagination is a separate cognitive activity, not a stage of memory."},{"id":"r2024w3q2","run":"2024","week":"3","wn":3,"n":2,"q":"___ refers to changing information into a usable form.","options":["Storage","Recall","Encoding","Recollection","Forgetting"],"answer":[2],"explanation":"Encoding is the first stage of memory, transforming incoming information into a form that can be stored. Storage keeps it and recall/recollection bring it back."},{"id":"r2024w3q3","run":"2024","week":"3","wn":3,"n":3,"q":"___ refers to a range of mental processes relating to the acquisition, storage, manipulation and retrieval of information.","options":["Cognition","Construction","Encoding","Thinking"],"answer":[0],"explanation":"Cognition is the umbrella term for mental processes involved in acquiring, storing, manipulating and retrieving information, such as perception, memory, reasoning and thinking."},{"id":"r2024w3q4","run":"2024","week":"3","wn":3,"n":4,"q":"Which of the following is a challenge faced by people with social cognition deficits?","options":["talking too much to people","responding too well to people","difficulty in reading facial expressions","difficulty in getting good academic scores"],"answer":[2],"explanation":"Social cognition covers how people perceive and interpret social information. People with social cognition deficits, as in some autism spectrum conditions, often struggle to read facial expressions and know how to respond."},{"id":"r2024w3q5","run":"2024","week":"3","wn":3,"n":5,"q":"Which of the following is not true about the assumptions underlying the Information Processing View of Learning?","options":["Information processing is analogous to computer processing","The human information processing system is interactive","There is no limit on how much information can be processed at each stage","Information is processed in steps"],"answer":[2],"explanation":"The information processing view assumes that processing happens in steps, is interactive, and is like computer processing, but with limited capacity at each stage (e.g., short-term memory holds about 7 plus or minus 2 items). So saying there is no limit is not true."},{"id":"r2024w3q6","run":"2024","week":"3","wn":3,"n":6,"q":"___ prevents the quick disappearance from short term memory of information","options":["Rehearsal","Encoding","Retrieval","None of the given"],"answer":[0],"explanation":"Rehearsal, especially maintenance rehearsal (repeating information), keeps information active in short-term memory and stops it from fading within about 20 seconds."},{"id":"r2024w3q7","run":"2024","week":"3","wn":3,"n":7,"q":"The Multicomponent Model of Working Memory is largely attributed to the work by","options":["Atkinson & Shiffrin","Baddeley","Piaget","Craik & Lockhart"],"answer":[1],"explanation":"Alan Baddeley (with Hitch, 1974) proposed the multicomponent model of working memory, with a central executive, phonological loop, visuo-spatial sketchpad and later the episodic buffer. Atkinson and Shiffrin gave the multi-store model and Craik and Lockhart the levels-of-processing model."},{"id":"r2024w3q8","run":"2024","week":"3","wn":3,"n":8,"q":"___ memory refers to the events that can be reported from a person's life.","options":["Episodic","Semantic","Procedural","None of the given"],"answer":[0],"explanation":"Episodic memory stores personally experienced events that can be reported with their time and place. Semantic memory holds general facts, and procedural memory holds skills."},{"id":"r2024w3q9","run":"2024","week":"3","wn":3,"n":9,"q":"The memory capacity depends on which of the following?","options":["complexity of the synapses","spatial and temporal correlations between memories","specific way memories are retrieved","all of the given"],"answer":[3],"explanation":"Memory capacity is thought to depend on synaptic complexity, on how memories overlap in space and time, and on how they are retrieved. Since all three are factors, all of the given is correct."},{"id":"r2024w3q10","run":"2024","week":"3","wn":3,"n":10,"q":"Which of the following is not one of the three measurable dimensions of cognitive load?","options":["mental effort","mental load","physical effort","performance"],"answer":[2],"explanation":"Cognitive load is commonly measured through mental load, mental effort and performance. Physical effort is not a dimension of cognitive load."},{"id":"r2024w4q1","run":"2024","week":"4","wn":4,"n":1,"q":"The three main types of thinking in psychology include the following except","options":["symbolic","creative","divergent","convergent"],"answer":[3],"explanation":"In this course the three main types of thinking are symbolic, creative and divergent thinking, so convergent is the option left out.","note":"Ambiguous: convergent and divergent thinking are usually presented as a classic pair, so 'convergent' being excluded depends on the course's specific list (symbolic, creative, divergent)."},{"id":"r2024w4q2","run":"2024","week":"4","wn":4,"n":2,"q":"Young children engaging in imaginative play often engage in ___ thinking.","options":["creative","divergent","symbolic","convergent"],"answer":[2],"explanation":"Imaginative (pretend) play uses one thing to stand for another, such as a stick as a horse, which is symbolic thinking. Piaget linked this symbolic function to the preoperational stage."},{"id":"r2024w4q3","run":"2024","week":"4","wn":4,"n":3,"q":"Which of the following is a way in which we think?","options":["in verbal symbols","in mathematical symbols","in gestures and movements","all of the given"],"answer":[3],"explanation":"We think using verbal symbols (words), mathematical symbols, and also gestures, movements and images. Since all are ways of thinking, all of the given is correct."},{"id":"r2024w4q4","run":"2024","week":"4","wn":4,"n":4,"q":"People experience the ___ experience when they find the solution to a problem suddenly that had been in their mind for hours or days, late.","options":["\"oh no\"","\"wow\"","\"aha\"","none of the given"],"answer":[2],"explanation":"The 'aha' experience is the sudden insight when a solution to a problem appears after it has been in mind for some time. Kohler's insight learning studies describe this."},{"id":"r2024w4q5","run":"2024","week":"4","wn":4,"n":5,"q":"___ knowledge refers to knowledge of terminology and specific details.","options":["factual","conceptual","procedural","metacognitive"],"answer":[0],"explanation":"In Bloom's revised taxonomy, factual knowledge covers basic elements such as terminology and specific details. Conceptual knowledge covers relationships and theories, and procedural knowledge covers how to do things.","rep":["2025","2024"],"grp":179},{"id":"r2024w4q6","run":"2024","week":"4","wn":4,"n":6,"q":"Which of the following is not true about metacognition?","options":["allows people to be dependent on others for their learning","often referred to as \"thinking about thinking\"","is crucial for efficient independent learning because it fosters self-reflection","is a regulatory system that helps a person understand and control his or her own cognitive performance"],"answer":[0],"explanation":"Metacognition is thinking about thinking, a regulatory system that supports self-reflection and independent learning. It makes learners less, not more, dependent on others."},{"id":"r2024w4q7","run":"2024","week":"4","wn":4,"n":7,"q":"Which of the following is not an effective way to develop reflective thinking?","options":["asking questions","self-questioning","negotiated learning","avoiding reflective discussions"],"answer":[3],"explanation":"Asking questions, self-questioning and negotiated learning all encourage reflection. Avoiding reflective discussions prevents reflective thinking, so it is not an effective way."},{"id":"r2024w4q8","run":"2024","week":"4","wn":4,"n":8,"q":"Which of the following is not true about creative thinking?","options":["It is the ability to consider something in a new way","It is not a skill anybody can develop","It is the process of nurturing our imagination","It is all about developing innovative solutions to problems.","It requires a compilation of analytical, problem-solving, organizational and communication skills"],"answer":[1],"explanation":"Creative thinking is a skill that can be developed and improved by anyone through practice. The other statements correctly describe creative thinking."},{"id":"r2024w4q9","run":"2024","week":"4","wn":4,"n":9,"q":"The ___ stage of the creative thinking process refers to the \"eureka\" moment.","options":["insight","incubation","evaluation","preparation","elaboration"],"answer":[0],"explanation":"In Wallas's model of creativity (preparation, incubation, illumination/insight, verification), the insight or illumination stage is the sudden 'eureka' moment when the idea appears."},{"id":"r2024w4q10","run":"2024","week":"4","wn":4,"n":10,"q":"In a concept map, two nodes connected with a labeled arrow are called a","options":["preposition","nodal link","schema","proposition"],"answer":[3],"explanation":"In a concept map, two concepts (nodes) joined by a labeled linking arrow form a proposition, a meaningful statement. 'Preposition' is a grammatical term and a tempting look-alike."},{"id":"r2024w5q1","run":"2024","week":"5","wn":5,"n":1,"q":"Which of the following is not a causal factor for extrinsic motivation?","options":["rewards","social pressure","curiosity","financial gain","punishment"],"answer":[2],"explanation":"Extrinsic motivation comes from outside the person, such as rewards, social pressure, money or punishment. Curiosity is an internal source, so it drives intrinsic motivation."},{"id":"r2024w5q2","run":"2024","week":"5","wn":5,"n":2,"q":"___ refers to realizing the value of developing a skill/behavior.","options":["Amotivation","Identified regulation","Introjected regulation","Motivational learning"],"answer":[1],"explanation":"In self-determination theory, identified regulation means a person consciously values a behavior or skill and accepts it as personally important. Introjected regulation is driven by guilt or ego, and amotivation is a lack of motivation."},{"id":"r2024w5q3","run":"2024","week":"5","wn":5,"n":3,"q":"Drive theory is a psychological concept that attempts to explain why and how people behave in the ways they do. It is given by","options":["Murray","Hull","Atkinson","Zajonc"],"answer":[1],"explanation":"Clark Hull's drive-reduction theory explains behavior as an effort to reduce internal tension created by biological drives such as hunger and thirst. Murray is known for psychogenic needs and Atkinson for achievement motivation."},{"id":"r2024w5q4","run":"2024","week":"5","wn":5,"n":4,"q":"___ theory that suggests that people are motivated to take action in order to receive a reward and is based on the idea of operant conditioning.","options":["Incentive","Arousal","Goal setting","None of the given"],"answer":[0],"explanation":"Incentive theory says people are pulled to act by external rewards, which links it to operant conditioning and reinforcement. Arousal theory concerns optimal stimulation levels."},{"id":"r2024w5q5","run":"2024","week":"5","wn":5,"n":5,"q":"The Yerkes Dodson law gives ___ relationship between arousal and performance.","options":["inverted U shaped","linear","no","parabolic"],"answer":[0],"explanation":"The Yerkes-Dodson law says performance rises with arousal up to an optimal point and then falls, giving an inverted U-shaped curve."},{"id":"r2024w5q6","run":"2024","week":"5","wn":5,"n":6,"q":"The expectancy theory is based on the assumption that ___.","options":["our behavior is based on making a conscious choice from a set of possible alternative behaviors","individuals are motivated to seek out stimulation when they have low levels of arousal, but will become bored and unmotivated when they become too highly aroused","biological needs produce unpleasant states of arousal which people seek to reduce","none of the given"],"answer":[0],"explanation":"Vroom's expectancy theory assumes people consciously choose among alternative behaviors based on expected outcomes (expectancy, instrumentality, valence). The second option describes arousal theory and the third describes drive theory."},{"id":"r2024w5q7","run":"2024","week":"5","wn":5,"n":7,"q":"Valence, or the perceived value of reward, would have ___ value if one wants to avoid that reward.","options":["one","zero","positive","negative"],"answer":[3],"explanation":"Valence is the value placed on an outcome: positive if wanted, zero if indifferent, and negative if the person would rather avoid it."},{"id":"r2024w5q8","run":"2024","week":"5","wn":5,"n":8,"q":"Which of the following is not true about Maslow's need hierarchy?","options":["Needs lower down in the hierarchy must be satisfied before individuals can attend to higher needs","Safety needs lie at the bottom of the pyramid","Deficiency needs are concerned with basic survival","Growth needs are more psychological needs","Motivation is seen as being not just concerned with tension reduction and survival but also with human growth and development"],"answer":[1],"explanation":"In Maslow's hierarchy, physiological needs lie at the bottom of the pyramid, with safety needs on the second level. So saying safety needs are at the bottom is not true."},{"id":"r2024w5q9","run":"2024","week":"5","wn":5,"n":9,"q":"Self-Determination Theory differentiates between ___ and ___ motivation types.","options":["autonomous and controlled","autonomous and intrinsic","controlled and extrinsic","introjected and extrinsic","introjected and intrinsic"],"answer":[0],"explanation":"Self-determination theory contrasts autonomous motivation (acting from choice and personal value) with controlled motivation (acting from external pressure or internal guilt)."},{"id":"r2024w5q10","run":"2024","week":"5","wn":5,"n":10,"q":"In achievement motivation, the motive to avoid failure often consists of","options":["worries about the consequences of failing","self-criticism","accelerated heart rate","all of the given"],"answer":[3],"explanation":"The motive to avoid failure includes worries about the consequences of failing, self-criticism and bodily signs of anxiety such as a faster heart rate. So all of the given apply."},{"id":"r2024w6q1","run":"2024","week":"6","wn":6,"n":1,"q":"Daniel Goleman's work in emotional intelligence (EI) has outlined ___ main areas of this intelligence.","options":["three","four","five","six"],"answer":[2],"explanation":"Goleman's model has five components: self-awareness, self-regulation, motivation, empathy and social skills."},{"id":"r2024w6q2","run":"2024","week":"6","wn":6,"n":2,"q":"Which of the following statements is not true?","options":["Experts even suggested that emotional intelligence/ EQ, is more important than IQ/academic intelligence","An individual with high EI is not only aware of what emotions they are feeling but can put words to their feelings","Studies show that EI does not impact aspects of one's life like academic performance","Peter Salovey and John Mayer were the first to develop a psychological theory of emotional intelligence."],"answer":[2],"explanation":"Studies show that emotional intelligence does affect academic performance, work, relationships and health, so the third statement is false. The others are accurate, including that Salovey and Mayer first theorized EI."},{"id":"r2024w6q3","run":"2024","week":"6","wn":6,"n":3,"q":"___ refers to how tuned to the emotions of others a person is.","options":["Empathy","Motivation","Emotional literacy","Self regulation"],"answer":[0],"explanation":"Empathy is the ability to sense and understand others' emotions. Self-regulation concerns managing one's own emotions, and emotional literacy concerns naming them."},{"id":"r2024w6q4","run":"2024","week":"6","wn":6,"n":4,"q":"The following are advantages of developing emotional intelligence, except ____","options":["Being able to accept criticism and responsibility","Knowing why we do the things we do","Being able to say no when we need to","Being able to hide our feelings from others"],"answer":[3],"explanation":"Emotional intelligence helps us accept criticism, understand our motives and set boundaries. Hiding our feelings from others is suppression, not a benefit of EI, which favors appropriate expression."},{"id":"r2024w6q5","run":"2024","week":"6","wn":6,"n":5,"q":"The Pyramid of Emotional Intelligence is also known as the ___ layer model.","options":["nine","five","seven","eleven"],"answer":[0],"explanation":"The Pyramid of Emotional Intelligence (Drigas and Papoutsis) has nine layers, from emotional stimuli at the base up to emotional unity at the top."},{"id":"r2024w6q6","run":"2024","week":"6","wn":6,"n":6,"q":"EI can be developed at any stage of life through self-effort & training.","options":["True","False"],"answer":[0],"explanation":"Unlike largely stable IQ, emotional intelligence consists of skills that can be learned and improved at any age through self-effort, practice and training."},{"id":"r2024w6q7","run":"2024","week":"6","wn":6,"n":7,"q":"When someone engages in ___, they can regulate their emotions to ensure that others feel more comfortable.","options":["emotional exhaustion","emotional literacy","empathy","emotional labor"],"answer":[3],"explanation":"Emotional labor (Hochschild) is the regulation of one's emotional expressions to meet role demands, such as staying calm and pleasant so customers feel comfortable."},{"id":"r2024w6q8","run":"2024","week":"6","wn":6,"n":8,"q":"The management of emotions is ___","options":["a private act","influenced by cultural and social norms","done by actively shaping and directing feelings","all of the given"],"answer":[3],"explanation":"Managing emotions is partly a private act, shaped by cultural and social display rules, and involves actively shaping and directing one's feelings. So all of the given are correct."},{"id":"r2024w6q9","run":"2024","week":"6","wn":6,"n":9,"q":"___ is seen when workers change their outward emotional expressions but do not attempt to feel the emotions that they are displaying.","options":["deep acting","emotional contagion","surface acting","emotional literacy"],"answer":[2],"explanation":"Surface acting means changing outward expressions (for example, a fake smile) without trying to feel the emotion. Deep acting involves trying to actually feel the emotion that is displayed."},{"id":"r2024w6q10","run":"2024","week":"6","wn":6,"n":10,"q":"The concept of emotional contagion can be linked to biological basis of ___","options":["emotional neurons","mirror neurons","contagious neurons","None of the given"],"answer":[1],"explanation":"Mirror neurons fire both when we act and when we observe others acting, which is thought to underlie automatically 'catching' others' emotions, i.e., emotional contagion."},{"id":"r2024w7q1","run":"2024","week":"7","wn":7,"n":1,"q":"___ defined learning as 'a change in human disposition or capacity that persists over a period of time and is not simply ascribable to processes of growth.'","options":["Bloom","Dewey","Gagne","Kolb"],"answer":[2],"explanation":"Robert Gagne defined learning as a change in human disposition or capability that persists over time and is not simply ascribable to processes of growth (maturation). Bloom is known for his taxonomy, Dewey for reflective learning and Kolb for the experiential learning cycle."},{"id":"r2024w7q2","run":"2024","week":"7","wn":7,"n":2,"q":"The principles of contiguity (how close in time two events must be for a bond to be formed) and reinforcement (any means of increasing the likelihood that an event will be repeated) are central to explaining the learning process in the ___ orientation to learning.","options":["Cognitive","Humanistic","Social and social-constructivist","Behaviorist"],"answer":[3],"explanation":"Contiguity and reinforcement are the core mechanisms of the behaviorist orientation, which explains learning as stimulus-response bonds strengthened by their timing and consequences. Cognitive and humanistic orientations focus on mental processes and personal growth instead."},{"id":"r2024w7q3","run":"2024","week":"7","wn":7,"n":3,"q":"Which of the following is not true about humanistic orientations to learning?","options":["It has a quality of personal involvement","It is self-initiated","It is pervasive","The locus of evaluation resides definitely outside the learner"],"answer":[3],"explanation":"In Carl Rogers' humanistic view, learning involves personal involvement, is self-initiated, is pervasive, and is evaluated by the learner. The locus of evaluation lies within the learner, not outside, so that statement is not true."},{"id":"r2024w7q4","run":"2024","week":"7","wn":7,"n":4,"q":"The concept of situated learning is studied under which school of thought of learning theories?","options":["behaviorist","cognitive","humanistic","social"],"answer":[3],"explanation":"Situated learning (Lave and Wenger) holds that learning happens through participation in communities of practice, so it belongs to the social (social-situational) orientation. Behaviorist and cognitive orientations locate learning in responses or individual minds rather than social participation."},{"id":"r2024w7q5","run":"2024","week":"7","wn":7,"n":5,"q":"Which of the following is not one of the individual variable factors affecting learning?","options":["ergonomics","interest","endurance","ego","perception"],"answer":[0],"explanation":"Interest, endurance, ego and perception are characteristics of the individual learner that affect learning. Ergonomics concerns the design of the physical environment and equipment, so it is an environmental rather than an individual factor."},{"id":"r2024w7q6","run":"2024","week":"7","wn":7,"n":6,"q":"___ learners prefer maps, graphs, diagrams and charts to learn.","options":["Visual","Solitary","Kinesthetic","Auditory"],"answer":[0],"explanation":"Visual (spatial) learners learn best through images, so they prefer maps, graphs, diagrams and charts. Auditory learners prefer listening, and kinesthetic learners prefer hands-on activity."},{"id":"r2024w7q7","run":"2024","week":"7","wn":7,"n":7,"q":"___ learners search for connections, causes, patterns, and results in their learning.","options":["linguistic","kinesthetic","visual","logical"],"answer":[3],"explanation":"Logical (mathematical) learners use reasoning and systems, so they look for connections, causes, patterns and results. Linguistic learners prefer words, and visual learners prefer images."},{"id":"r2024w7q8","run":"2024","week":"7","wn":7,"n":8,"q":"Effective instruction is ___","options":["interactive, generative and dynamic","designed to accommodate student learning needs and styles","guided by general pedagogical approaches","eclectic","all of the given"],"answer":[4],"explanation":"Effective instruction is interactive, generative and dynamic, accommodates learners' needs and styles, is guided by general pedagogical approaches and is eclectic in drawing on several methods. Since every statement applies, 'all of the given' is correct."},{"id":"r2024w7q9","run":"2024","week":"7","wn":7,"n":9,"q":"___ role of the trainer consists of transmitting information about a subject to the audience.","options":["expert","instructor","facilitator","co-learner"],"answer":[0],"explanation":"In the expert role, the trainer acts as a subject-matter authority who transmits information about the subject to the audience. Facilitators and co-learners guide or share learning rather than simply transmitting content."},{"id":"r2024w7q10","run":"2024","week":"7","wn":7,"n":10,"q":"Which of the following is not a component of the ADDIE model?","options":["analysis","integration","development","evaluation"],"answer":[1],"explanation":"ADDIE stands for Analysis, Design, Development, Implementation and Evaluation. 'Integration' is not one of its phases."},{"id":"r2024w8q1","run":"2024","week":"8","wn":8,"n":1,"q":"The word 'pedagogy' has been derived from the Greek word \"pedagogue\" which stands for","options":["the science of learning","the art of observing","the art of teaching children","none of the given"],"answer":[2],"explanation":"Pedagogy comes from the Greek paidagogos (pais, child + agogos, leader), and the term refers to the art of teaching children. It is not the science of learning in general or the art of observing."},{"id":"r2024w8q2","run":"2024","week":"8","wn":8,"n":2,"q":"Which of the following statements is not true about pedagogy?","options":["It assists both students and teachers in gaining an in-depth understanding of fundamental material.","It is about suppressing responses from learners","It enhances the student-teacher relationship","It enables teachers to influence student learning with an intention to capture the attention of students"],"answer":[1],"explanation":"Pedagogy aims to draw out and engage learners' responses, deepen understanding and strengthen the student-teacher relationship. Suppressing learners' responses runs against good pedagogy, so that statement is not true."},{"id":"r2024w8q3","run":"2024","week":"8","wn":8,"n":3,"q":"Which of the following is not a pedagogical approach in teaching?","options":["reflective","collective","collaborative","integrative"],"answer":[1],"explanation":"Commonly taught pedagogical approaches include constructivist, collaborative, reflective, integrative and inquiry-based approaches. 'Collective' is not one of them and is a distractor that sounds like 'collaborative'."},{"id":"r2024w8q4","run":"2024","week":"8","wn":8,"n":4,"q":"___ is a form of active learning that starts by posing questions, problems or scenarios rather than simply presenting established facts or portraying a smooth path to knowledge.","options":["constructivist learning","passive learning","inquiry-based learning","metalearning"],"answer":[2],"explanation":"Inquiry-based learning starts from questions, problems or scenarios that learners investigate, instead of presenting finished facts. Passive learning is the opposite of this active approach."},{"id":"r2024w8q5","run":"2024","week":"8","wn":8,"n":5,"q":"Which of the following is a primary role of the instructor in experiential learning?","options":["posing problems","providing solutions","blurring boundaries","none of the given"],"answer":[0],"explanation":"In experiential learning the instructor sets up the experience by posing problems, setting boundaries and supporting learners, while learners work out solutions themselves. Providing solutions would undercut learning from experience."},{"id":"r2024w8q6","run":"2024","week":"8","wn":8,"n":6,"q":"The \"what is important?\" stage of the experiential learning process refers to the ___ stage","options":["processing","generalizing","application","reflecting"],"answer":[0],"explanation":"In the experiential learning cycle (experiencing, sharing, processing, generalizing, applying), the processing stage asks 'what is important?' by examining patterns in the shared experience. Generalizing asks 'so what?' and application asks 'now what?'."},{"id":"r2024w8q7","run":"2024","week":"8","wn":8,"n":7,"q":"The ___ learning style as given by Kolb suggests that these individuals prefer to look at things from multiple perspectives and prefer to watch rather than do.","options":["Assimilating","Accommodating","Converging","Diverging"],"answer":[3],"explanation":"Kolb's diverging (feeling and watching) learners view situations from multiple perspectives and prefer to watch rather than do, often gathering information and brainstorming. Accommodating learners, by contrast, prefer hands-on doing."},{"id":"r2024w8q8","run":"2024","week":"8","wn":8,"n":8,"q":"The following factors influence preferred learning style except","options":["career choice","personality","educational specialization","genes"],"answer":[3],"explanation":"Kolb noted that a person's preferred learning style is shaped by factors such as personality type, educational specialization, career choice and current job role. Genes are not listed among these influences."},{"id":"r2024w8q9","run":"2024","week":"8","wn":8,"n":9,"q":"Integrative learning often involves three steps. Which of the following is not one of them?","options":["collaboration","integrative enquiry","application and transfer","reflection"],"answer":[0],"explanation":"Integrative learning typically involves integrative inquiry, application and transfer of learning to new settings, and reflection. Collaboration may support it but is not one of the three steps."},{"id":"r2024w8q10","run":"2024","week":"8","wn":8,"n":10,"q":"In transformative learning, ___ includes a student's habit of the mind, as well as a personal point of view.","options":["intentional content","frame of reference","frame of context","none of the given"],"answer":[1],"explanation":"In Mezirow's transformative learning theory, a frame of reference is made up of habits of mind and a point of view, which shape how a person interprets experience. Transformation happens when this frame of reference is revised."},{"id":"r2024w9q1","run":"2024","week":"9","wn":9,"n":1,"q":"E-learning implies ___ learning.","options":["mentor assisted","teacher enhanced","computer enhanced","electricity enhanced"],"answer":[2],"explanation":"E-learning means learning enhanced or delivered through computers and electronic technology. It is not defined by mentor or teacher assistance, and 'electricity enhanced' is a playful distractor."},{"id":"r2024w9q2","run":"2024","week":"9","wn":9,"n":2,"q":"___ type of e-learning is highly interactive, which includes graphics, video, audio and games too.","options":["text driven","simulation","interactive","none of the given"],"answer":[1],"explanation":"Simulation-based e-learning is the most highly interactive type, using graphics, video, audio and even games to recreate real situations. Text-driven courses are the least interactive."},{"id":"r2024w9q3","run":"2024","week":"9","wn":9,"n":3,"q":"Which of the following is not true about e-learning?","options":["one can have access to the content any number of times","it helps in developing new policies","it saves time for the students, they don't need to travel to the institution","it is targeted to cater to the needs of students specifically"],"answer":[3],"explanation":"E-learning benefits include unlimited access to content, saving travel time and easy roll-out of new policies, and it serves many groups such as working professionals and homemakers. It is not targeted only at students, so that statement is not true."},{"id":"r2024w9q4","run":"2024","week":"9","wn":9,"n":4,"q":"As learning depends on the learner's prior experience, and no two learners will have the same experiences, new information will be dealt with in different ways by different learners. This statement means that learning is","options":["goal-oriented","dependent on self-awareness","social","idiosyncratic"],"answer":[3],"explanation":"Because each learner brings different prior experience, each processes new information in their own unique way, so learning is idiosyncratic. Goal-oriented and social describe other characteristics of learning."},{"id":"r2024w9q5","run":"2024","week":"9","wn":9,"n":5,"q":"Which of the following is a way of facilitating the social dimension to learning?","options":["e-mails","online discussions","virtual communities","all of the given"],"answer":[3],"explanation":"E-mails, online discussions and virtual communities all let learners interact with peers and instructors, supporting the social dimension of online learning. Hence 'all of the given' is correct."},{"id":"r2024w9q6","run":"2024","week":"9","wn":9,"n":6,"q":"We can say that when we're good at something after practice, it's usually because","options":["our brain has become automated","our brain has released better chemicals","our brain has made stronger connections with this information","our brain has prioritized this information over others"],"answer":[2],"explanation":"Practice repeatedly activates the same neural pathways, strengthening the connections that represent the information or skill. This stronger connectivity is why practised skills become easier and more reliable."},{"id":"r2024w9q7","run":"2024","week":"9","wn":9,"n":7,"q":"Learners may multitask when engaging in an online course, which could be resulting in","options":["hyperfocus","better retrieval","shorter attention spans","None of the given"],"answer":[2],"explanation":"Multitasking splits attention across activities, which shortens attention spans and impairs encoding. It does not produce hyperfocus or better retrieval.","rep":["2026","2025","2024"],"grp":106},{"id":"r2024w9q8","run":"2024","week":"9","wn":9,"n":8,"q":"The cognitive load theory suggests that when we overload our ___ we are unable to acquire and process new information.","options":["sensory memory","encoding","retrieval","working memory"],"answer":[3],"explanation":"Cognitive load theory (Sweller) holds that working memory has limited capacity, and overloading it prevents new information from being processed and stored. Sensory memory, encoding and retrieval are not the limited resource the theory centres on."},{"id":"r2024w9q9","run":"2024","week":"9","wn":9,"n":9,"q":"There are five critical aspects of psychology which are needed to guarantee the implementation of successful eLearning. Which of the following is not one of them?","options":["evolution","self-discipline","stress","emotion"],"answer":[0],"explanation":"The psychological aspects that support successful e-learning include factors such as motivation, emotion, stress and self-discipline. Evolution is not one of them."},{"id":"r2024w9q10","run":"2024","week":"9","wn":9,"n":10,"q":"___ is a learning tool, because the explicit navigation of the topic and association types might enable meaningful learning and it helps to reduce the cognitive loads caused by E-learning content and constant attention.","options":["topic map","schema","prototype","instructional map"],"answer":[0],"explanation":"A topic map organises content as topics and the explicit associations between them, so learners can navigate meaningfully. This structure reduces the cognitive load of e-learning content."},{"id":"r2024w10q1","run":"2024","week":"10","wn":10,"n":1,"q":"The Readiness Model for New Normal in Education designed by many educational institutions caters to the following components except","options":["parent readiness","learner readiness","society readiness","teacher readiness"],"answer":[2],"explanation":"The readiness model for the new normal in education addresses learner readiness, teacher readiness, parent readiness and institutional readiness. Society readiness is not one of its components."},{"id":"r2024w10q2","run":"2024","week":"10","wn":10,"n":2,"q":"In 2018, Global Education and Skills Forum noted that the 'future' teacher would need some skills to thrive in the 21st century. Which of the following is not one of them?","options":["Being a facilitator","Internal focus","Strong social skills","Data analysis"],"answer":[1],"explanation":"The forum listed skills such as being a facilitator, strong social skills, data analysis and an external focus for the future teacher. 'Internal focus' is the reverse of the external focus it recommended."},{"id":"r2024w10q3","run":"2024","week":"10","wn":10,"n":3,"q":"Which of the following impacts student learning?","options":["Their perception about their intelligence and ability","Prior knowledge","Their context","All of the given"],"answer":[3],"explanation":"Students' beliefs about their intelligence and ability, their prior knowledge and their context all affect learning, as reflected in APA's principles for teaching and learning. So 'all of the given' is correct."},{"id":"r2024w10q4","run":"2024","week":"10","wn":10,"n":4,"q":"Which of the following statements is not true?","options":["Techniques linked to self-control contribute to more effective learning if taught and applied correctly","Student creativity can be encouraged.","Clear, explanatory and timely feedback to students is important for learning","Students tend to enjoy learning and have better outcomes when their motivation is more extrinsic than intrinsic"],"answer":[3],"explanation":"Research shows that students enjoy learning more and achieve better outcomes when their motivation is intrinsic rather than extrinsic. The other statements, on self-control, creativity and timely feedback, are true."},{"id":"r2024w10q5","run":"2024","week":"10","wn":10,"n":5,"q":"Both formative and summative assessment are important and useful, provided they are applied and interpreted appropriately.","options":["True","False"],"answer":[0],"explanation":"Formative assessment guides ongoing teaching and learning, while summative assessment judges achievement at the end of a unit. Both are valuable when used and interpreted appropriately, so the statement is true."},{"id":"r2024w10q6","run":"2024","week":"10","wn":10,"n":6,"q":"Individual differences are the unique ways each human being differs from another. It can be handled through using different techniques. Which of the following is not one of them?","options":["observation","sociograms","rating scales","ignorance"],"answer":[3],"explanation":"Teachers can identify and respond to individual differences using techniques such as observation, sociograms and rating scales. Ignoring the differences is not a technique for handling them."},{"id":"r2024w10q7","run":"2024","week":"10","wn":10,"n":7,"q":"Clapping is an example of ___ reward.","options":["tangible","financial","social","none of the given"],"answer":[2],"explanation":"Clapping expresses approval from other people, so it is a social reward. Tangible rewards are physical objects, and financial rewards involve money."},{"id":"r2024w10q8","run":"2024","week":"10","wn":10,"n":8,"q":"___ is the process of judging the value or worth of an individual's achievements or characteristics.","options":["Goal-setting","Classroom conduct","Formation","Evaluation"],"answer":[3],"explanation":"Evaluation is the process of judging the value or worth of a person's achievements or characteristics, usually against criteria. Goal-setting and classroom conduct are different activities."},{"id":"r2024w10q9","run":"2024","week":"10","wn":10,"n":9,"q":"___ refers to the frequent, interactive assessment of student progress to identify learning needs and shape teaching.","options":["Formative assessment","Summative assessment","Collective assessment","None of the given"],"answer":[0],"explanation":"Formative assessment is frequent, interactive checking of student progress during instruction to identify needs and adjust teaching. Summative assessment comes at the end and judges overall achievement."},{"id":"r2024w10q10","run":"2024","week":"10","wn":10,"n":10,"q":"\"That is an intelligent response, well done\" is an example of a ___ level feedback.","options":["Task-level","Process-level","Facilitator-level","Personal-level"],"answer":[3],"explanation":"In Hattie and Timperley's model, praise directed at the person ('intelligent, well done') is personal or self-level feedback. It says little about the task or process, which is why it is considered the least useful for learning."},{"id":"r2024w11q1","run":"2024","week":"11","wn":11,"n":1,"q":"___ refers to a complex set of mental abilities underlying social stimulus perception, processing, interpretation, and response.","options":["social schema","emotional cognition","social cognition","emotional schema"],"answer":[2],"explanation":"Social cognition is the set of mental abilities used to perceive, process, interpret and respond to social stimuli such as other people's behaviour. A social schema is only one knowledge structure used within it."},{"id":"r2024w11q2","run":"2024","week":"11","wn":11,"n":2,"q":"Piaget's conception of ___ views information inconsistent with an individual's cognitive structures as an initiator for assimilation and accommodation processes.","options":["assimilation and accommodation schema","cognitive determinism","reciprocal dynamism","cognitive conflict"],"answer":[3],"explanation":"Piaget saw cognitive conflict (disequilibrium), the clash between new information and existing schemas, as the trigger for assimilation and accommodation. Reciprocal determinism is Bandura's concept, not Piaget's."},{"id":"r2024w11q3","run":"2024","week":"11","wn":11,"n":3,"q":"During the earliest stages of development, children see the world from their own perspective and struggle to think about how other people may view the world. This highlights that initially, children are","options":["egocentric","idiosyncratic","egoistic","egomaniac"],"answer":[0],"explanation":"Piaget described young children as egocentric: they find it hard to take another person's point of view. This is a cognitive limitation, not selfishness (egoism)."},{"id":"r2024w11q4","run":"2024","week":"11","wn":11,"n":4,"q":"Which of the following is false regarding social cognition?","options":["It develops in childhood and adolescence","When looking at a social situation, any two people may have wildly different interpretations.","It includes complex abilities like theory of mind","There are no cultural differences in social cognition"],"answer":[3],"explanation":"Social cognition is shaped by culture, so the same behaviour can be interpreted differently across cultural settings. Saying there are no cultural differences is therefore false."},{"id":"r2024w11q5","run":"2024","week":"11","wn":11,"n":5,"q":"Social processes influence how information is selected, organized, integrated, and retrieved. This highlights the ___ hypothesis.","options":["social cue","cognitive influence","schema influence","social mediation"],"answer":[1],"explanation":"The cognitive influence hypothesis proposes that social processes shape how information is selected, organised, integrated and later retrieved. The other options are not named hypotheses in this sense."},{"id":"r2024w11q6","run":"2024","week":"11","wn":11,"n":6,"q":"The social cognitive theory is developed by ___.","options":["Watson","Piaget","Bandura","Freud"],"answer":[2],"explanation":"Albert Bandura developed social cognitive theory, which grew out of his social learning theory and stresses observational learning, self-efficacy and reciprocal determinism. Watson was a behaviorist and Piaget a cognitive-developmental theorist."},{"id":"r2024w11q7","run":"2024","week":"11","wn":11,"n":7,"q":"___ refers to the internal or external responses to a person's behavior that affect the likelihood of continuing or discontinuing the behavior.","options":["modeling","schemas","awards","reinforcements"],"answer":[3],"explanation":"Reinforcements are internal or external responses to a behaviour that make it more or less likely to continue. Modeling is learning by observing others, not the consequences of behaviour."},{"id":"r2024w11q8","run":"2024","week":"11","wn":11,"n":8,"q":"Observational learning occurs through the sequence of ___ number of processes. One of those is attentional processes.","options":["four","five","six","seven"],"answer":[0],"explanation":"Bandura described four processes in observational learning: attention, retention, reproduction (production) and motivation. Attentional processes come first."},{"id":"r2024w11q9","run":"2024","week":"11","wn":11,"n":9,"q":"The ___ model of observational learning involves an actual individual demonstrating or acting out a behavior.","options":["live","symbolic","verbal instructional","contextual"],"answer":[0],"explanation":"A live model is an actual person demonstrating the behaviour in front of the learner. Symbolic models appear in media such as films or books, and verbal instructional models describe the behaviour in words."},{"id":"r2024w11q10","run":"2024","week":"11","wn":11,"n":10,"q":"___ suggests that our behavior, personal factors, and environmental factors all influence each other.","options":["environmental dynamism","reciprocal determinism","collective determinism","reciprocal dynamism"],"answer":[1],"explanation":"Bandura's reciprocal determinism holds that behaviour, personal factors and the environment all influence one another in both directions. The other options are not Bandura's terms."},{"id":"r2024w12q1","run":"2024","week":"12","wn":12,"n":1,"q":"Sustainable development is","options":["unidimensional","bidimensional","multidimensional","none of the given"],"answer":[2],"explanation":"Sustainable development combines economic, social and environmental dimensions, so it is multidimensional. It cannot be reduced to one or two dimensions."},{"id":"r2024w12q2","run":"2024","week":"12","wn":12,"n":2,"q":"Revenue generation and resource use are components of","options":["environmental sustainability","social sustainability","financial sustainability","economic sustainability"],"answer":[3],"explanation":"Revenue generation and resource use concern the economic pillar of sustainability, which is about maintaining economic value and productive capacity over time. Financial sustainability is not one of the standard pillars."},{"id":"r2024w12q3","run":"2024","week":"12","wn":12,"n":3,"q":"___ as a practice is defined as solving social problems using market based methods and can create both economic and social value.","options":["social entrepreneurship","economic entrepreneurship","social marketing","social economics"],"answer":[0],"explanation":"Social entrepreneurship uses market-based methods to solve social problems, creating both economic and social value. Social marketing applies marketing techniques to change behaviour rather than building ventures."},{"id":"r2024w12q4","run":"2024","week":"12","wn":12,"n":4,"q":"In the context of sustainability, HESI highlights the role of ___ in building a better world for current and future generations.","options":["Financial stability","Higher education","Climate change","Natural resources"],"answer":[1],"explanation":"The Higher Education Sustainability Initiative (HESI) highlights the role of higher education in building a better, more sustainable world for present and future generations."},{"id":"r2024w12q5","run":"2024","week":"12","wn":12,"n":5,"q":"The following are the outcome targets of SDG 4, except.","options":["Relevant skills for decent work","Gender equality and inclusion","Privatization of institutes","Universal youth literacy"],"answer":[2],"explanation":"SDG 4 targets include relevant skills for decent work, gender equality and inclusion, and universal youth literacy and numeracy. Privatization of institutes is not an SDG 4 target."},{"id":"r2024w12q6","run":"2024","week":"12","wn":12,"n":6,"q":"One of the means to implement SDG 4 is exponentially increasing the number of scholarships available to developing contexts.","options":["False","True"],"answer":[1],"explanation":"One means of implementing SDG 4 (target 4.b) is to substantially expand the number of scholarships available to developing countries. So the statement is true in spirit.","note":"Key 'True' is plausible but the wording is loose: SDG target 4.b says 'substantially expand' scholarships for developing countries, not 'exponentially increase'; a strict reading could make it False."},{"id":"r2024w12q7","run":"2024","week":"12","wn":12,"n":7,"q":"Successful implementation of ESD requires a shift in focus from","options":["feeling to thinking","learning to teaching","teaching to feeling","teaching to learning"],"answer":[3],"explanation":"Education for Sustainable Development calls for learner-centred, action-oriented pedagogy, which moves the focus from teaching to learning.","rep":["2026","2024"],"grp":138},{"id":"r2024w12q8","run":"2024","week":"12","wn":12,"n":8,"q":"___ refers to the ability to understand and evaluate multiple possible futures to deal with risks and changes.","options":["anticipatory competency","collaboration competency","normative competency","systems thinking competency"],"answer":[0],"explanation":"Anticipatory competency is the ability to understand and evaluate multiple futures (possible, probable and desirable) and to deal with risks and change. Normative competency concerns values, and systems thinking concerns relationships within complex systems."},{"id":"r2024w12q9","run":"2024","week":"12","wn":12,"n":9,"q":"Fostering competencies requires integration of three interrelated dimensions of learning as described by UNESCO. Which of the following is not one of them?","options":["biological learning","cognitive learning","behavioral learning","social and emotional learning"],"answer":[0],"explanation":"UNESCO describes three dimensions of learning for ESD: cognitive, social-emotional and behavioural. 'Biological learning' is not one of them."},{"id":"r2024w12q10","run":"2024","week":"12","wn":12,"n":10,"q":"GAP in the context of Education for Sustainable Development stands for","options":["General Activity Priority","Global Action Programme","Global Achievement Programme","General Awareness Programme"],"answer":[1],"explanation":"GAP stands for the Global Action Programme on Education for Sustainable Development (2015-2019), UNESCO's follow-up to the UN Decade of ESD."},{"id":"r2023w1q1","run":"2023","week":"1","wn":1,"n":1,"q":"Psychologists agree that learning results from ___","options":["running","talking","experience","seeing","reacting"],"answer":[2],"explanation":"Learning is a relatively permanent change in behavior or behavior potential that results from experience. Changes caused by maturation, fatigue or injury are not counted as learning."},{"id":"r2023w1q2","run":"2023","week":"1","wn":1,"n":2,"q":"Learning is defined as a ___ change in behavior","options":["temporary","large","small","easy","relatively permanent"],"answer":[4],"explanation":"Learning is defined as a relatively permanent change in behavior (or behavior potential) resulting from experience. Temporary changes such as those due to fatigue or drugs do not count as learning."},{"id":"r2023w1q3","run":"2023","week":"1","wn":1,"n":3,"q":"___ definitions of learning refer to a specific change in mental constructs (e.g., knowledge, representations, associations) of an organism.","options":["Cognitive","Psychodynamic","Experimental","Anthropological","Humanistic"],"answer":[0],"explanation":"Cognitive definitions treat learning as a change in mental constructs such as knowledge, representations and associations, which are then inferred from behavior. Behavioral definitions, by contrast, focus only on observable behavior change."},{"id":"r2023w1q4","run":"2023","week":"1","wn":1,"n":4,"q":"Who among the following was one of the first psychologists to study how learning influences behavior?","options":["Carl Jung","John B. Watson","Sigmund Freud","Albert Einstein","Abraham Maslow"],"answer":[1],"explanation":"John B. Watson, the founder of behaviorism, studied how learning (conditioning) shapes behavior, most famously in the Little Albert experiment. Freud and Jung focused on the unconscious, and Maslow on needs and humanistic psychology."},{"id":"r2023w1q5","run":"2023","week":"1","wn":1,"n":5,"q":"Which of the following is not an outcome of effective learning?","options":["more connected knowledge","more sad and anxious feelings","more reflective approach","more positive emotions","more developed vision of future self as a learner"],"answer":[1],"explanation":"Effective learning leads to more connected knowledge, a more reflective approach, positive emotions and a stronger vision of oneself as a learner. Increased sadness and anxiety are signs of ineffective or stressful learning, not an outcome of effective learning."},{"id":"r2023w1q6","run":"2023","week":"1","wn":1,"n":6,"q":"Learning that consists of adding to existing student knowledge is known as","options":["conceptual growth","conceptual decline","conceptual change","conceptual decay","conceptual budding"],"answer":[0],"explanation":"Conceptual growth means adding new information to an existing knowledge base without needing to restructure it. Conceptual change, in contrast, requires revising or replacing existing (often mistaken) beliefs."},{"id":"r2023w1q7","run":"2023","week":"1","wn":1,"n":7,"q":"What type of feedback to students is important for increasing learning?","options":["Clear, assertive, and delayed","Clear, explanatory, and timely","Ambiguous, explanatory, timely","Strict, assertive, delayed","Clear, harsh, timely"],"answer":[1],"explanation":"Feedback improves learning most when it is clear, explains what was right or wrong and how to improve, and is given promptly. Delayed, ambiguous or harsh feedback is much less useful to the learner."},{"id":"r2023w1q8","run":"2023","week":"1","wn":1,"n":8,"q":"Getting used to of something like the ticking of a wall clock is an example of","options":["Sensitization","Conditioning","Meaningful learning","Habituation","Associative learning"],"answer":[3],"explanation":"Habituation is a non-associative form of learning in which responding to a repeated, harmless stimulus (like a ticking clock) decreases over time. Sensitization is the opposite: increased responding after repeated or intense stimulation."},{"id":"r2023w1q9","run":"2023","week":"1","wn":1,"n":9,"q":"In ___ learning, special emphasis is placed on exchanges of information as a way of enriching work and the confluence of ideas","options":["associative","observational","emotional","non-associative","cooperative"],"answer":[4],"explanation":"Cooperative learning has students work together in small groups, so exchanging information and combining ideas is central to how they learn. Observational learning, by contrast, is learning by watching a model."},{"id":"r2023w1q10","run":"2023","week":"1","wn":1,"n":10,"q":"___ is the process of gradually changing the quality of a response.","options":["Modeling","Cueing","Reinforcement","Shaping","Punishment"],"answer":[3],"explanation":"Shaping reinforces successive approximations of a target behavior, gradually changing the response until the desired behavior is reached. Modeling involves learning by observing others.","rep":["2026","2023"],"grp":25},{"id":"r2023w2q1","run":"2023","week":"2","wn":2,"n":1,"q":"___ established the first psychological laboratory at the University of Leipzig in Germany.","options":["Sigmund Freud","Albert Einstein","Wilhelm Wundt","Aristotle","Carl Jung"],"answer":[2],"explanation":"Wilhelm Wundt founded the first experimental psychology laboratory at the University of Leipzig in 1879, which is often treated as the start of psychology as a science. Freud and Jung were psychoanalysts working in Vienna and Zurich."},{"id":"r2023w2q2","run":"2023","week":"2","wn":2,"n":2,"q":"___ is a theory of learning that uses mind as an information processor, like a computer","options":["Behaviorism","Information Technology","Psychoanalysis","Cognitivism","Motivation"],"answer":[3],"explanation":"Cognitivism views the mind as an information processor, like a computer, that takes in, stores and retrieves information. Behaviorism, in contrast, ignores internal mental processes and focuses on observable behavior."},{"id":"r2023w2q3","run":"2023","week":"2","wn":2,"n":3,"q":"According to Gardner's theory of multiple intelligences, ___ intelligence is about self-knowledge and the ability to act adaptively on the basis of that knowledge","options":["Interpersonal","Spatial","Intrapersonal","Linguistic","Musical"],"answer":[2],"explanation":"In Gardner's theory, intrapersonal intelligence is understanding oneself (one's feelings, strengths and goals) and using that self-knowledge to guide behavior. Interpersonal intelligence is about understanding other people."},{"id":"r2023w2q4","run":"2023","week":"2","wn":2,"n":4,"q":"In the PASS theory of intelligence, PASS stands for ___","options":["Practice, Attention, Selection, Sensation","Planning, Attention-Arousal, Simultaneous and Successive","Processing, Arousal, Simultaneous Selection","Problem solving, Attention, Sensation, Substitution","Perception, Attention, Selection, Sensation"],"answer":[1],"explanation":"Das, Naglieri and Kirby's PASS theory names four cognitive processes: Planning, Attention-Arousal, Simultaneous processing and Successive processing. It is based on Luria's model of brain functioning."},{"id":"r2023w2q5","run":"2023","week":"2","wn":2,"n":5,"q":"Pre-assessment, group based initial instruction, regular formative assessments, corrective instruction, and parallel formative assessments are all components of ___","options":["Mastery learning","Structure of Intellect","Instructional learning","Positive learning","Intelligence"],"answer":[0],"explanation":"These are the components of Bloom's mastery learning: students are pre-assessed, taught, given formative tests, and those who have not mastered the unit get corrective instruction followed by a parallel test before moving on."},{"id":"r2023w2q6","run":"2023","week":"2","wn":2,"n":6,"q":"Which of the following is an approach to learning which suggests that reality is determined by the experiences of the learner?","options":["Constructivism","Cognitivism","Conceptualism","Instructionism","Conceptualization"],"answer":[0],"explanation":"Constructivism holds that learners actively build their own understanding, so reality and knowledge are shaped by the learner's experiences. Cognitivism focuses on internal information processing rather than knowledge construction from experience."},{"id":"r2023w2q7","run":"2023","week":"2","wn":2,"n":7,"q":"___ constructivism is based on the work of Lev Vygotsky.","options":["Cognitive","Behavioral","Motivational","Positive","Social"],"answer":[4],"explanation":"Social constructivism, based on Lev Vygotsky's work, holds that knowledge is built through social interaction, language and culture. Cognitive constructivism is mainly associated with Piaget."},{"id":"r2023w2q8","run":"2023","week":"2","wn":2,"n":8,"q":"Which of the following is not a stage of development as given by Piaget?","options":["Preoperational","Formal operational","Sensory-motor","Post operational","Concrete operational"],"answer":[3],"explanation":"Piaget's four stages are sensorimotor, preoperational, concrete operational and formal operational. There is no 'post operational' stage in his theory."},{"id":"r2023w2q9","run":"2023","week":"2","wn":2,"n":9,"q":"According to Vygotsky, ___ is the gap between what a learner can do independently and what they can do with the help of a more knowledgeable other.","options":["knowledge gap","zone of proximal development","zone of intelligence","intelligence gap","zone of knowledge"],"answer":[1],"explanation":"Vygotsky's zone of proximal development is the gap between what a learner can do alone and what they can achieve with guidance from a more knowledgeable other. Scaffolding is the support given within this zone."},{"id":"r2023w2q10","run":"2023","week":"2","wn":2,"n":10,"q":"___ teaching involves an interactive dialogue between a teacher and a small group of students.","options":["Reciprocal","Instructional","Reinforcing","Corrective","Restricted"],"answer":[0],"explanation":"Reciprocal teaching (Palincsar and Brown) is a dialogue between a teacher and a small group of students in which they take turns leading discussion using four strategies: predicting, questioning, clarifying and summarizing."},{"id":"r2023w3q1","run":"2023","week":"3","wn":3,"n":1,"q":"Researchers have long believed that memories form due to changes in the brain ___","options":["muscles","bones","blood","skull","neurons"],"answer":[4],"explanation":"Memories are thought to be stored through changes in neurons, especially in the strength of synaptic connections between them (e.g., long-term potentiation). Muscles, bones and blood are not where memories are formed."},{"id":"r2023w3q2","run":"2023","week":"3","wn":3,"n":2,"q":"___ refers to calling back the stored information in response to some cue for use in a process or activity","options":["Encoding","Storage","Registration","Retrieval","Forgetting"],"answer":[3],"explanation":"Retrieval is the process of accessing stored information in response to a cue so it can be used. Encoding converts information into a storable form, and storage keeps it over time."},{"id":"r2023w3q3","run":"2023","week":"3","wn":3,"n":3,"q":"The duration of the sensory register is ___","options":["1-3 seconds","1-3 minutes","15-30 seconds","15-30 minutes","1 hour"],"answer":[0],"explanation":"The sensory register holds a large amount of raw sensory information only very briefly, roughly up to 1-3 seconds (visual traces fade in under a second, auditory ones last a little longer). 15-30 seconds is the typical duration of unrehearsed short-term memory."},{"id":"r2023w3q4","run":"2023","week":"3","wn":3,"n":4,"q":"Maintenance rehearsal in the context of short term memory is also known as ___","options":["elaborative rehearsal","rote rehearsal","elaborative encoding","dual coding","visual imagery encoding"],"answer":[1],"explanation":"Maintenance rehearsal, simply repeating information to keep it in short-term memory, is also called rote rehearsal. Elaborative rehearsal is different, as it links the information to meaning and existing knowledge."},{"id":"r2023w3q5","run":"2023","week":"3","wn":3,"n":5,"q":"Which of the following is not a component of the working memory model?","options":["Central executive","Visuo-spatial sketchpad","Language repository","Episodic buffer","Phonological loop"],"answer":[2],"explanation":"Baddeley's working memory model has a central executive, phonological loop, visuo-spatial sketchpad and episodic buffer. There is no 'language repository' component; verbal material is handled by the phonological loop."},{"id":"r2023w3q6","run":"2023","week":"3","wn":3,"n":6,"q":"___ describes our implicit knowledge of tasks that usually do not require conscious recall to perform them","options":["Procedural memory","Declarative memory","Semantic memory","Episodic memory","Collective memory"],"answer":[0],"explanation":"Procedural memory is implicit memory for skills and how to do things, such as riding a bicycle, performed without conscious recall. Declarative memory (semantic and episodic) is explicit memory for facts and events."},{"id":"r2023w3q7","run":"2023","week":"3","wn":3,"n":7,"q":"The Levels of Processing theory in memory is given by -","options":["Atkinson & Shiffrin","Craik & Lockhart","Baddley","Piaget","Freud"],"answer":[1],"explanation":"Fergus Craik and Robert Lockhart proposed the levels of processing theory in 1972, arguing that deeper (semantic) processing produces more durable memories. Atkinson and Shiffrin proposed the multi-store model, and Baddeley the working memory model."},{"id":"r2023w3q8","run":"2023","week":"3","wn":3,"n":8,"q":"___ processing is when we encode only the physical qualities of something.","options":["Phonemic","Structural","Semantic","Deep","Elaborative"],"answer":[1],"explanation":"Structural (shallow) processing encodes only physical features, such as what a word looks like. Phonemic processing encodes sound, and semantic processing encodes meaning, which is the deepest level."},{"id":"r2023w3q9","run":"2023","week":"3","wn":3,"n":9,"q":"___ refers to the cognitive capacity actually allocated to the task.","options":["Mental load","Mental effort","Performance","Capacity load","Task load"],"answer":[1],"explanation":"In cognitive load theory, mental effort is the cognitive capacity actually allocated to a task. Mental load is the load imposed by the task itself, and performance is the outcome achieved."},{"id":"r2023w3q10","run":"2023","week":"3","wn":3,"n":10,"q":"Which of the following is not a helpful way of improving memory?","options":["Writing it down","Repetition","Taking a mental picture","Over-exerting yourself","Attaching meaning to it"],"answer":[3],"explanation":"Writing things down, repetition, visual imagery and attaching meaning are all well-supported memory aids. Over-exerting yourself causes fatigue and stress, which impair rather than improve memory."},{"id":"r2023w4q1","run":"2023","week":"4","wn":4,"n":1,"q":"When there are many possible answers to a solution, we rely on ___ to help us choose the best solution, like trying to answer or solve an open-ended question","options":["luck","divergent thinking","remembering","sensory memory","symbolic thinking"],"answer":[1],"explanation":"Divergent thinking generates many possible ideas or solutions to an open-ended problem, which is why it is used when there is no single correct answer. Convergent thinking narrows down to one correct answer.","note":"Wording mixes ideas: generating many possible answers is divergent thinking, but 'choose the best solution' describes convergent thinking. Key (divergent) fits the open-ended framing."},{"id":"r2023w4q2","run":"2023","week":"4","wn":4,"n":2,"q":"___ are representative items within each concept.","options":["Imaginations","Focuses","Architectures","Prototypes","Images"],"answer":[3],"explanation":"A prototype is the most typical or representative member of a concept or category, and new items are categorized by how closely they resemble it. For example, a robin is a prototypical bird.","rep":["2025","2023"],"grp":174},{"id":"r2023w4q3","run":"2023","week":"4","wn":4,"n":3,"q":"Cognitive, affective, and psychomotor are three learning domains as given by -","options":["Cognitive architectures","Maslow's hierarchy","Bloom's Taxonomy","Propositions","Working memory theory"],"answer":[2],"explanation":"Bloom's taxonomy classifies learning objectives into three domains: cognitive (knowledge and thinking), affective (feelings and attitudes) and psychomotor (physical skills). Maslow's hierarchy concerns motivation and needs."},{"id":"r2023w4q4","run":"2023","week":"4","wn":4,"n":4,"q":"___ knowledge defines knowledge about own knowledge or self-knowledge","options":["Factual","Metacognitive","Cognitive","Procedural","Conceptual"],"answer":[1],"explanation":"Metacognitive knowledge is knowledge about one's own cognition, such as awareness of one's strengths, weaknesses and strategies. In the revised Bloom's taxonomy it is listed alongside factual, conceptual and procedural knowledge."},{"id":"r2023w4q5","run":"2023","week":"4","wn":4,"n":5,"q":"___ is the ability to collect and analyze information to come to a conclusion.","options":["Critical thinking","Metacognition","Intuition","Affective thinking","Learning"],"answer":[0],"explanation":"Critical thinking is the ability to gather and analyze information objectively and evaluate it to reach a reasoned conclusion. Metacognition is thinking about one's own thinking, and intuition reaches conclusions without deliberate analysis."},{"id":"r2023w4q6","run":"2023","week":"4","wn":4,"n":6,"q":"'Think out of the box' refers to which of the following?","options":["Creative thinking","Critical thinking","Reflective thinking","Analytical thinking","Metacognition"],"answer":[0],"explanation":"'Thinking out of the box' means going beyond conventional ways of thinking to produce novel, original ideas, which is creative thinking. Critical and analytical thinking evaluate and break down existing information."},{"id":"r2023w4q7","run":"2023","week":"4","wn":4,"n":7,"q":"Which of the following is not a stage of the creative thinking process?","options":["Elaboration","Evaluation","Preparation","Insight","Information"],"answer":[4],"explanation":"The creative process is usually described as preparation, incubation, insight, evaluation and elaboration. Gathering information happens within the preparation stage, but 'information' is not itself a stage."},{"id":"r2023w4q8","run":"2023","week":"4","wn":4,"n":8,"q":"___ is a method of problem solving in which possible solutions are tried until one is successful.","options":["Analogy","Trial and error","Chance","Algorithm","Creativity"],"answer":[1],"explanation":"Trial and error means trying possible solutions one after another until one works. An algorithm, in contrast, is a step-by-step procedure that guarantees a solution."},{"id":"r2023w4q9","run":"2023","week":"4","wn":4,"n":9,"q":"In the traditional approach to learning, a student's role is ___","options":["passive","active","experiential","absent","unrecognized"],"answer":[0],"explanation":"In the traditional, teacher-centered approach, the teacher transmits knowledge and the student passively receives it. Active and experiential roles are features of constructivist, learner-centered approaches."},{"id":"r2023w4q10","run":"2023","week":"4","wn":4,"n":10,"q":"___ are versatile graphic organizers that can represent many different forms of relationships between concepts.","options":["Prototypes","Concepts","Emotional maps","Cognitive aids","Cognitive maps"],"answer":[4],"explanation":"Cognitive maps (including concept maps and mind maps) are flexible graphic organizers that visually show relationships between concepts. Prototypes are typical examples of a category, not diagrams."},{"id":"r2023w5q1","run":"2023","week":"5","wn":5,"n":1,"q":"Which of the following is not a major component of motivation?","options":["Activation","Confusion","Persistence","Intensity","Direction"],"answer":[1],"explanation":"Motivation is usually described in terms of activation (starting a behavior), persistence (continuing despite obstacles), intensity (vigor of effort) and direction (the goal being pursued). Confusion is not a component of motivation."},{"id":"r2023w5q2","run":"2023","week":"5","wn":5,"n":2,"q":"___ refers to doing something or behaving well because one feels an internal pressure to do so.","options":["Identified regulation","Amotivation","Introjected regulation","Curiosity","Motivational learning"],"answer":[2],"explanation":"Introjected regulation is a partly internalized form of extrinsic motivation in which a person acts because of internal pressure such as guilt, anxiety or ego. Identified regulation means acting because one personally values the outcome."},{"id":"r2023w5q3","run":"2023","week":"5","wn":5,"n":3,"q":"___ drives are often referred to as 'tertiary drives'.","options":["Biological","Psychological","Social","Hunger","None of the above"],"answer":[2],"explanation":"Drives are often grouped as primary (biological, such as hunger), secondary (learned or psychological) and tertiary (social drives such as affiliation and approval). This course refers to social drives as tertiary drives."},{"id":"r2023w5q4","run":"2023","week":"5","wn":5,"n":4,"q":"Incentive theory of motivation is based on the concept of ___","options":["Operant conditioning","Classical conditioning","Memory","Forgetting","Drive theory"],"answer":[0],"explanation":"Incentive theory holds that behavior is pulled by external rewards and incentives, which comes from the operant conditioning idea that behavior is shaped by its consequences. Drive theory, by contrast, explains behavior as being pushed by internal tension."},{"id":"r2023w5q5","run":"2023","week":"5","wn":5,"n":5,"q":"The Yerkes Dodson law gives a relationship between ___ and ___","options":["arousal, performance","intelligence, stress","stress, happiness","learning, marks","None of the above"],"answer":[0],"explanation":"The Yerkes-Dodson law describes an inverted-U relationship between arousal and performance: performance is best at a moderate level of arousal and drops when arousal is too low or too high."},{"id":"r2023w5q6","run":"2023","week":"5","wn":5,"n":6,"q":"The letter 'M' in the acronym 'SMART' used in the context of goal setting stands for -","options":["measurable","microscopic","maintained","motivated","none of the above"],"answer":[0],"explanation":"In SMART goals, M stands for Measurable, meaning progress and success can be tracked with clear criteria. SMART is Specific, Measurable, Achievable, Relevant and Time-bound."},{"id":"r2023w5q7","run":"2023","week":"5","wn":5,"n":7,"q":"Maslow's need hierarchy has ___ number of stages.","options":["Two","Three","Seven","Four","Five"],"answer":[4],"explanation":"Maslow's classic hierarchy has five levels: physiological, safety, love and belonging, esteem, and self-actualization. Later expanded versions add more levels, but the standard model has five."},{"id":"r2023w5q8","run":"2023","week":"5","wn":5,"n":8,"q":"What are the three psychological needs highlighted by the self determination theory?","options":["Autonomy, Comfort, Rationalization","Autonomy, Competence, Relatedness","Attention, Comfort, Relationship","Attention, Competence, Relationship","None of the above"],"answer":[1],"explanation":"Self-determination theory (Deci and Ryan) identifies three basic psychological needs: autonomy, competence and relatedness. Meeting these needs supports intrinsic and autonomous motivation."},{"id":"r2023w5q9","run":"2023","week":"5","wn":5,"n":9,"q":"Which of the following is not an example of esteem needs in the context of Maslow's hierarchy?","options":["sleep","achievement","education","respect","competence"],"answer":[0],"explanation":"Sleep is a physiological need at the base of Maslow's hierarchy. Achievement, respect and competence (and the recognition that education brings) relate to esteem needs.","note":"'Education' is not a standard esteem need in Maslow's hierarchy, but 'sleep' is clearly physiological, so the key is still the only clear answer."},{"id":"r2023w5q10","run":"2023","week":"5","wn":5,"n":10,"q":"Achievement motivation stems from two needs: need to achieve and need to ___","options":["enjoy","relax","avoid failure","be respected","seek attention"],"answer":[2],"explanation":"Atkinson's theory of achievement motivation says it results from the tension between the need to achieve success and the need to avoid failure. The balance between them influences how challenging a task a person chooses."},{"id":"r2023w6q1","run":"2023","week":"6","wn":6,"n":1,"q":"Who among the following is given major credit for the popularization of the term 'Emotional Intelligence'?","options":["Dr. Abraham Maslow","Dr. Carl Jung","Dr. Daniel Goleman","Dr. John Mayer","Dr. Sigmund Freud"],"answer":[2],"explanation":"Daniel Goleman's 1995 bestseller 'Emotional Intelligence' brought the term to a mass audience, so he gets major credit for popularizing it. John Mayer (with Peter Salovey) coined and formally defined the concept earlier, but did not popularize it."},{"id":"r2023w6q2","run":"2023","week":"6","wn":6,"n":2,"q":"Which of the following is not a component of emotional intelligence?","options":["Self-awareness","Self-regulation","Knowledge","Motivation","Empathy"],"answer":[2],"explanation":"Goleman's model has five components: self-awareness, self-regulation, motivation, empathy and social skills. Knowledge is a cognitive attribute, not a component of emotional intelligence."},{"id":"r2023w6q3","run":"2023","week":"6","wn":6,"n":3,"q":"____ refers to the ability of putting words to feelings.","options":["Emotional literacy","Emotional testing","Social knowledge","Emotional ability","Emotional aptitude"],"answer":[0],"explanation":"Emotional literacy is the ability to recognize, understand and name one's feelings, i.e. to put words to emotions. It is a foundation for expressing and regulating emotions appropriately."},{"id":"r2023w6q4","run":"2023","week":"6","wn":6,"n":4,"q":"The following are signs of emotional intelligence, except","options":["The ability to let go of mistakes","Feelings of empathy and concern for others","An awareness of personal strengths and limitations","Self-confidence and self-acceptance","Not taking responsibility for one's mistakes"],"answer":[4],"explanation":"Emotionally intelligent people own their mistakes, learn from them and then let them go. Refusing to take responsibility for one's mistakes is the opposite of emotional intelligence, while the other options are typical signs of it."},{"id":"r2023w6q5","run":"2023","week":"6","wn":6,"n":5,"q":"According to Hochschild, the ____ are attempts by organizations to control employees' inner lives or thoughts and feelings; e.g. in the case of flight attendants.","options":["feeling rules","emotional syntax","emotional norms","feeling norms","None of the above"],"answer":[0],"explanation":"Arlie Hochschild, in her study of flight attendants, described feeling rules as the organization's expectations about which emotions employees should feel and display. Through such rules organizations try to manage workers' inner feelings, which is the basis of emotional labor."},{"id":"r2023w6q6","run":"2023","week":"6","wn":6,"n":6,"q":"____ occurs when someone's emotions and related behaviors lead to similar emotions and behaviors in others.","options":["Deep acting","Emotional domino","Surface acting","Emotional contagion","Emotional norms"],"answer":[3],"explanation":"Emotional contagion is the spread of emotions and related behaviors from one person to others, as when one person's cheerfulness or anxiety 'catches on' in a group. Surface and deep acting are emotional labor strategies, not contagion."},{"id":"r2023w6q7","run":"2023","week":"6","wn":6,"n":7,"q":"The biological explanation of emotional contagion can be through the existence of ____","options":["emotional neurons","emotional nerves","feeling neurons","heart","mirror neurons"],"answer":[4],"explanation":"Mirror neurons fire both when we perform an action and when we observe someone else performing it, so they are thought to underlie automatic mimicry of others' expressions and emotions. This offers a biological basis for emotional contagion."},{"id":"r2023w6q8","run":"2023","week":"6","wn":6,"n":8,"q":"Which of the following is not one of three main areas of general creativity?","options":["nonverbal and verbal creativity","biological creativity","creativity in problem solving","emotional creativity"],"answer":[1],"explanation":"The three main areas of general creativity discussed are nonverbal and verbal creativity, creativity in problem solving, and emotional creativity. 'Biological creativity' is not one of them."},{"id":"r2023w6q9","run":"2023","week":"6","wn":6,"n":9,"q":"'A breakup gives rise to song lyrics' is an example of how ____","options":["emotions can inspire creativity","heartbreak can inspire emotional intelligence","emotional intelligence is lowered","none of the above"],"answer":[0],"explanation":"Writing song lyrics after a breakup shows strong emotions acting as fuel for creative expression. It illustrates that emotions can inspire creativity, not anything about emotional intelligence rising or falling."},{"id":"r2023w6q10","run":"2023","week":"6","wn":6,"n":10,"q":"Which of the following is false?","options":["Emotional intelligence can predict academic performance and workplace success","Meditation or journal keeping can be effective strategies to improve self-awareness","Emotional intelligence cannot be learnt or improved through training; it is genetic.","Improving communication skills aids in improving conflict resolution.","None of the above"],"answer":[2],"explanation":"Emotional intelligence is not fixed by genes; skills such as self-awareness, empathy and self-regulation can be learned and improved through training and practice. The other statements are true, so the genetic claim is the false one."},{"id":"r2023w7q1","run":"2023","week":"7","wn":7,"n":1,"q":"Which of the following is not a component of Benjamin S. Bloom's taxonomy of educational objectives?","options":["Cognitive","Affective","Psychomotor","Biological","None of the above"],"answer":[3],"explanation":"Bloom's taxonomy of educational objectives has three domains: cognitive (knowledge), affective (attitudes and feelings) and psychomotor (physical skills). 'Biological' is not a domain."},{"id":"r2023w7q2","run":"2023","week":"7","wn":7,"n":2,"q":"Which of the following is not included in the major schools of learning theories?","options":["Behaviorist orientation","Cognitive orientation","Humanistic orientation","Social and social-constructivist orientations","Biological and evolutionary orientation"],"answer":[4],"explanation":"The major schools of learning theory covered are the behaviorist, cognitive, humanistic, and social/social-constructivist (situational) orientations. A biological and evolutionary orientation is not among them."},{"id":"r2023w7q3","run":"2023","week":"7","wn":7,"n":3,"q":"Which of the following affect learning?","options":["Task variables","Environmental variables","Individual variables","All of the above"],"answer":[3],"explanation":"Learning is influenced by task variables (e.g. task demands, trainer, communication), environmental variables (e.g. ambience, space) and individual variables (e.g. abilities, motivation). So all of the above affect learning."},{"id":"r2023w7q4","run":"2023","week":"7","wn":7,"n":4,"q":"Which of the following is not a task variable?","options":["Trainer's competence","Communication gap","Rationality","Task overload","Learning capabilities"],"answer":[4],"explanation":"Learning capabilities belong to the learner, so they are an individual variable. Trainer's competence, communication gap, rationality and task overload relate to the task and its delivery, so they are treated as task variables."},{"id":"r2023w7q5","run":"2023","week":"7","wn":7,"n":5,"q":"____ learning refers to learning that gets students to learn through doing; such as experimentation and play","options":["Active","Passive","Deep","Shallow","None of the above"],"answer":[0],"explanation":"Active learning engages students directly through doing, such as experimentation, discussion and play, rather than passively receiving information. Passive learning is the opposite, as in simply listening to a lecture."},{"id":"r2023w7q6","run":"2023","week":"7","wn":7,"n":6,"q":"____ learners favor educational lessons that include peer work or participation.","options":["Social/linguistic","Solitary","Kinesthetic","Auditory","Visual"],"answer":[0],"explanation":"Social (interpersonal) learners prefer learning with others, so they favor lessons involving peer work, group discussion and participation. Solitary learners, by contrast, prefer to work alone."},{"id":"r2023w7q7","run":"2023","week":"7","wn":7,"n":7,"q":"Which of the following is not true for effective instruction?","options":["It is interactive","It is eclectic","It is generative and dynamic","It incorporates components of core curriculum","It is independent of the success of the learning experience"],"answer":[4],"explanation":"Effective instruction is judged by whether learning actually happens; it is interactive, eclectic, generative and dynamic, and tied to the core curriculum. Saying it is independent of the success of the learning experience is therefore untrue."},{"id":"r2023w7q8","run":"2023","week":"7","wn":7,"n":8,"q":"The following are principles of instruction given by Merrill, except ____","options":["Activation","Formation","Demonstration","Integration","Application"],"answer":[1],"explanation":"Merrill's First Principles of Instruction are problem-centered (task-centered) learning, activation, demonstration, application and integration. 'Formation' is not one of them."},{"id":"r2023w7q9","run":"2023","week":"7","wn":7,"n":9,"q":"Which of the following is a principle of Instructional Systems Design (ISD)?","options":["It should move at an efficient pace","It should keep information outside of context","It should be independent of the community","It should create opportunities for learners to replicate past work and output"],"answer":[0],"explanation":"ISD principles call for instruction that moves at an efficient pace, presents information in meaningful context, connects to the learners' community and encourages new application rather than mere replication. Only 'it should move at an efficient pace' fits."},{"id":"r2023w7q10","run":"2023","week":"7","wn":7,"n":10,"q":"According to Ausubel, ____ occurs when new information is integrated into existing knowledge structures, also known as mental schemas.","options":["structural learning","mental learning","meaningful learning","integrative learning","None of the above"],"answer":[2],"explanation":"Ausubel's meaningful learning occurs when new information is linked to and integrated with relevant concepts already present in the learner's cognitive structure (schemas). He contrasted this with rote learning, which is memorized without such links."},{"id":"r2023w8q1","run":"2023","week":"8","wn":8,"n":1,"q":"Which of the following is not a pedagogical approach in teaching?","options":["Collaborative approach","Inquiry-based approach","Constructivist approach","Refractive approach","Integrative approach"],"answer":[3],"explanation":"Collaborative, inquiry-based, constructivist and integrative approaches are recognized pedagogical approaches in teaching. A 'refractive approach' is not one; refraction is a physics term."},{"id":"r2023w8q2","run":"2023","week":"8","wn":8,"n":2,"q":"Constructivism with respect to learning suggests that ____","options":["the role of learners is passive","learners are the makers of meaning and knowledge","facilitators are the makers of meaning and knowledge","internet is the maker of meaning and knowledge","none of the above"],"answer":[1],"explanation":"Constructivism holds that learners actively construct their own meaning and knowledge by connecting new experiences to what they already know. Learners are not passive recipients, and the teacher acts as a facilitator rather than the source of meaning."},{"id":"r2023w8q3","run":"2023","week":"8","wn":8,"n":3,"q":"Which of the following is false about pedagogy in education and learning?","options":["Effective pedagogies are an amalgamation of various teaching techniques","Pedagogy is based on a facilitator-centered approach","Pedagogy allows teachers to evaluate individual students' performance regularly","Pedagogy allows students to meet like-minded people and learn from their peers","None of the above"],"answer":[1],"explanation":"Modern pedagogy is learner-centered: it puts students' needs, participation and construction of knowledge at the center, with the teacher as facilitator. Describing it as facilitator-centered is therefore false, while the other statements are true."},{"id":"r2023w8q4","run":"2023","week":"8","wn":8,"n":4,"q":"Which of the following is not a major component of the experiential learning process?","options":["Generalizing","Experiencing","Analyzing","Sharing","Overthinking","Applying"],"answer":[4],"explanation":"The experiential learning process is commonly described as experiencing, sharing, analyzing (processing), generalizing and applying. 'Overthinking' is not a component."},{"id":"r2023w8q5","run":"2023","week":"8","wn":8,"n":5,"q":"David Kolb's experiential learning style theory typically suggests ____ number of stages in the experiential learning cycle.","options":["Four","Nine","Fifteen","Seven","None of the above"],"answer":[0],"explanation":"Kolb's experiential learning cycle has four stages: concrete experience, reflective observation, abstract conceptualization and active experimentation. Learners move around this cycle as they learn."},{"id":"r2023w8q6","run":"2023","week":"8","wn":8,"n":6,"q":"The stages of the experiential learning cycle given by Kolb are dissected by two continuums relating to perception and ____","options":["emotion","motivation","processing","perseveration","none of the above"],"answer":[2],"explanation":"Kolb's cycle is organized by two continuums: the perception continuum (feeling versus thinking, how we grasp experience) and the processing continuum (doing versus watching, how we transform it). Combining them yields the four learning styles."},{"id":"r2023w8q7","run":"2023","week":"8","wn":8,"n":7,"q":"The ____ learning style as given by Kolb suggests that these individuals prefer technical tasks and like to be left alone to solve them.","options":["Assimilating","Accommodating","Diverging","Converging"],"answer":[3],"explanation":"Converging (thinking and doing) learners like to apply ideas to practical problems and prefer technical tasks over interpersonal ones. They are happy to work out solutions on their own, unlike accommodators, who rely on others and gut feeling."},{"id":"r2023w8q8","run":"2023","week":"8","wn":8,"n":8,"q":"The model of multimedia learning is based upon some primary assumptions as given by Mayer that are mentioned below. Which of the following is false?","options":["Visual and auditory experiences/information are processed through separate and distinct information processing 'channels'","Each information processing channel is limited in its ability to process experience/information","Processing experience/information in channels is an active cognitive process designed to construct coherent mental representations","None of the above"],"answer":[3],"explanation":"Mayer's cognitive theory of multimedia learning rests on three assumptions: dual channels (separate visual and auditory channels), limited capacity of each channel, and active processing to build coherent mental representations. All three statements are true, so none is false."},{"id":"r2023w8q9","run":"2023","week":"8","wn":8,"n":9,"q":"The ____ principle of multimedia learning suggests that students learn better when corresponding words and pictures are presented simultaneously rather than successively","options":["temporal contiguity","spatial contiguity","modality","coherence","redundancy"],"answer":[0],"explanation":"Mayer's temporal contiguity principle states that people learn better when corresponding words and pictures are presented at the same time rather than one after the other. Spatial contiguity, by contrast, concerns placing words near the pictures they describe on the page or screen."},{"id":"r2023w8q10","run":"2023","week":"8","wn":8,"n":10,"q":"Mezirow(1978) identified ____ number of steps that are required for transformative learning to occur.","options":["Four","Five","Seven","Ten","Thirteen"],"answer":[3],"explanation":"Jack Mezirow described ten phases of transformative learning, starting with a disorienting dilemma and moving through self-examination, critical assessment of assumptions and planning, to reintegrating the new perspective into one's life."},{"id":"r2023w9q1","run":"2023","week":"9","wn":9,"n":1,"q":"Which of the following is not a feature of e-learning?","options":["individualization","accessibility","personalization","stereotypical","social justice"],"answer":[3],"explanation":"E-learning is valued for individualization, personalization, accessibility and wider access to education (social justice). 'Stereotypical' is the opposite of its tailored, individualized nature."},{"id":"r2023w9q2","run":"2023","week":"9","wn":9,"n":2,"q":"Many students in the context of a digital classroom regard knowledge of ____ as more important than 'what'.","options":["'who'","'why not'","'where'","'how to'","none of the above"],"answer":[3],"explanation":"In a digital classroom, where facts are easy to look up online, students tend to value knowing 'how to' find, use and apply information over knowing 'what' (factual content)."},{"id":"r2023w9q3","run":"2023","week":"9","wn":9,"n":3,"q":"Which of the following is not a benefit of e-learning?","options":["It accommodates everybody's needs","It is self-paced","It is motivating and interactive","It is scalable","None of the above"],"answer":[2],"explanation":"Accommodating everyone's needs, being self-paced and being scalable are standard listed benefits of e-learning. It is not automatically motivating and interactive; keeping learners motivated and engaged is in fact a known challenge, so this is the keyed non-benefit.","note":"Ambiguous: being motivating and interactive is often listed as an e-learning benefit; the key presumably treats it as a non-benefit because sustaining motivation is a known e-learning challenge."},{"id":"r2023w9q4","run":"2023","week":"9","wn":9,"n":4,"q":"When we are learning or practicing something, our brain ____","options":["does not do anything","releases hormones","builds strong connections between the muscles and bones","builds strong connections between neurons"],"answer":[3],"explanation":"Learning and practice strengthen synaptic connections between neurons, and repeated activation makes these neural pathways more efficient (neuroplasticity). It is not about muscles and bones, and hormone release is not the key process."},{"id":"r2023w9q5","run":"2023","week":"9","wn":9,"n":5,"q":"The ____ theory suggests that when we overload our working memory, we are unable to acquire and process new information.","options":["cognitive load","emotional labor","memory","psychological stress","None of the above"],"answer":[0],"explanation":"Sweller's cognitive load theory holds that working memory has limited capacity; when it is overloaded, learners cannot process and acquire new information effectively. Good instructional design therefore tries to reduce unnecessary load."},{"id":"r2023w9q6","run":"2023","week":"9","wn":9,"n":6,"q":"The brain often benefits from physically writing in a notebook since it contributes to ____. Learners during e-learning are hence often advised to take notes.","options":["emotion","motivation","encoding","forgetting","decoding"],"answer":[2],"explanation":"Writing notes by hand makes learners process and summarize the material, which strengthens encoding into memory. That is why taking notes is recommended during e-learning."},{"id":"r2023w9q7","run":"2023","week":"9","wn":9,"n":7,"q":"In the context of virtual learning, ____ refers to the speed and ease with which a novice user can achieve proficiency with the system.","options":["Efficiency","Memorability","Novice index","Learnability","None of the above"],"answer":[3],"explanation":"In usability terms, learnability is how quickly and easily a new user can become proficient with a system. Efficiency refers to how fast experienced users work, and memorability to how easily users regain proficiency after a break."},{"id":"r2023w9q8","run":"2023","week":"9","wn":9,"n":8,"q":"Which of the following is not a critical factor that impacts e-learning?","options":["Motivation","Self-discipline","Stress","Social skills","Genes"],"answer":[4],"explanation":"Motivation, self-discipline, stress and social skills all affect how well learners manage and benefit from e-learning. Genes are not identified as a critical factor."},{"id":"r2023w9q9","run":"2023","week":"9","wn":9,"n":9,"q":"In the context of instructional design, ____ refers to learners' automatic performance on specific procedures with predetermined steps to be followed.","options":["chaining","association","discrimination","none of the above"],"answer":[0],"explanation":"In instructional design, chaining means linking a series of steps in a fixed sequence so that the learner performs the whole procedure automatically. Association and discrimination concern linking stimuli and telling stimuli apart, not automatic step-by-step procedures."},{"id":"r2023w9q10","run":"2023","week":"9","wn":9,"n":10,"q":"____ provides the context to learners in the form of simulated job-related situations where learners have to judge a situation, use the information they have at hand, and make the best possible choice to solve the problem.","options":["Problem-focused e-learning","Scenario-based e-learning","Guided e-learning","None of the above"],"answer":[1],"explanation":"Scenario-based e-learning places learners in realistic, simulated job situations where they must judge the situation, use the information available and choose the best response. This builds decision-making and problem-solving skills in context."},{"id":"r2023w10q1","run":"2023","week":"10","wn":10,"n":1,"q":"Which of the following is not an essential skill needed for today's teacher (post pandemic era)","options":["digital skills","communication","life skills","non-inclusive education","participative education"],"answer":[3],"explanation":"Post-pandemic teachers need digital skills, communication, life skills and the ability to run participative, inclusive classrooms. Non-inclusive education is not a skill but a practice to avoid."},{"id":"r2023w10q2","run":"2023","week":"10","wn":10,"n":2,"q":"The following psychological principles about how students think and learn are true except","options":["Students' cognitive development and learning is not limited by the general stages of development","Students existing knowledge is not related to and does not impact their present learning","The beliefs or perceptions students have about their intelligence and ability affect their learning and cognitive functioning","Learning is context-based"],"answer":[1],"explanation":"According to the APA's principles for teaching and learning, students' prior knowledge strongly affects new learning, so saying it does not impact present learning is false. The other statements match the principles: development is not limited by general stages, beliefs about intelligence affect learning, and learning is context-based."},{"id":"r2023w10q3","run":"2023","week":"10","wn":10,"n":3,"q":"Which of the following is true regarding the social and emotional learning of students?","options":["Learning is situated in a single isolated social context","Interpersonal relationships are unimportant for development of students","Emotional well-being impacts students' educational performance","None of the above"],"answer":[2],"explanation":"Social and emotional learning recognizes that emotional well-being strongly influences students' performance and learning. Learning is situated in multiple social contexts, and interpersonal relationships are important for students' development."},{"id":"r2023w10q4","run":"2023","week":"10","wn":10,"n":4,"q":"Learners who have a ____ believe that intelligence is malleable and success is related to effort level","options":["communication","academic intelligence","fixed mindset","intelligent mindset","growth mindset"],"answer":[4],"explanation":"Dweck's growth mindset is the belief that intelligence can be developed and that success depends on effort and strategy. A fixed mindset treats intelligence as an unchangeable trait."},{"id":"r2023w10q5","run":"2023","week":"10","wn":10,"n":5,"q":"Acquiring long-term knowledge and skill is largely dependent on ____","options":["practice","good luck","genes","money","None of the above"],"answer":[0],"explanation":"Long-term knowledge and skill depend largely on practice, especially deliberate, spaced practice with feedback. Luck, genes and money are not the main determinants in the APA principles."},{"id":"r2023w10q6","run":"2023","week":"10","wn":10,"n":6,"q":"Use of ____ goals increase self-efficacy and competency towards larger goals.","options":["ambiguous","extremely challenging","extremely non-challenging","proximal","none of the above"],"answer":[3],"explanation":"Proximal (short-term, specific, moderately challenging) goals give learners frequent success experiences, which build self-efficacy and competence toward larger, distal goals. Ambiguous or extremely hard or easy goals do not have this effect."},{"id":"r2023w10q7","run":"2023","week":"10","wn":10,"n":7,"q":"The following are examples of formative assessment except ____","options":["anecdotal records","essays","lab reports","entrance tests"],"answer":[3],"explanation":"Anecdotal records, essays and lab reports can be used during instruction to monitor progress and give feedback, which is formative assessment. Entrance tests are given before instruction for selection or placement, so they are not formative."},{"id":"r2023w10q8","run":"2023","week":"10","wn":10,"n":8,"q":"Summative assessment is conducted ____","options":["during instruction","before instruction","before and during instruction","after instruction"],"answer":[3],"explanation":"Summative assessment is conducted after instruction (at the end of a unit, course or term) to evaluate what students have learned. Assessment during instruction is formative, and assessment before instruction is diagnostic."},{"id":"r2023w10q9","run":"2023","week":"10","wn":10,"n":9,"q":"Which of the following is not an appropriate principle of good feedback practice?","options":["Aims to hamper self-reflection","Provides opportunities to close the gap between current and desired performance","Helps clarify what good performance is","Provides information to teachers that can be used to help shape the teaching","Encourages positive motivational beliefs and self-esteem"],"answer":[0],"explanation":"Good feedback practice (Nicol and Macfarlane-Dick) aims to facilitate self-assessment and reflection, clarify good performance, help close the performance gap, inform teaching and support motivation and self-esteem. Hampering self-reflection contradicts these principles."},{"id":"r2023w10q10","run":"2023","week":"10","wn":10,"n":10,"q":"Which of the following is not one of the levels of feedback?","options":["Task-level","Process-level","Facilitator-level","Personal-level"],"answer":[2],"explanation":"Hattie and Timperley describe four levels of feedback: task, process, self-regulation and self (personal). 'Facilitator-level' is not one of them."}];
